(3440,76,'custom','Click the Edit icon for a product where Actual Yard Stock (PCS) is greater than 0 and Stock on Sales Order (PCS) is equal to 0','xpath=//body','import re

def to_number(txt):
    txt = (txt or "").replace(",", "").strip()
    m = re.search(r"[-+]?\\d+(?:\\.\\d+)?", txt)
    return float(m.group()) if m else 0.0

grid = page.locator("div[role=\'grid\']").filter(
    has=page.locator("[data-field=\'actualYardStockPCS\']")
).first

scroller = grid.locator(".MuiDataGrid-virtualScroller")

found = False

for _ in range(50):

    rows = grid.locator("div[role=\'row\'][data-rowindex]")

    for i in range(rows.count()):

        try:
            row = rows.nth(i)

            actual_pcs = to_number(
                row.locator(
                    "[data-field=\'actualYardStockPCS\']"
                ).text_content(timeout=2000)
            )

            stock_so_pcs = to_number(
                row.locator(
                    "[data-field=\'StockOnSoPCS\']"
                ).text_content(timeout=2000)
            )

            print(actual_pcs, stock_so_pcs)

            if actual_pcs > 30 and stock_so_pcs == 0:

                print("MATCH FOUND")

                row.locator(
                    "[data-field=\'edit\'] button[title=\'Edit\']"
                ).click(force=True)

                found = True
                break

        except:
            continue

    if found:
        break

    scroller.evaluate("(el) => el.scrollTop += 1500")
    page.wait_for_timeout(1000)

assert found, \\
    "No row found where Actual Yard Stock (PCS) > 30 and Stock on S/O (PCS)=0"','2026-05-06 18:52:06','2026-08-21 09:15:15','user','User','PENDING',21,1),
(3441,76,'action','Click the product Checkbox','xpath=//input[@type=\'checkbox\' and @aria-label=\'Select row\']',NULL,'2026-05-06 19:05:07','2026-08-21 09:15:15','user','User','PENDING',22,1),
(3443,76,'custom','Verify Item to Produce grid contains 2 rows and at least one row has Length value as 20.00','xpath=//body','grid = page.locator(\'div[role="grid"][aria-colcount="7"]\')

rows = grid.locator(
    \'div[class*="MuiDataGrid-virtualScrollerRenderZone"] div[role="row"][data-rowindex]\'
)

expect(rows).to_have_count(2)

lengths = rows.locator(
    \'div[role="gridcell"][data-field="length"]\'
).all_inner_texts()

print(lengths)

# true if any row has 20.00
has20 = any(
    abs(float(str(t).strip()) - 20.0) < 0.01
    for t in lengths
)

assert has20, "No row found with Length = 20.00"','2026-05-06 19:22:45','2026-08-21 09:16:22','user','User','PENDING',30,1),
(3444,76,'custom','verify the Cutting BOM is created, the Cutting BOM overlay is displayed, and the grid shows Length "20.00" FT','xpath=//body','import re
from playwright.sync_api import expect

# Dialog
dialog = page.get_by_role("dialog")

# Wait until "Cutting Detail Bom# <number>" title is displayed
title = dialog.locator("h2").first

expect(title).to_have_text(
    re.compile(r"^Cutting Detail Bom#\\s*\\d+\\s*$"),
    timeout=30000
)

# Title validation
title_text = title.inner_text().strip()

assert re.search(
    r"^Cutting Detail Bom#\\s*\\d+\\s*$",
    title_text
), f"Unexpected title: {title_text}"

# Length cells directly
length_cells = dialog.locator(
    \'div[role="gridcell"][data-field="length"]\'
)

# Wait until length data is available
expect(length_cells.first).to_be_visible(timeout=30000)

# Get all length values
length_texts = length_cells.all_inner_texts()

print("Lengths:", length_texts)

# PASS if any row has 20.00
has_20 = any(
    abs(float(t.strip()) - 20.0) < 0.01
    for t in length_texts
)

assert has_20, \\
    f"No row found with Length 20.00. Found: {length_texts}"','2026-05-06 19:25:53','2026-08-24 05:17:55','user','User','PENDING',33,1),
