(3831,40,'custom','Click the Edit icon for a product where Actual Yard Stock (PCS) is greater than 0 and Stock on Sales Order (PCS) is equal to 0','xpath=//body','import re


def to_number(txt):
    txt = (txt or "").replace(",", "").strip()
    m = re.search(r"[-+]?\\d+(?:\\.\\d+)?", txt)
    return float(m.group()) if m else 0.0


# ============================================================
# Main inventory grid: LBS grid
# ============================================================

grid = page.locator(
    "div[role=\'grid\']"
).filter(
    has=page.locator("[data-field=\'actualYardStockLBS\']")
).first

grid.wait_for(
    state="visible",
    timeout=30000
)

scroller = grid.locator(
    ".MuiDataGrid-virtualScroller"
)

scroller.wait_for(
    state="attached",
    timeout=30000
)


found = False


# ============================================================
# Search rows
# ============================================================

for _ in range(50):

    rows = grid.locator(
        "div[role=\'row\'][data-rowindex]"
    )

    for i in range(rows.count()):

        try:
            row = rows.nth(i)

            actual_lbs = to_number(
                row.locator(
                    "[data-field=\'actualYardStockLBS\']"
                ).text_content(timeout=2000)
            )

            stock_so_lbs = to_number(
                row.locator(
                    "[data-field=\'stockOnSoLBS\']"
                ).text_content(timeout=2000)
            )

            print(
                f"Actual LBS: {actual_lbs} | "
                f"Stock on S/O LBS: {stock_so_lbs}"
            )


            # ====================================================
            # Skip unwanted Actual LBS value
            # ====================================================

            if abs(actual_lbs - 2800028000) < 0.01:
                print(
                    "SKIP ROW - "
                    "Actual Yard Stock (LBS) = 2,800,028,000"
                )
                continue


            # ====================================================
            # Matching condition
            # ====================================================

            if actual_lbs > 30 and stock_so_lbs == 0:

                # -----------------------------------------------
                # Get Product ID from SAME row
                # -----------------------------------------------

                product_id_cell = row.locator(
                    "[data-field=\'idCol\']"
                )

                product_id = product_id_cell.get_attribute(
                    "title"
                )

                if not product_id:
                    product_id = product_id_cell.text_content()

                product_id = (product_id or "").strip()


                # -----------------------------------------------
                # Print matched row details
                # -----------------------------------------------

                print("MATCH FOUND")
                print(f"Product ID: {product_id}")
                print(
                    f"Actual Yard Stock (LBS): {actual_lbs}"
                )
                print(
                    f"Stock on S/O (LBS): {stock_so_lbs}"
                )


                # -----------------------------------------------
                # Click Edit from SAME row
                # -----------------------------------------------

                row.locator(
                    "[data-field=\'edit\'] button[title=\'Edit\']"
                ).click(force=True)

                found = True
                break


        except Exception:
            continue


    if found:
        break


    # ============================================================
    # Scroll down
    # ============================================================

    scroller.evaluate(
        "(el) => { el.scrollTop += 1500; }"
    )

    page.wait_for_timeout(1000)


# ============================================================
# Final assertion
# ============================================================

assert found, (
    "No row found where "
    "Actual Yard Stock (LBS) > 30 and "
    "Stock on S/O (LBS) = 0 "
    "excluding Actual Yard Stock (LBS) = 2,800,028,000"
)','2026-05-09 03:58:28','2026-08-30 04:52:12','user','User','PENDING',19,1),
