(3835,40,'custom','Verify that the Item to Produce grid contains two rows and that at least one row displays a Strip Width of "23.50"','xpath=//body','from playwright.sync_api import expect


# ============================================================
# Get "Item to Produce" section
# ============================================================

section = page.locator(
    "h6:has-text(\'Item to Produce\')"
).locator(
    "xpath=following::div[@role=\'grid\'][1]"
)


# ============================================================
# Get data rows
# ============================================================

rows = section.locator(
    "div[role=\'row\'][data-rowindex]"
)

expect(rows).to_have_count(2)


# ============================================================
# Get Length values
# ============================================================

lengths = rows.locator(
    "div[role=\'gridcell\'][data-field=\'length\']"
).all_inner_texts()

print("Length values:", lengths)


# ============================================================
# Verify Length = 23.50 exists
# ============================================================

assert any(
    abs(float(length.strip()) - 23.50) < 0.01
    for length in lengths
), "No row found with Length = 23.50"','2026-05-09 04:44:04','2026-08-30 04:20:37','user','User','PENDING',25,1),
(3836,40,'custom','Verify that the Item to Produce grid contains three rows and that at least two rows display a Strip Width of "23.50"','xpath=//body','from playwright.sync_api import expect

grid = page.locator(\'div[role="grid"][aria-colcount="8"]\')

rows = grid.locator(
    \'div[class*="MuiDataGrid-virtualScrollerRenderZone"] div[role="row"][data-rowindex]\'
)
expect(rows).to_have_count(3)

lengths = rows.locator(
    \'div[role="gridcell"][data-field="length"]\'
).all_inner_texts()

TARGET = 23.50
count_2350 = sum(
    1 for t in lengths
    if abs(float(t.strip().replace(",", "")) - TARGET) < 0.01
)

assert count_2350 >= 2, f"Expected >=2 rows with Strip Width {TARGET}, found {count_2350}"','2026-05-09 04:50:27','2026-08-25 03:38:51','user','User','PENDING',30,1),
