(4212,78,'custom','Verify that the PO Intransit is created successfully with a unique number.','Assertion','from playwright.sync_api import expect

# Verify PO In transit unique number is created
transit_id = page.locator("text=Transit ID :")

expect(transit_id).to_be_visible()

# Validate unique number format exists
expect(transit_id).to_contain_text("Load #")','2026-05-13 07:47:10','2026-08-25 03:40:50','user','User','PENDING',71,1),
(4213,78,'custom','Capture the Transit ID.','Transit ID Caption','import re
from playwright.sync_api import expect

# Locate the Transit ID heading
transit_section = page.locator(
    "h6.MuiTypography-root.MuiTypography-h6"
).filter(
    has_text="Transit ID"
).first

expect(transit_section).to_be_visible(timeout=15_000)

# Get full text
transit_text = transit_section.inner_text().strip()

# Example text:
# "Transit ID : 217402, Load # 00030 - Created by: Krishna"

# Extract Transit ID
m = re.search(r"Transit ID\\s*:\\s*(\\d+)", transit_text)

if not m:
    raise AssertionError(
        f"Could not parse Transit ID from: {transit_text!r}"
    )

transit_id = m.group(1)

# Store variable
set_var("transit_id", transit_id)

