(5197,112,'custom','Verify intercompany invoices are being shown in search result','Assert','import re
from playwright.sync_api import Page, expect
def assert_intercompany_invoices_grid_has_rows(page: Page) -> None:
    # Grid root (MUI DataGrid)
    grid = page.locator("div.MuiDataGrid-main[role=\'grid\']")
    # Grid visible / loaded
    expect(grid).to_be_visible()
    # Real data rows have `data-rowindex` (header row doesn\'t)
    data_rows = grid.locator("div[role=\'row\'][data-rowindex]")
    # Wait until at least 1 row is rendered
    expect(data_rows.first).to_be_visible()
    # Final assert: 1 ya 1 se zyada rows
    assert data_rows.count() >= 1','2026-05-20 07:31:55','2026-05-20 07:31:55','user','system','PENDING',11,1),
