(5516,124,'custom','Verify that the Credit Note Preview header, Date field, and Preview Credit Note button are displayed successfully','Credit Note Preview header','from playwright.sync_api import Page, expect

def test_verify_credit_note_preview_popup(page: Page):

    # Verify Credit Note Preview header is displayed
    expect(
        page.locator("//h2[contains(text(),\'Credit Note Preview\')]")
    ).to_be_visible()

    # Verify Date field is displayed
    expect(
        page.locator("(//input[@type=\'text\' and @placeholder=\'MM/DD/YYYY\'])[3]")
    ).to_be_visible()

    # Verify Comments field is displayed
    expect(
        page.locator("//textarea[@name=\'comments\']")
    ).to_be_visible()

    # Verify Preview Credit Note button is displayed
    expect(
        page.locator("//button[normalize-space()=\'Preview Credit Note\']")
    ).to_be_visible()','2026-05-20 14:48:54','2026-05-20 15:33:33','user','system','PENDING',14,1),
