(5536,126,'custom','Verify all shipping and billing details auto-populate',' shipping and billing details','from playwright.sync_api import Page, expect

def test_verify_billing_and_shipping_details_not_blank(page: Page):

    # ---------------------------
    # Billing Details Section
    # ---------------------------

    billing_section = page.locator(
        "//h6[contains(text(),\'Billing Details\')]/ancestor::div[contains(@class,\'MuiPaper-root\')]"
    )

    # Verify billing section contains some visible text
    billing_text = billing_section.text_content()

    assert billing_text is not None
    assert billing_text.strip() != "", "Billing Details section is blank"


    # ---------------------------
    # Shipping Details Section
    # ---------------------------

    shipping_section = page.locator(
        "//h6[contains(text(),\'Shipping Details\')]/ancestor::div[contains(@class,\'MuiPaper-root\')]"
    )

    # Verify shipping section contains some visible text
    shipping_text = shipping_section.text_content()

