(5633,128,'custom','Verify Print pdf and Receive pdf button shown on the top right','Print pdf and Receive pdf button','from playwright.sync_api import Page, expect

def test_verify_print_and_receive_pdf_buttons(page: Page):

    # Verify Print button is visible on top right
    print_button = page.locator("//button[@permission=\'PRINT_CREDIT_NOTE\' and text()=\'Print\']")
    expect(print_button).to_be_visible()

    # Verify Credit Receive Pdf button is visible on top right
    receive_pdf_button = page.locator("//button[contains(normalize-space(),\'Credit Receive Pdf\')]")
    expect(receive_pdf_button).to_be_visible()','2026-05-21 09:44:26','2026-07-14 15:41:35','user','User','PENDING',17,1),
