(5855,131,'custom','Verify that the PO #, Shipping Term, Project Name, and Carrier Name fields are displayed in the Picklist','Assertion','from playwright.async_api import async_playwright, expect

async def test_verify_fields(page):

    # Verify PO # field
    await expect(
        page.locator("//input[@placeholder=\'PO #\']")
    ).to_be_visible()

    # Verify Shipping Term field
    await expect(
        page.locator("//label[contains(text(),\'Shipping Term\')]/following::input[1]")
    ).to_be_visible()

    # Verify Project Name field
    await expect(
        page.locator("//input[@name=\'projectName\']")
    ).to_be_visible()

    # Verify Carrier field
    await expect(
        page.locator("//input[@role=\'combobox\' and @id=\'autocomplete-shippingCarrier\']")
    ).to_be_visible()','2026-05-22 04:19:50','2026-09-03 16:26:46','user','User','PENDING',34,1),
