(5857,130,'custom','Verify shipment  should get cancelled and On order screen quantity ship should show zero.','Assertion','from playwright.sync_api import Page, expect

def test_verify_shipment_cancelled_and_qty_shipped_zero(page: Page):

    # Verify SHIPMENT CANCELLED message
    shipment_cancelled = page.locator(
        "//span[contains(.,\'SHIPMENT CANCELLED\')]"
    )

    expect(shipment_cancelled).to_be_visible()

    # Verify Qty Shipped value is 0.00
    qty_shipped_value = page.locator(
        "//div[@role=\'gridcell\' and @data-field=\'qtyShippedItem\']"
    ).first

    expect(qty_shipped_value).to_contain_text("0.00")','2026-05-22 04:35:46','2026-08-15 10:23:40','user','User','PENDING',43,1),
