(6445,143,'assertion','Verify System should show the manually cancel receipt row on history with negative qty','Inventory History grid','from playwright.sync_api import expect

# Stored Order/PO value
order_id = str(get_var("po_number")).strip()
print("Stored Order ID:", order_id)

rows = page.locator(
    f"//div[@role=\'row\'][@data-id]"
    f"[.//div[@data-field=\'orderId\' and normalize-space()=\'{order_id}\']]"
)

count = rows.count()
print("Matching Rows:", count)

found = False

for i in range(count):
    details = rows.nth(i).locator("[data-field=\'comments\']").inner_text().strip()

    print(f"Row {i} Details: {details}")

    if "manually cancelled" in details.lower():
