text = loc.inner_text().strip()
m = re.search(r"\\(#(\\d+)\\)", text)
if not m:
    raise AssertionError(f"Could not parse intransit id from: {text!r}")
intransit_id = m.group(1)
set_var("intransit_id", intransit_id)

print(f\'set_var("intransit_id", {intransit_id})\')
