(8654,172,'custom','Verify that price/Tons values displayed in the grid with conversion rate ','Assertion','import json

currency = get_var("supplierCurrency")


def to_list(raw):
    """Normalize a TDM value into a list of dicts."""
    if not raw:
        return []
    if isinstance(raw, str):
        s = raw.strip()
        if not s or s.upper() == None:
            return []
        raw = json.loads(s)
    return raw if isinstance(raw, list) else [raw]


def int_part(value):
    """Return the integer part of a number as an int (ignores $, commas, decimals).

    Returns None if there are no digits, so an empty/blank cell never
    silently matches another empty cell.
    """
    digits = "".join(filter(str.isdigit, str(value).split(".")[0]))
    return int(digits) if digits else None


def to_float(value):
    if value is None:
        print(f"to_float: value is None -> returning None (passed: {value!r})")
        return None
    s = str(value).replace("$", "").replace(",", "").strip()
    if not s or s.upper() == "NA":
        print(f"to_float: blank/NA -> returning None (passed: {value!r})")
        return None
    return float(s)


conversion_rate = to_float(tdm_fetch("{TableProductLogic.${row_number}.CONVERSION_RATE_VALUE}"))

print("conversion rate:", conversion_rate)

allProducts = (
    to_list(get_var("beamsJson"))
    + to_list(get_var("pipesJson"))
    + to_list(get_var("attchJson"))
    + to_list(get_var("otherJson"))
    + to_list(get_var("sheetJson"))
)

print("total items:", len(allProducts))
set_var("allProductsJson", allProducts)

failures = []
results = []  # collects (productId, expected, actual, status) for the summary table

for item in allProducts:
    productId = item["input"]["productId"]

    cell = page.locator(
        f"//*[text()=\'{productId}\']/..//*[@data-field=\'unitCostFormatted\']"
    )
    cell.wait_for(state="visible")
    actual_raw = cell.inner_text().strip()

    expected = int_part(item["output"]["costperton"])
    actual = int_part(actual_raw)

    if currency == "USD":
        print("actual raw",actual_raw)
        actual_usd = to_float(actual_raw)
        expected_usd = conversion_rate * to_float(item["output"]["costperton"])
        print("actual usd",actual_usd)
        print("expected usd",expected_usd)
        usd_ok = round(actual_usd, 2) == round(expected_usd, 2)
        print(
            f" USD {productId} -> expected={expected_usd:.2f} actual={actual_usd:.2f} "
            f"[{\'OK\' if usd_ok else \'MISMATCH\'}]"
        )
        if not usd_ok:
            failures.append(
                f"{productId} qtyChangeCost: expected {expected_usd:.2f}, got {actual_usd:.2f}"
            )
    else:
        if actual == expected:
            status = "OK"
        else:
            status = "MISMATCH"
            failures.append(
                f"{productId} unitCost: expected {expected}, got {actual} (raw {actual_raw!r})"
            )
        results.append((productId, expected, actual, status))
        print(f"[{status}] {productId} -> expected={expected} actual={actual} (raw {actual_raw!r})")

# ---- Summary: every product id with its expected and actual integer part ----
print("\\n===== SUMMARY (integer part) =====")
print(f"{\'productId\':<25} {\'expected\':>12} {\'actual\':>12}   status")
print("-" * 66)
for productId, expected, actual, status in results:
    print(f"{str(productId):<25} {str(expected):>12} {str(actual):>12}   {status}")
print("-" * 66)
print(f"{len(results)} products checked, {len(failures)} mismatch(es)\\n")

assert not failures, "Mismatches:\\n" + "\\n".join(failures)
print("All matched")
