(8742,173,'custom','Read and capture the Transit ID','Transit ID Caption','import re
from playwright.sync_api import expect

# Locate the header containing "Receive Purchase Order Intransit"
header = page.locator(
    "span.MuiTypography-root.MuiTypography-body1"
).filter(
    has_text="Receive Purchase Order Intransit"
).first

expect(header).to_be_visible(timeout=15_000)

# Get header text
header_text = header.inner_text().strip()

# Example:
# "Receive Purchase Order Intransit(#228725),"

# Extract Intransit number
m = re.search(r"Intransit\\(#(\\d+)\\)", header_text)

if not m:
    raise AssertionError(
        f"Could not parse Intransit number from: {header_text!r}"
    )

intransit_id = m.group(1)

# Store variable
set_var("intransit_id", intransit_id)

print(f"Captured Intransit ID: {intransit_id}")','2026-06-08 12:57:18','2026-07-15 10:42:53','user','system','PENDING',15,1),
