(8972,116,'custom','Click on CSV Export and Verify file content and matches with grid information for first row','content matched','import os
import csv
import re

from playwright.sync_api import expect


# ============================================================
# SEARCH INVENTORY - CSV EXPORT VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "SEARCH INVENTORY - EXPORT CSV AND VALIDATE FIRST ROW"
)

print(
    "============================================================"
)


# ============================================================
# 1. GET FIRST ROW FROM SEARCH INVENTORY GRID
# ============================================================

print(
    "\\n============================================================"
)

print(
    "GETTING FIRST ROW FROM SEARCH INVENTORY UI"
)

print(
    "============================================================"
)


# ------------------------------------------------------------
# First data row of MUI DataGrid
# ------------------------------------------------------------

first_row = page.locator(
    ".MuiDataGrid-row[data-rowindex=\'0\']"
).first


expect(
    first_row
).to_be_visible(
    timeout=10000
)


print(
    "\\nFirst UI row found successfully."
)


# ------------------------------------------------------------
# Get all cells from first row
# ------------------------------------------------------------

ui_cells = first_row.locator(
    ".MuiDataGrid-cell"
)


ui_cell_count = ui_cells.count()


assert ui_cell_count > 0, (
    "No cells were found in the first Search Inventory UI row."
)


print(
    "UI first row cell count:",
    ui_cell_count
)


# ============================================================
# 2. BUILD UI COLUMN -> VALUE MAPPING
# ============================================================

ui_row_data = {}


for i in range(ui_cell_count):

    cell = ui_cells.nth(i)

    # --------------------------------------------------------
    # Get data-field from the grid cell
    # --------------------------------------------------------

    field_name = cell.get_attribute(
        "data-field"
    )

    if not field_name:
        continue


    # --------------------------------------------------------
    # Get displayed value
    # --------------------------------------------------------

    cell_value = cell.inner_text().strip()


    # Normalize whitespace
    cell_value = " ".join(
        cell_value.split()
    )


    ui_row_data[field_name] = cell_value


    print(
        f"UI Column: {field_name} | "
        f"Value: {cell_value}"
    )


assert len(ui_row_data) > 0, (
    "Unable to extract any column values from the first UI row."
)


print(
    "\\nSUCCESS: First UI row data extracted."
)


# ============================================================
# 3. GET UI COLUMN HEADER MAPPING
#
# data-field = internal field name
# header text = CSV/display column name
# ============================================================

print(
    "\\n============================================================"
)

print(
    "GETTING SEARCH INVENTORY COLUMN HEADERS"
)

print(
    "============================================================"
)


ui_headers = {}


header_cells = page.locator(
    ".MuiDataGrid-columnHeader"
)


header_count = header_cells.count()


print(
    "UI header count:",
    header_count
)


for i in range(header_count):

    header = header_cells.nth(i)

    field_name = header.get_attribute(
        "data-field"
    )

    if not field_name:
        continue


    header_text = header.inner_text().strip()

    header_text = " ".join(
        header_text.split()
    )


    if not header_text:
        # Try aria-label if visible text is empty
        header_text = (
            header.get_attribute("aria-label")
            or ""
        ).strip()


    ui_headers[field_name] = header_text


    print(
        f"UI Field: {field_name} | "
        f"Header: {header_text}"
    )


# ============================================================
# 4. CLICK CSV EXPORT AND DOWNLOAD FILE
# ============================================================

print(
    "\\n============================================================"
)

print(
    "EXPORTING SEARCH INVENTORY AS CSV"
)

print(
    "============================================================"
)


# ------------------------------------------------------------
# CSV Export button
#
# DOM:
# <button title="CSV Export">
# ------------------------------------------------------------

export_button = page.locator(
    "button[title=\'CSV Export\']"
).first


expect(
    export_button
).to_be_visible(
    timeout=10000
)


expect(
    export_button
).to_be_enabled(
    timeout=10000
)


# ------------------------------------------------------------
# Wait for download
# ------------------------------------------------------------

with page.expect_download(
    timeout=30000
) as download_info:

    export_button.click()


download = download_info.value


# ============================================================
# 5. DOWNLOAD INFORMATION
# ============================================================

filename = download.suggested_filename


print(
    "\\nDownloaded filename:",
    filename
)


assert filename, (
    "CSV download did not provide a filename."
)


assert filename.lower().endswith(
    ".csv"
), (
    f"Expected CSV file, but downloaded: {filename}"
)


# ============================================================
# 6. SAVE CSV FILE
# ============================================================

download_dir = "/tmp/downloads"


os.makedirs(
    download_dir,
    exist_ok=True
)


file_path = os.path.join(
    download_dir,
    filename
)


download.save_as(
    file_path
)


print(
    "CSV saved to:",
    file_path
)


# ============================================================
# 7. VERIFY FILE EXISTS
# ============================================================

assert os.path.exists(
    file_path
), (
    f"Downloaded CSV file was not saved: {file_path}"
)


assert os.path.getsize(
    file_path
) > 0, (
    f"Downloaded CSV file is empty: {file_path}"
)


print(
    "\\nSUCCESS: CSV file exists and is not empty."
)


# ============================================================
# 8. READ CSV
# ============================================================

print(
    "\\n============================================================"
)

print(
    "READING SEARCH INVENTORY CSV"
)

print(
    "============================================================"
)


with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)

    rows = list(reader)


assert len(rows) > 0, (
    "Search Inventory CSV does not contain any rows."
)


print(
    "Total physical CSV rows:",
    len(rows)
)


# ============================================================
# 9. FIND SEARCH INVENTORY HEADER ROW
# ============================================================
#
# Search Inventory screenshot contains:
#
# Product ID
# Description
# MTR
# HEAT#
# Actual Yard
# C (%)
# Mn (%)
# P (%)
# S (%)
# Si (%)
# Al (%)
# Cu (%)
# Ni (%)
#
# We search for Product ID + Description rather than assuming
# the header is always row 1.
# ============================================================

header_row_index = None


for index, row in enumerate(rows):

    cleaned_row = [
        column.strip().strip(\'="\')
        for column in row
    ]


    has_product_id = (
        "Product ID" in cleaned_row
    )


    has_description = (
        "Description" in cleaned_row
    )


    if (
        has_product_id
        and has_description
    ):

        header_row_index = index

        break


assert header_row_index is not None, (
    "Search Inventory CSV header row was not found."
)


headers = [
    column.strip().strip(\'="\')
    for column in rows[header_row_index]
]


print(
    "\\nSearch Inventory CSV header found at row:",
    header_row_index + 1
)


print(
    "CSV Headers:"
)


for header in headers:

    print(
        " -",
        header
    )


# ============================================================
# 10. GET CSV DATA ROWS
# ============================================================

data_rows = rows[
    header_row_index + 1:
]


# Remove completely blank rows

data_rows = [
    row
    for row in data_rows
    if any(
        cell.strip()
        for cell in row
    )
]


assert len(data_rows) > 0, (
    "Search Inventory CSV does not contain any data rows."
)


csv_first_row = data_rows[0]


print(
    "\\nCSV first data row:"
)

print(
    csv_first_row
)


# ============================================================
# 11. CREATE CSV HEADER -> VALUE MAPPING
# ============================================================

csv_row_data = {}


for index, header in enumerate(headers):

    if index >= len(csv_first_row):
        continue


    value = csv_first_row[index]


    value = value.strip().strip(\'="\')


    # Normalize whitespace
    value = " ".join(
        value.split()
    )


    csv_row_data[header] = value


# ============================================================
# 12. DISPLAY CSV FIRST ROW
# ============================================================

print(
    "\\n============================================================"
)

print(
    "CSV FIRST ROW DATA"
)

print(
    "============================================================"
)


for header, value in csv_row_data.items():

    print(
        f"CSV Column: {header} | "
        f"Value: {value}"
    )


# ============================================================
# 13. VALIDATE EXPECTED SEARCH INVENTORY COLUMNS
# ============================================================

expected_columns = [
    "Product ID",
    "Description",
    "MTR",
    "HEAT#"
]


print(
    "\\n============================================================"
)

print(
    "VALIDATING SEARCH INVENTORY CSV COLUMNS"
)

print(
    "============================================================"
)


for column in expected_columns:

    assert column in headers, (
        f"Expected Search Inventory column "
        f"\'{column}\' was not found in CSV."
    )


print(
    "SUCCESS: Expected Search Inventory columns "
    "are present in CSV."
)


# ============================================================
# 14. MAP UI FIELD NAMES TO CSV DISPLAY HEADERS
# ============================================================
#
# UI uses data-field.
#
# Example:
#
# data-field="description"
#
# while CSV uses:
#
# Description
#
# We use the UI column header text to find the corresponding
# CSV column.
# ============================================================

print(
    "\\n============================================================"
)

print(
    "VALIDATING FIRST UI ROW AGAINST FIRST CSV ROW"
)

print(
    "============================================================"
)


validated_columns = 0


for field_name, ui_value in ui_row_data.items():

    # --------------------------------------------------------
    # Find display header corresponding to this data-field
    # --------------------------------------------------------

    csv_header = ui_headers.get(
        field_name
    )


    if not csv_header:
        print(
            f"Skipping UI field \'{field_name}\' "
            f"because no UI header was found."
        )

        continue


    # --------------------------------------------------------
    # CSV must contain this column
    # --------------------------------------------------------

    if csv_header not in csv_row_data:

        print(
            f"Skipping \'{field_name}\' because "
            f"CSV header \'{csv_header}\' was not found."
        )

        continue


    csv_value = csv_row_data[
        csv_header
    ]


    # --------------------------------------------------------
    # Normalize values before comparison
    # --------------------------------------------------------

    normalized_ui_value = " ".join(
        str(ui_value).strip().split()
    )


    normalized_csv_value = " ".join(
        str(csv_value).strip().split()
    )


    # --------------------------------------------------------
    # Print comparison
    # --------------------------------------------------------

    print(
        "\\n------------------------------------------------------------"
    )

    print(
        "Column:",
        csv_header
    )

    print(
        "UI value :",
        normalized_ui_value
    )

    print(
        "CSV value:",
        normalized_csv_value
    )


    # --------------------------------------------------------
    # ASSERT UI == CSV
    # --------------------------------------------------------

    assert normalized_ui_value == normalized_csv_value, (
        f"\\nFirst row data mismatch for column "
        f"\'{csv_header}\'.\\n"
        f"UI value : \'{normalized_ui_value}\'\\n"
        f"CSV value: \'{normalized_csv_value}\'"
    )


    print(
        f"SUCCESS: \'{csv_header}\' "
        "matches between UI and CSV."
    )


    validated_columns += 1


# ============================================================
# 15. VERIFY AT LEAST ONE COLUMN WAS VALIDATED
# ============================================================

assert validated_columns > 0, (
    "No Search Inventory columns could be matched "
    "between UI and CSV."
)


print(
    "\\n============================================================"
)

print(
    "SUCCESS: FIRST SEARCH INVENTORY UI ROW "
    "MATCHES FIRST CSV DATA ROW."
)

print(
    "Columns validated:",
    validated_columns
)

print(
    "============================================================"
)


# ============================================================
# 16. DELETE CSV AFTER VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "DELETING DOWNLOADED CSV"
)

print(
    "============================================================"
)


assert os.path.exists(
    file_path
), (
    f"CSV file does not exist before deletion: {file_path}"
)


os.remove(
    file_path
)


assert not os.path.exists(
    file_path
), (
    f"CSV file was not deleted: {file_path}"
)


print(
    "SUCCESS: Search Inventory CSV was deleted "
    "after validation."
)


print(
    "\\n============================================================"
)

print(
    "SEARCH INVENTORY CSV VALIDATION COMPLETED SUCCESSFULLY"
)

print(
    "============================================================"
