assert match is not None, "Order number not found after \'Order #:\'"

order_number = match.group(1)
print(order_number)

# Verify Created text
assert "Created" in order_text, "\'Created\' text not found"

# Verify ORDER_CREATED icon/button
order_created_icon = page.locator("(//button[@title=\'ORDER_CREATED\'])[2]")
assert order_created_icon.is_visible(), "\'ORDER_CREATED\' icon not visible"

