(10281,172,'custom','Beams: Create and Receive PO In transit','Create and Receive PO','import json
import re
from playwright.sync_api import expect

product = get_var("beamsJson")
print("products:", product)
purchaseOrder = get_var("po_number")


if product == None:
    print("product is NA, skipping everything")
else:
    page.wait_for_timeout(5000)

    if isinstance(product, str):
        product = json.loads(product)

    for itemprop in product:
        productId = itemprop["input"]["productId"]
        unitPrice = itemprop["input"]["po_price"]
        uom = itemprop["input"]["po_quantity_uom"]
        qty = itemprop["input"]["po_qty"]
        page.locator(\'//button[contains(text(),"Create PO Intransit")]\').click()
        page.wait_for_timeout(2000)
        page.locator(\'[name="poNumber"]\').fill(purchaseOrder)
        page.locator(\'h6.MuiTypography-h6\').first.click()
        page.wait_for_timeout(2000)

        transitQtyLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'transitQty\']")
        transitQtyLoc.click()
        page.wait_for_timeout(3000)
        
        transitQtyInput = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'transitQty\']//input")
        if transitQtyInput.count() < 1:
            transitQtyLoc.click()
            transitQtyInput.fill(qty)
        else:
            transitQtyInput.fill(qty)

        page.locator(\'//h6[normalize-space()="Intransit For Receiving PO"]\').click()
        page.wait_for_timeout(7000)
        page.locator(\'//button[text()="Create And Receive PO Intransit"]\').click()
        page.wait_for_timeout(5000)

        okButton = page.locator("//div[@role=\'dialog\']//button[normalize-space()=\'Ok\']")
        if okButton.count() < 1:
            page.locator(\'//button[text()="Create And Receive PO Intransit"]\').click()
            page.wait_for_timeout(3000)
            okButton.click()
        else:
            okButton.click()


