(10282,220,'custom','Complete the intransit flow with PO Order','Complete the intransit flow with PO Order','import re

transit_counter = 1

for i in range(1, 13):

    qty_shipped = tdm_fetch(
        f"{{UserFlowProductsData.1.POQtyShippedtem{i}}}"
    )

    if (
        qty_shipped is None
        or str(qty_shipped).strip() == ""
        or str(qty_shipped).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Qty Shipped Row {i}: {qty_shipped}")
        continue

    print(f"Processing Qty Shipped Row {i}: {qty_shipped}")

    # ==========================
    # Create PO Intransit
    # ==========================

    page.locator(
        "//button[normalize-space()=\'Create PO Intransit\']"
    ).click()

    page.wait_for_timeout(2000)

    page.locator(
        "//input[@type=\'text\' and @name=\'poNumber\']"
    ).fill(str(get_var("po_number")))

    page.wait_for_timeout(1000)

    page.locator(
        "//h6[normalize-space()=\'Intransit For Receiving PO\']"
    ).click()

    page.wait_for_timeout(3000)

    # ==========================
    # Enter Transit Quantity
    # ==========================

    page.locator(
        "(//div[@role=\'gridcell\' and @data-field=\'transitQty\'])[1]"
    ).click()

    page.wait_for_timeout(1000)

    page.locator(
        "(//div[@role=\'gridcell\' and @data-field=\'transitQty\'])[1]//input"
    ).fill(str(qty_shipped))

    page.wait_for_timeout(1000)

    # Save Grid Value

    page.locator(
        "//h6[normalize-space()=\'Intransit For Receiving PO\']"
    ).evaluate("el => el.click()")

    page.wait_for_timeout(5000)

    # Re-select First Row

    page.locator(
        "(//div[@role=\'gridcell\' and @data-field=\'transitQty\'])[1]"
    ).click(force=True)

    page.wait_for_timeout(5000)

    # ==========================
    # Create And Receive PO Intransit
    # ==========================

    page.get_by_role(
        "button",
        name="Create And Receive PO Intransit"
    ).click()

    page.wait_for_timeout(5000)

    # Confirmation Popup

    page.locator(
        "//div[@role=\'dialog\']//button[normalize-space()=\'Ok\']"
    ).click()

    page.wait_for_timeout(20000)

    # ==========================
    # Capture Transit ID
    # ==========================

    transit_loc = page.locator(
        "//h6[contains(text(),\'Transit ID\')]"
    )

    expect(transit_loc).to_be_visible(
        timeout=15000
    )

    transit_text = transit_loc.inner_text()

    print("Transit Text:", transit_text)

    m = re.search(
        r"Transit ID\\s*:\\s*(\\d+)",
        transit_text
    )

    if m:

        transit_id = m.group(1)

        print(
            f"Transit ID {transit_counter}: {transit_id}"
        )

        set_var(
            f"transit_id{transit_counter}",
            transit_id
        )

    # ==========================
    # Capture Product ID
    # ==========================

    product_loc = page.locator(
        "//div[@role=\'gridcell\' and @data-field=\'productId\']"
    )

    expect(product_loc).to_be_visible(
        timeout=15000
    )

    product_id = product_loc.inner_text().strip()

    print(
        f"Product ID {transit_counter}: {product_id}"
    )

    set_var(
        f"product_id{transit_counter}",
        product_id
    )

    # ==========================
    # Close Dialog (X)
    # ==========================

    page.locator(
        "(//div[@role=\'dialog\']//*[name()=\'svg\' and contains(@class,\'iconify\')])[1]"
    ).click()

    page.wait_for_timeout(3000)

    transit_counter += 1

print(
    f"Successfully processed {transit_counter - 1} transit record(s)."
)','2026-06-22 10:15:11','2026-06-23 17:22:17','user','User','PENDING',24,1),
