(10373,220,'custom','Enter Order  Qty, Unit Price and UAM in Order Screen','Enter Order  Qty, Unit Price and UAM','from playwright.sync_api import expect

# ==========================
# Order Qty, Unit Price & UOM (1 to 12)
# ==========================

for i in range(1, 13):

    # ==========================
    # Product ID Check
    # ==========================

    product_id = tdm_fetch(
        f"{{UserFlowProductsData.1.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Row {i} - Product ID not found")
        continue

    print(f"Processing Row {i}")

    # ==========================
    # Fetch Test Data
    # ==========================

    order_qty = tdm_fetch(
        f"{{UserFlowProductsData.1.OrderQtyOrderedIntem{i}}}"
    )

    order_unit_price = tdm_fetch(
        f"{{UserFlowProductsData.1.OrderUnitPriceInItem{i}}}"
    )

    uom_value = tdm_fetch(
        f"{{UserNewFlowProductsData.1.OrderUAMSelect{i}}}"
    )

    # ==========================
    # Qty Ordered
    # ==========================

    if (
        order_qty is not None
        and str(order_qty).strip() != ""
        and str(order_qty).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'quantity\'])[{i}]"
        ).click()

        page.wait_for_timeout(1000)

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'quantity\'])[{i}]//input"
        ).fill(str(order_qty))

        page.wait_for_timeout(1000)

        page.locator(
            "//h6[contains(text(),\'New Sales Order\')]"
        ).click(force=True)

        page.wait_for_timeout(2000)

        print(f"Qty Ordered updated for Row {i}: {order_qty}")

    else:
        print(f"Skipping Qty Ordered Row {i}: {order_qty}")

    # ==========================
    # Unit Price
    # ==========================

    if (
        order_unit_price is not None
        and str(order_unit_price).strip() != ""
        and str(order_unit_price).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'unitPrice\'])[{i}]"
        ).click()

        page.wait_for_timeout(1000)

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'unitPrice\'])[{i}]//input"
        ).fill(str(order_unit_price))

        page.wait_for_timeout(1000)

        page.locator(
            "//h6[contains(text(),\'New Sales Order\')]"
        ).click(force=True)

        page.wait_for_timeout(2000)

        print(
            f"Unit Price updated for Row {i}: {order_unit_price}"
        )

    else:
        print(
            f"Skipping Unit Price Row {i}: {order_unit_price}"
        )

    # ==========================
    # UOM Selection
    # ==========================

    if (
        uom_value is not None
        and str(uom_value).strip() != ""
        and str(uom_value).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        uom = str(uom_value).strip()

        print(f"Selecting UOM for Row {i}: {uom}")

        # Activate row before UOM selection
        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'unitPrice\'])[{i}]"
        ).click()

        page.wait_for_timeout(2000)

        # Open UOM dropdown
        uom_input = page.locator(
            "//input[@role=\'combobox\' and @id=\'autocomplete-unitMeasure\']"
        )

        uom_input.click(force=True)

        page.wait_for_timeout(1000)

        # Type UOM from TDM
        uom_input.fill(uom)

        page.wait_for_timeout(2000)

        # Select matching option
        option = page.locator(
            f"//li[@role=\'option\'][normalize-space()=\'{uom}\']"
        )

        expect(option.first).to_be_visible(timeout=10000)

        option.first.click()

        page.wait_for_timeout(1000)

        # Click outside to save
        page.locator(
            "//h6[contains(text(),\'New Sales Order\')]"
        ).click(force=True)

        page.wait_for_timeout(2000)

        print(f"UOM updated for Row {i}: {uom}")

    else:
        print(f"Skipping UOM Row {i}: {uom_value}")

    page.wait_for_timeout(2000)

