(10378,220,'custom','Enter Qty Shipped in Shipping Order Screen','Enter Qty Shipped','import re
from playwright.sync_api import expect

# ==========================
# Process All Available Rows
# ==========================

for i in range(1, 13):

    # ==========================
    # Product ID Check
    # ==========================

    product_id = tdm_fetch(
        f"{{UserFlowProductsData.1.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Row {i} - Product ID not found")
        continue

    # ==========================
    # Qty To Ship
    # ==========================

    qty_to_ship = tdm_fetch(
        f"{{UserFlowProductsData.1.OrderQtyToShipwithTheQuantityValueItem{i}}}"
    )

    if (
        qty_to_ship is None
        or str(qty_to_ship).strip() == ""
        or str(qty_to_ship).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Qty To Ship Row {i}")
        continue

    print(f"Processing Row {i}")

    # ==========================
    # Click Qty To Ship Cell
    # ==========================

    page.locator(
        f"//div[@data-id=\'{i}\']//*[@data-field=\'qtyToShip\']"
    ).click()

    page.wait_for_timeout(1000)

    # ==========================
    # Enter Qty To Ship
    # ==========================

    page.locator(
        f"//div[@data-id=\'{i}\']//*[@data-field=\'qtyToShip\']//input"
    ).fill(str(qty_to_ship))

    page.wait_for_timeout(1000)

    # ==========================
    # Click Outside Grid
    # ==========================

    page.locator(
        "//span[text()=\'Billing Details\']"
    ).click(force=True)

    page.wait_for_timeout(2000)

    # ==========================
    # Click Qty Ordered Cell
    # ==========================

    page.locator(
        f"(//div[@role=\'gridcell\' and @data-field=\'quantity\'])[{i}]"
    ).click()

    page.wait_for_timeout(2000)

    # ==========================
    # Generate Picklist
    # ==========================

    page.locator(
        "//button[normalize-space()=\'Generate Picklist\']"
    ).click(force=True)

    page.wait_for_timeout(10000)

    # ==========================
    # Generate BOL
    # ==========================

    page.locator(
        "(//button[normalize-space()=\'Generate BOL\'])[1]"
    ).click(force=True)

    page.wait_for_timeout(10000)

    # ==========================
    # Capture BOL Number
    # ==========================

    loc = page.get_by_text(
        re.compile(r"Planned In Shipment\\s+\\d+", re.I)
    )

    expect(loc).to_be_visible(timeout=15000)

    m = re.search(
        r"Planned In Shipment\\s+(\\d+)",
        loc.inner_text(),
        re.I
    )

    bol_number = m.group(1)

    var_name = f"bol_number{i}"

    set_var(var_name, bol_number)

    print(f"{var_name} = {bol_number}")

    # ==========================
    # Click New
    # ==========================

    page.locator(
        "//button[normalize-space()=\'New\']"
    ).click(force=True)

    page.wait_for_timeout(10000)

