(10385,220,'custom','Enter BOLs in Invoice sceen and generate Invoices','Enter BOLs in Invoice sceen','# ==========================
# Generate Invoice For All BOLs
# ==========================

for i in range(1, 13):

    product_id = tdm_fetch(
        f"{{UserFlowProductsData.1.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        continue

    bol_number = get_var(f"bol_number{i}")

    if not bol_number:
        print(f"BOL Number not found for Row {i}")
        continue

    print(f"Processing Invoice for BOL: {bol_number}")

    # ==========================
    # Clear BOL #
    # ==========================

    page.locator(
        "//input[@name=\'shipmentId\']"
    ).clear()

    page.wait_for_timeout(2000)

    # ==========================
    # Enter BOL #
    # ==========================

    page.get_by_role(
        "textbox",
        name="BOL #"
    ).fill(str(bol_number))

    page.wait_for_timeout(2000)

    # ==========================
    # Search
    # ==========================

    page.get_by_role(
        "button",
        name="Search"
    ).click()

    page.wait_for_timeout(3000)

    # ==========================
    # Select Checkbox
    # ==========================

    page.locator(
        "//input[@type=\'checkbox\' and @aria-label=\'Select row\']"
    ).check()

    page.wait_for_timeout(2000)

    # ==========================
    # Generate Invoice
    # ==========================

    page.get_by_role(
        "button",
        name="Generate Invoice"
    ).click()

    page.wait_for_timeout(3000)

    # ==========================
    # Preview Invoice
    # ==========================

    page.get_by_role(
        "button",
        name="Preview Invoice"
    ).click()

    page.wait_for_timeout(5000)

    # ==========================
    # Click OK Popup
    # ==========================

    ok_btn = page.locator(
        "//button[normalize-space()=\'Ok\']"
    )

    if ok_btn.count() > 0:

        ok_btn.wait_for(
            state="visible",
            timeout=15000
        )

        ok_btn.click()

        print("OK button clicked successfully")

        page.wait_for_timeout(10000)

    else:

        print("OK button not displayed")

    # ==========================
    # Final Generate Invoice
    # ==========================

    page.locator(
        "(//button[normalize-space()=\'Generate Invoice\'])[2]"
    ).click(force=True)

    page.wait_for_timeout(10000)

    print(
        f"Invoice Generated Successfully For BOL: {bol_number}"
    )

