        page.wait_for_timeout(7000)

        qtyToShipLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'qtyToShip\']")
        
        found = False
        for attempt in range(1, 7):   
            expect(btn, "...").to_be_enabled(timeout=120000)
            if qtyToShipLoc.count() >= 1:
                found = True
                break
            else:
                btn.click()
                page.wait_for_timeout(5000)


            print(f"attempt {attempt}: qtyToShip row not found for {productId}, retrying")

        qtyToShipInput = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'qtyToShip\']//input")
        if qtyToShipInput.count() < 1:
            qtyToShipLoc.click()
            page.wait_for_timeout(2000)
            qtyToShipInput.fill(str(qtyToShip))
        else:
            qtyToShipInput.fill(str(qtyToShip))
