(10858,172,'custom','Beams: Generate invoice for each Bol','Generate Invoice','import json
import re

product = get_var("beamsJson")

if product == None:
    print("product is NA, skipping everything")
else:
    if isinstance(product, str):
        product = json.loads(product)
    
    index = 0
    for itemprop in product:
        index +=1
        productId = itemprop["input"]["productId"]
        bol_number = itemprop["runtime"]["bol_number"]

        search = page.locator("//*[@type=\'submit\']")
        firstcheckbox = page.locator(f"//*[text()=\'{bol_number}\']/..//input").first


        found = False
        for attempt in range(1, 5):
            page.locator("//input[@name=\'shipmentId\']").clear()
            page.get_by_role("textbox", name="BOL #").fill(str(bol_number))
            expect(search, f"Search button not enabled for BOL {bol_number}").to_be_enabled(timeout=120000)
            search.click()
            page.wait_for_timeout(2000)
            if firstcheckbox.count() > 0:
                found = True
                break

        if not found:
            print(f"BOL {bol_number} not found after 4 attempts, skipping")
            continue

        firstcheckbox.click()    
        page.wait_for_timeout(7000)

        page.get_by_role("button", name="Generate Invoice").click()
        page.wait_for_timeout(7000)
        page.get_by_role("button", name="Preview Invoice").click()

        ok_btn = page.locator("//button[normalize-space()=\'Ok\']")
        page.wait_for_timeout(7000)
        if ok_btn.count() > 0:
            ok_btn.wait_for(state="visible", timeout=15000)
            ok_btn.click()
            print("OK button clicked successfully")
        else:
            print("OK button not displayed")

        page.locator("(//button[normalize-space()=\'Generate Invoice\'])[2]").click(force=True)','2026-06-25 18:39:48','2026-08-12 09:00:54','user','User','PENDING',89,1),
