(10932,236,'custom','Select multiple Credit Notes for the same Order','Select multiple credit notes','# ============================================================
# Select First 3 DataGrid Rows
# ============================================================

rows = page.locator(
    "div[role=\'row\'][data-id]:visible"
)

row_count = rows.count()

assert row_count >= 3, (
    f"Expected at least 3 visible data rows, "
    f"but found {row_count}."
)


# ============================================================
# Select First 3 Rows
# ============================================================

for i in range(3):

    row = rows.nth(i)

    # --------------------------------------------------------
    # Get row ID for logging
    # --------------------------------------------------------

    row_id = row.get_attribute("data-id")

    print(
        f"Selecting row {i + 1} "
        f"(data-id={row_id})..."
    )


    # --------------------------------------------------------
    # Get checkbox cell
    # --------------------------------------------------------

    checkbox_cell = row.locator(
        "div[role=\'gridcell\'][data-field=\'__check__\']"
    )

    expect(checkbox_cell).to_be_visible(
        timeout=15000
    )


    # --------------------------------------------------------
    # Get checkbox input
    # --------------------------------------------------------

    checkbox = checkbox_cell.locator(
        "input[aria-label=\'Select row\']"
    )

    expect(checkbox).to_be_attached(
        timeout=15000
    )


    # --------------------------------------------------------
    # Check current selection
    # --------------------------------------------------------

    if not checkbox.is_checked():

        # Click MUI checkbox wrapper instead of input
        checkbox_wrapper = checkbox.locator(
            "xpath=.."
        )

        checkbox_wrapper.click(
            force=True
        )


    # --------------------------------------------------------
    # Verify row selection using aria-selected
    # --------------------------------------------------------

    expect(row).to_have_attribute(
        "aria-selected",
        "true",
        timeout=15000
    )

    print(
        f"Row {i + 1} "
        f"(data-id={row_id}) selected successfully."
    )


# ============================================================
# Final Verification
# ============================================================

selected_rows = page.locator(
    "div[role=\'row\'][data-id][aria-selected=\'true\']:visible"
)

selected_count = selected_rows.count()

assert selected_count >= 3, (
    f"Expected 3 selected rows, "
    f"but found {selected_count}."
)

print(
    "SUCCESS: First 3 rows selected successfully."
)','2026-06-29 09:04:35','2026-08-29 15:19:41','user','User','PENDING',10,1),
