(11306,248,'custom','Read and capture the Heat Number from the first grid, click the Linked Document button, then verify that the Heat Number in the Linked Document dialog matches the captured value','Read, capture and verify','from playwright.sync_api import expect

# Capture Heat Number from Inventory grid
heat_number = page.locator("(//div[@role=\'gridcell\' and @data-field=\'heat\'])[1]").inner_text().strip()
print(f"Captured Heat Number: {heat_number}")

# Click on Linked Document button
page.locator("(//button[@title=\'Linked Document\'])[1]").click()

# Wait for Linked Document dialog to appear
expect(page.locator("//h2[normalize-space()=\'Inventory Search Documents\']")).to_be_visible()

# Capture Heat Number from Linked Document grid
linked_heat = page.locator("(//div[@role=\'gridcell\' and @data-field=\'heatNumber\'])[1]").inner_text().strip()
print(f"Linked Document Heat Number: {linked_heat}")

# Verify both Heat Numbers are same
assert heat_number == linked_heat, (
    f"Heat Number mismatch! Expected: {heat_number}, Actual: {linked_heat}"
)

print(" Heat Number matched successfully.")','2026-07-01 07:24:03','2026-08-16 07:06:43','user','User','PENDING',52,1),
