expect(modal).to_be_visible()

# Verify Status Location column exists
expect(
    modal.locator("//div[@role=\'columnheader\' and @data-field=\'statusLocation\']")
).to_have_text("Status Location")

# Verify From Date column exists
expect(
    modal.locator("//div[@role=\'columnheader\' and @data-field=\'fromDate\']")
).to_have_text("From Date")

# Verify Status Location values are displayed
status_cells = modal.locator("//div[@role=\'gridcell\' and @data-field=\'statusLocation\']")

status_count = status_cells.count()
assert status_count > 0, "No Status Location records found."

for i in range(status_count):
    expect(status_cells.nth(i)).to_be_visible()
    print(f"Status {i+1}: {status_cells.nth(i).text_content().strip()}")

# Verify From Date values are displayed
date_cells = modal.locator("//div[@role=\'gridcell\' and @data-field=\'fromDate\']")

date_count = date_cells.count()
assert date_count > 0, "No From Date records found."

for i in range(date_count):
    expect(date_cells.nth(i)).to_be_visible()
    print(f"Date {i+1}: {date_cells.nth(i).text_content().strip()}")

print("Transit Status Locations modal verified successfully.")','2026-07-02 04:35:16','2026-09-07 15:08:48','user','system','PENDING',41,1),
