(11501,253,'custom','Read and capture the Shipment number near the Planned In Shipment header','Shipment number','import re
from playwright.sync_api import expect

# Locate the Planned In Shipment heading
shipment_heading = page.locator("//h6[contains(normalize-space(),\'Planned In Shipment #\')]")

expect(shipment_heading).to_be_visible()

# Get text
text = shipment_heading.text_content().strip()

# Extract Shipment Number
match = re.search(r"Planned In Shipment\\s*#\\s*(\\d+)", text)
assert match, f"Shipment number not found in: {text}"

shipment_number = match.group(1)

# Store the shipment number
set_var("shipment_number", shipment_number)

print(f"Shipment Number: {shipment_number}")','2026-07-02 08:40:05','2026-07-02 10:37:08','user','User','PENDING',20,1),
