(11504,253,'custom','Verify that the selected Shipment # is displayed on the Receive Intransit screen','Assertion','from playwright.sync_api import expect

# Get expected Shipment Number from variable
expected_shipment = get_var("shipment_number")

# Get actual Shipment Number from the first row under Shipment column
actual_shipment = page.locator(
    "(//div[@role=\'gridcell\' and @data-field=\'shipmentId\'])[1]"
).text_content().strip()

# Assertion
assert actual_shipment == expected_shipment, (
    f"Shipment Number mismatch. Expected: {expected_shipment}, Actual: {actual_shipment}"
)

print("Shipment Number verified successfully.")','2026-07-02 08:52:32','2026-07-02 10:42:55','user','system','PENDING',27,1),
