(11559,253,'custom','Read and capture the Transit ID near the Transit ID header','Read and capture the Transit ID near the Transit ID header','import re

# Get and store Transit ID value
transit_loc = page.locator("//h6[contains(text(),\'Transit ID\')]")

expect(transit_loc).to_be_visible(timeout=15_000)

transit_text = transit_loc.inner_text()

print("Transit Text:", transit_text)

# Capture only Transit ID number
m = re.search(r"Transit ID\\s*:\\s*(\\d+)", transit_text)

transit_id = m.group(1)

print("Transit ID:", transit_id)

set_var("transit_id", transit_id)','2026-07-02 10:42:55','2026-07-02 10:42:55','user','system','PENDING',21,1),
