(11565,254,'assertion','Verify that the BOL GENERATED, Intransit Received, SHIPMENT DELIVERED and Intransit Created status are displayed in the Status column for all applicable search result rows	','from playwright.sync_api import expect

# List of statuses to verify
statuses = [
    "BOL_GENERATED",
    "Intransit Created",
    "Intransit Received",
    "SHIPMENT_DELIVERED"
]

for status in statuses:
    status_buttons = page.locator(f"//button[@title=\'{status}\']")

    count = status_buttons.count()
    assert count > 0, f"No \'{status}\' status found in the search results."

    for i in range(count):
        expect(status_buttons.nth(i)).to_be_visible()

    print(f"Verified {count} \'{status}\' status button(s) in the search result grid.")',NULL,'2026-07-02 10:57:47','2026-07-02 10:59:19','user','User','PENDING',20,1),
