(11642,256,'custom','Verify that the Finish Date and timestamp are updated after 2–3 minutes','Assertion','from playwright.sync_api import expect
from datetime import datetime

locator = "//tr[.//th[contains(normalize-space(.), \'Export All Freight Invoice To Sage\')]]/td[last()]"

finish_date = page.locator(locator)
finish_date.scroll_into_view_if_needed()

expect(finish_date).to_be_visible(timeout=30000)

# Capture and print timestamp
timestamp = finish_date.text_content().strip()
print(f"Finish Date & Time: {timestamp}")

assert timestamp != "", "Finish Date should not be blank"

# Remove timezone (CUT) and validate only date & time
timestamp_without_tz = " ".join(timestamp.split()[:2])
datetime.strptime(timestamp_without_tz, "%m/%d/%Y %H:%M")

print("Finish Date & Timestamp is displayed successfully.")','2026-07-02 14:08:03','2026-09-06 07:33:49','user','User','PENDING',39,1),
