(11699,259,'custom','Verify system should open the Attached Documents screen and display all documents attached to the selected shipment. If no attachments are available, the system should display "No Data"','Assertion','from playwright.sync_api import expect

# Verify Attached Documents dialog is displayed
expect(page.get_by_role("heading", name="Attached Documents")).to_be_visible()

# Verify Print BOL with Attachments button is visible
expect(page.get_by_role("button", name="Print BOL with Attachments")).to_be_visible()

# Verify grid column headers
headers = [
    "Document Name",
    "File Name",
    "Document Type",
    "Heat #",
    "Upload Date",
    "Upload By",
    "Document Attributes",
    "Notes"
]

for header in headers:
    expect(page.get_by_role("columnheader", name=header)).to_be_visible()

# Verify document data or No Data message
no_data = page.get_by_text("No Data")

if no_data.is_visible():
    expect(no_data).to_be_visible()
    print("Verified: No attached documents are available.")
else:
    rows = page.locator("//div[@role=\'row\' and @data-rowindex]")
    expect(rows.first).to_be_visible()
    assert rows.count() > 0, "No attached document records found."
    print(f"Verified: {rows.count()} attached document(s) are displayed.")','2026-07-03 08:01:27','2026-08-16 03:46:04','user','User','PENDING',14,1),
