(12205,265,'custom','The PO transfer inbound column should reflect the qty for which intransit is created','Assertion','from playwright.sync_api import expect

# Get stored FT value (Example: "16.00 Ft")
selected_ft = get_var("selected_ft")

# Convert "16.00 Ft" -> 16.00
selected_ft = float(selected_ft.replace(" Ft", "").strip())

# Multiply by 10
expected_value = selected_ft * 10

# Always format with 2 decimal places
expected_text = f"{expected_value:.2f}"

# Locator
po_transfer_inbound = page.locator(
    "//div[@data-field=\'PoTransferInbound\']//div[contains(@class,\'MuiBox-root\')]"
)

# Verify
expect(po_transfer_inbound).to_have_text(expected_text, timeout=15000)

print(f"Verified PO Transfer Inbound value is {expected_text}.")','2026-07-06 14:21:54','2026-08-11 09:31:00','user','User','PENDING',58,1),
