(12285,265,'custom','The PO Transfer Inbound column should reflect Zero in the qty since all the in transit items are now received','Assertion','from playwright.sync_api import expect

# Verify PO Transfer Inbound value is 0.00
po_transfer_inbound = page.locator(
    "//div[@data-field=\'PoTransferInbound\']//div[contains(@class,\'MuiBox-root\')]"
)

expect(po_transfer_inbound).to_have_text("0.00", timeout=15000)

print("Verified PO Transfer Inbound value is 0.00.")','2026-07-06 15:15:48','2026-08-11 09:31:00','user','system','PENDING',79,1),
