(12519,256,'custom','Verify the system should show the list of freight  invoices which belongs to PPBC only and System should only list Sales Shipment with Order id starts with BC','Assertion','from playwright.sync_api import expect

# Locate all Sales Order cells
sales_orders = page.locator("//div[@role=\'gridcell\' and @data-field=\'orderId\']")

expect(sales_orders.first).to_be_visible()

count = sales_orders.count()

verified = 0

for i in range(count):
    order = sales_orders.nth(i).inner_text().strip()

    # Skip blank cells
    if not order:
        continue

    assert order.startswith("BC"), f"Sales Order \'{order}\' does not start with \'BC\'"
    verified += 1

