(12792,274,'custom','Create and Receive Beams PO In transit','Create and Receive Beams PO','import json
import re
from playwright.sync_api import expect

product = tdm_fetch("{TableProductLogic.${row_number}.BEAMS}")
purchaseOrder = get_var("po_number")


if product == "NA":
    print("product is NA, skipping everything")
else:
    page.wait_for_timeout(2000)

    if isinstance(product, str):
        product = json.loads(product)

    for itemprop in product:
        productId = itemprop["productId"]
        unitPrice = itemprop["price"]
        uom = itemprop["po_quantity_uom"]
        qty = itemprop["qty"]
        page.locator(\'//button[contains(text(),"Create PO Intransit")]\').click()
        page.wait_for_timeout(2000)
        page.locator(\'[name="poNumber"]\').fill(purchaseOrder)
        page.locator(\'h6.MuiTypography-h6\').first.click()
        page.wait_for_timeout(2000)
        page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'transitQty\']").click()
        page.wait_for_timeout(1000)
        page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'transitQty\']//input").fill(qty)
        page.wait_for_timeout(3000)
        page.locator(\'//h6[normalize-space()="Intransit For Receiving PO"]\').click()
        page.wait_for_timeout(7000)
        page.locator(\'//button[text()="Create And Receive PO Intransit"]\').click()
        page.wait_for_timeout(5000)
        try:
            page.locator("//div[@role=\'dialog\']//button[normalize-space()=\'Ok\']").click()
        except:
            print("No ok button is visible")
        page.wait_for_timeout(2000)
        transit_loc = page.locator("//h6[contains(text(),\'Transit ID\')]")
        expect(transit_loc).to_be_visible(timeout=15_000)
        transit_id = re.search(r"Transit ID\\s*:?\\s*(\\d+)", transit_loc.inner_text()).group(1)

        itemprop["transitid"] = transit_id
        
        page.locator(\'[id="print-button"]\').click()
        menu_items = page.locator(\'[role="menuitem"]\')
        expect(menu_items).to_have_count(3)
        expect(menu_items).to_have_text(["Print Documents", "Print Intransit", "Print Receipt"])

        page.keyboard.press("Escape")
        page.locator(\'[role="dialog"] .component-iconify.iconify--simple-line-icons\').click()

    set_var("updatedBeams", product)
    print(product)','2026-07-08 12:30:33','2026-07-08 12:30:33','API_USER','API_USER','PENDING',23,1),
