        product = json.loads(product)

    for itemprop in product:
        productId = itemprop["productId"]
        unitPrice = itemprop["price"]
        uom = itemprop["po_quantity_uom"]
        qty = itemprop["qty"]
        page.locator(\'//button[contains(text(),"Create PO Intransit")]\').click()
        page.wait_for_timeout(2000)
        page.locator(\'[name="poNumber"]\').fill(purchaseOrder)
        page.locator(\'h6.MuiTypography-h6\').first.click()
