(13191,280,'custom','Enter a previous month\'s date in MM/DD/YYYY format','Enter a previous month\'s date','from datetime import datetime
import calendar

today = datetime.now()

# Calculate previous month
if today.month == 1:
    year = today.year - 1
    month = 12
else:
    year = today.year
    month = today.month - 1

# Adjust day if previous month has fewer days
day = min(today.day, calendar.monthrange(year, month)[1])

previous_month_date = f"{month:02d}/{day:02d}/{year}"

# Locate the 3rd date field
date_field = page.locator("(//input[@placeholder=\'MM/DD/YYYY\'])[3]")

# Click the field
date_field.click()

# Select all and clear
page.keyboard.press("Control+A")
