(13319,80,'custom','Enter the Coil Number','Coil #','import random
import string

# Generate a unique 6-character serial number
def generate_serial():
    return \'\'.join(random.choices(string.ascii_uppercase + string.digits, k=6))

# Generate two unique serial numbers
serial_number1 = generate_serial()
serial_number2 = generate_serial()

while serial_number2 == serial_number1:
    serial_number2 = generate_serial()

# Combine them as comma-separated
serial_numbers = f"{serial_number1},{serial_number2}"

# Store the values
set_var("serial_numbers", serial_numbers)

# Fill the same input box
page.locator("//div//textarea[@name=\'motherCoil\']").fill(serial_numbers)

# Print for debugging
print(f\'set_var("serial_numbers", "{serial_numbers}")\')','2026-07-14 08:38:11','2026-07-14 09:16:15','user','User','PENDING',15,1),
