(13494,279,'custom','Verify some of items where qty order and shipped is same are marked as complete- C should be shown under the status column','Assertion','from playwright.sync_api import expect


# ============================================================
# Find Order Details Product Grid
# ============================================================

order_grid = page.locator(
    "//div[@role=\'grid\']"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Product ID\']]"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Qty Ordered\']]"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Qty Shipped\']]"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Status\']]"
).first

expect(
    order_grid
).to_be_visible(timeout=30000)

print("Order Details product grid found.")


# ============================================================
# Get Rows
# ============================================================

rows = order_grid.locator(
    "xpath=.//div[@role=\'rowgroup\']/div[@role=\'row\']"
)

row_count = rows.count()

print(
    f"Total rows found: {row_count}"
)


# ============================================================
# Validation Result
# ============================================================

valid_row_found = False


# ============================================================
# LOOP THROUGH ALL ROWS
# ============================================================

for i in range(row_count):

    row_number = i + 1

    row = rows.nth(i)

    print(
        f"\\nChecking Row {row_number}"
    )


    # ========================================================
    # Get Values From SAME ROW
    # ========================================================

    product_id = row.locator(
        "xpath=.//div[@role=\'gridcell\' and @data-field=\'productId\']"
    ).inner_text().strip()

    qty_ordered = row.locator(
        "xpath=.//div[@role=\'gridcell\' and @data-field=\'quantity\']"
    ).inner_text().strip()

    qty_shipped = row.locator(
        "xpath=.//div[@role=\'gridcell\' and @data-field=\'qtyShipped\']"
    ).inner_text().strip()

    status = row.locator(
        "xpath=.//div[@role=\'gridcell\' and @data-field=\'lineStatus\']"
    ).inner_text().strip().upper()


    # ========================================================
    # Print Current Row
    # ========================================================

    print(
        f"Row {row_number}: "
        f"Product ID={product_id}, "
        f"Qty Ordered={qty_ordered}, "
        f"Qty Shipped={qty_shipped}, "
        f"Status={status}"
    )


    # ========================================================
    # Quantity Comparison
    # ========================================================

    ordered = float(qty_ordered)

    shipped = float(qty_shipped)


    # ========================================================
    # CHECK SAME ROW
    # ========================================================

    if ordered == shipped:

        print(
            f"Row {row_number}: "
            f"Qty Ordered = Qty Shipped"
        )

        if status == "C":

            valid_row_found = True

            print(
                f"✓ Row {row_number}: "
                f"Qty matched and Status=C"
            )

        else:

            print(
                f"Row {row_number}: "
                f"Qty matched but Status={status}"
            )

            print(
                f"→ Row {row_number} is NOT valid"
            )

            print(
                "→ Continuing to next row..."
            )

    else:

        print(
            f"Row {row_number}: "
            f"Qty Ordered != Qty Shipped"
        )

        print(
            "→ Continuing to next row..."
        )


