    "ALL ROWS CHECKED"
)

print(
    "=================================================="
)


# ============================================================
# FINAL ASSERTION
# ============================================================

assert valid_row_found, (
    "No row found where "
    "Qty Ordered = Qty Shipped "
    "AND Status = C."
)


# ============================================================
# PASS
# ============================================================

print(
    "\\n=================================================="
)

print(
    "✓ SCRIPT PASSED"
)

print(
    "A valid row was found."
)

print(
    "Qty Ordered = Qty Shipped"
)

print(
    "Status = C"
)

print(
    "=================================================="
