(14032,172,'custom','Nonstk: Update Qty to Pick and generate picklist','Nonstk: Update Qty to Pick and generate individual product BOL#','import json
import re

product = get_var("nonstkJson")

if product == None:
    print("product is NA, skipping everything")
else:

    if isinstance(product, str):
        product = json.loads(product)

    page.locator("(//button[@title=\'Edit\'])[1]").click()

    index = 0
    for itemprop in product:
        index +=1
        productId = itemprop["input"]["productId"]
        qtyToShip = itemprop["input"]["so_genpick_qtytopick"]
    
        print("qtyToShip:", qtyToShip)
        
        btn = page.locator("//button[normalize-space()=\'New\']")
        for i in range(3):
            btn.click(force=True)
            spinner = page.locator("//*[contains(@class,\'MuiCircularProgress-svg\')]")
            expect(spinner).to_have_count(0, timeout=60000)
        page.wait_for_timeout(7000)

        qtyToShipLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'qtyToShip\']")
        
        found = False
        for attempt in range(1, 7):   
            expect(btn, "...").to_be_enabled(timeout=120000)
            if qtyToShipLoc.count() >= 1:
                found = True
                break
            else:
                btn.click()
                page.wait_for_timeout(5000)


            print(f"attempt {attempt}: qtyToShip row not found for {productId}, retrying")

        qtyToShipInput = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'qtyToShip\']//input")
        if qtyToShipInput.count() < 1:
            qtyToShipLoc.click()
            page.wait_for_timeout(2000)
            qtyToShipInput.fill(str(qtyToShip))
        else:
            qtyToShipInput.fill(str(qtyToShip))
        page.wait_for_timeout(5000)

        page.locator(\'h6.MuiTypography-h6\').first.click()
        page.wait_for_timeout(5000)

        okbutton = page.locator("//button[normalize-space()=\'Ok\']")
        if okbutton.count() > 0:
            okbutton.click()
        page.wait_for_timeout(5000)

        generatePicklistLoc = page.locator(\'//button[normalize-space()="Generate Picklist"]\')
        generatePicklistLoc.click()
        page.wait_for_timeout(5000)
        page.locator("//*[text()=\'Generate BOL\']").click()

        bolHeadingLocator = page.get_by_text(re.compile(r"Planned In Shipment\\s+\\d+", re.I))
        value = re.search(r"Planned In Shipment\\s+(\\d+)", bolHeadingLocator.inner_text(), re.I)
        bol_number = value.group(1)
        print("Generated BOL:", bol_number)
        itemprop["runtime"]["bol_number"] = bol_number

    page.wait_for_timeout(10000)    
    page.locator("(//div[@role=\'dialog\']//*[name()=\'svg\' and contains(@class,\'iconify\')])[1]").click()
    set_var("nonstkJson", product)','2026-07-19 03:33:09','2026-08-12 05:19:14','user','User','PENDING',86,1),
