(14603,293,'custom','Verify hold allocated is updated with PPEAST item and equal to (order quantity minus received quantity)','Hold Allocated','from playwright.sync_api import expect

# Get values from stored variables
qty_ordered = float(get_var("qty_ordered"))
qty_received = float(get_var("qty_received"))

# Locate the Hold Allocated input
hold_allocated_cell = page.locator("//input[@name=\'holdAllocated\']")

# Verify it is visible
expect(hold_allocated_cell).to_be_visible()

# Capture Hold Allocated value from UI
hold_allocated = float(hold_allocated_cell.input_value().strip())

# Calculate expected Hold Allocated value
expected_hold_allocated = qty_ordered - qty_received

# Verify the value
assert hold_allocated == expected_hold_allocated, (
    f"Hold Allocated mismatch. "
    f"Expected: {expected_hold_allocated}, Actual: {hold_allocated}"
)

print(f"✓ Hold Allocated verified successfully: {hold_allocated}")','2026-07-21 10:52:10','2026-09-08 06:20:42','API_USER','User','PENDING',97,1),
