    count = rows.count()
    new_in_this_pass = 0

    for i in range(count):
        row = rows.nth(i)
        data_id = row.get_attribute("data-id")
        if data_id is None or data_id in seen_ids:
            continue
        seen_ids.add(data_id)
        new_in_this_pass += 1

        so_cell = row.locator(\'[data-field="StockOnSoPCS"]\')
        yard_cell = row.locator(\'[data-field="actualYardStockPCS"]\')
        if so_cell.count() == 0 or yard_cell.count() == 0:
            continue

        so_val = parse_num(so_cell.get_attribute("title"))
        yard_val = parse_num(yard_cell.get_attribute("title"))
