(15962,313,'custom','Capture the Product ID from the Product ID column in the first row of the grid','xpath=//body','from playwright.sync_api import expect

dialog = page.locator("[role=\'dialog\']").first
expect(dialog).to_be_visible(timeout=15_000)

row = dialog.locator(".MuiDataGrid-row[data-id]").first
cell = row.locator(\'[data-field="productId"]\')
expect(cell).to_be_visible(timeout=15_000)

product_id = (cell.get_attribute("title") or cell.inner_text()).strip()
