(16091,315,'custom','Select the checkbox of the first product where Stock on S/O equals 0 and Actual Yard Stock is greater than 2',' Stock on S/O,Actual Yard Stock','# Click on PCS column header
page.locator(
    "//div[@role=\'columnheader\' and @data-field=\'StockOnSoPCS\']//div[text()=\'(PCS)\']"
).click()

# Click checkbox for first row where:
# actualYardStockPCS > 2
# StockOnSoPCS = 0

page.locator(
    \'(//div[@role="row" and @data-id]\'
    \'[.//div[@data-field="actualYardStockPCS"]\'
    \'[number(translate(normalize-space(.), ",", "")) > 1]]\'
    \'[.//div[@data-field="StockOnSoPCS"][normalize-space(.) = "0"]]\'
    \')[1]//input[@aria-label="Select row"]\'
).click(force=True)','2026-07-27 06:38:24','2026-07-27 06:38:24','API_USER','API_USER','PENDING',22,1),
