    page.locator("//div[@role=\'gridcell\' and @data-field=\'boOnBulkTransferLBS\']").first
    .inner_text()
    .replace(",", "")
    .strip()
)

actual_yard_stock = (
    page.locator("//div[@role=\'gridcell\' and @data-field=\'actualYardStockLBS\']").first
    .inner_text()
    .replace(",", "")
    .strip()
)

