(16722,325,'custom','Scroll Cumulative Qty (Pcs) in viewport','grid  column Cumulative Qty (Pcs) in view','scroller = page.locator(".MuiDataGrid-virtualScroller")
target = page.locator(\'.MuiDataGrid-virtualScrollerContent [data-field="currentStockPCS"]\')

for _ in range(40):
    if target.count() > 0:
        in_view = scroller.evaluate(
            """(el, cell) => {
                if (!cell) return false;
                const s = el.getBoundingClientRect();
                const c = cell.getBoundingClientRect();
                return c.left >= s.left && c.right <= s.right;
            }""",
            target.first.element_handle(),
        )
        if in_view:
            break

    at_end = scroller.evaluate(
        """el => {
            const max = el.scrollWidth - el.clientWidth;
            el.scrollLeft = Math.min(el.scrollLeft + 300, max);
            return el.scrollLeft >= max - 1;
        }"""
    )
    page.wait_for_timeout(100)

    if at_end and target.count() == 0:
        raise AssertionError("currentStockPCS column not found after scrolling to end")','2026-07-31 14:18:51','2026-09-03 07:39:42','user','system','PENDING',85,1),
(16724,325,'custom','verify  Cumulative Qty (Pcs) after shipment cancellation, Inventory should be returned and added to  Cumulative Qty (Pcs)','Cumulative Qty (Pcs)','from playwright.sync_api import expect

previous_cumulative_qty = get_var("current_cumulative_qty")

cumulative_qty_cell = page.locator(
    "//div[@role=\'gridcell\' and @data-field=\'currentStockPCS\']"
).last

expect(cumulative_qty_cell).to_be_visible()

new_cumulative_qty = int(
    cumulative_qty_cell.text_content().strip().replace(",", "")
)

expected_cumulative_qty = previous_cumulative_qty + 5

assert new_cumulative_qty == expected_cumulative_qty, (
    f"Expected Cumulative Qty to be {expected_cumulative_qty}, "
    f"but found {new_cumulative_qty}"
)

print(f"Previous: {previous_cumulative_qty}")
print(f"Current: {new_cumulative_qty}")
print("Cumulative Qty increased by 5 successfully.")','2026-07-31 14:31:21','2026-09-03 07:39:42','user','system','PENDING',86,1),
