(17120,334,'custom','Scroll Cumulative Qty (Pcs) in viewport','grid  column Cumulative Qty (Pcs) in view','scroller = page.locator(".MuiDataGrid-virtualScroller")
target = page.locator(\'.MuiDataGrid-virtualScrollerContent [data-field="currentStockPCS"]\')

for _ in range(40):
    if target.count() > 0:
        in_view = scroller.evaluate(
            """(el, cell) => {
                if (!cell) return false;
                const s = el.getBoundingClientRect();
                const c = cell.getBoundingClientRect();
                return c.left >= s.left && c.right <= s.right;
            }""",
            target.first.element_handle(),
        )
        if in_view:
            break

    at_end = scroller.evaluate(
        """el => {
            const max = el.scrollWidth - el.clientWidth;
            el.scrollLeft = Math.min(el.scrollLeft + 300, max);
            return el.scrollLeft >= max - 1;
        }"""
    )
    page.wait_for_timeout(100)

    if at_end and target.count() == 0:
        raise AssertionError("currentStockPCS column not found after scrolling to end")','2026-08-03 08:44:09','2026-08-03 08:44:09','API_USER','API_USER','PENDING',39,1),
