(17283,336,'custom','Click Print button and then Print BOL and Verify Verify carrier BOL and reference number and shipping carrier field showing updated in BOL PDF
','Print button and Print BOL button','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.

    Handles:
    - whitespace
    - accents
    - non-breaking spaces
    - punctuation spacing
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


def normalize_carrier_name(value):
    """
    Converts the UI Shipping Carrier value such as:

        PRC100 - PRC TRUCKING LTD

    into the carrier name expected on the BOL:

        PRC TRUCKING LTD

    The carrier code is not printed in the
    NOM DU TRANSPORTEUR field on the PDF.
    """

    if value is None:
        return ""

    value = str(value).strip()

    # Remove carrier code before the first dash.
    #
    # Example:
    # PRC100 - PRC TRUCKING LTD
    #
    # becomes:
    # PRC TRUCKING LTD
    #
    if " - " in value:
        value = value.split(
            " - ",
            1
        )[1]

    elif "-" in value:
        parts = value.split(
            "-",
            1
        )

        if len(parts) == 2:
            value = parts[1]

    return normalize_text(
        value
    )


# ============================================================
# 1. GET MANAGE SHIPMENT VALUES FROM UI
# ============================================================

print(
    "\\n============================================================"
)

print(
    "GETTING BOL / REF # / SHIPPING CARRIER FROM UI"
)

print(
    "============================================================"
)


# ============================================================
# 1A. GET CARRIER BOL
# ============================================================

print(
    "\\nGetting Carrier BOL from UI..."
)


carrier_bol_locator = page.get_by_label(
    "Carrier BOL",
    exact=True
).first


expect(
    carrier_bol_locator
).to_be_visible(
    timeout=10000
)


ui_carrier_bol_raw = (
    carrier_bol_locator.input_value()
)


ui_carrier_bol = (
    ui_carrier_bol_raw.strip()
)


print(
    "Carrier BOL from UI:",
    ui_carrier_bol
)


assert ui_carrier_bol, (
    "\\nCarrier BOL value is empty in UI."
)


# ============================================================
# 1B. GET REFERENCE #
# ============================================================

print(
    "\\nGetting Reference # from UI..."
)


reference_locator = page.get_by_label(
    "Reference #",
    exact=True
).first


expect(
    reference_locator
).to_be_visible(
    timeout=10000
)


ui_reference_raw = (
    reference_locator.input_value()
)


ui_reference = (
    ui_reference_raw.strip()
)


print(
    "Reference # from UI:",
    ui_reference
)


assert ui_reference, (
    "\\nReference # value is empty in UI."
)


# ============================================================
# 1C. GET SHIPPING CARRIER
# ============================================================

print(
    "\\nGetting Shipping Carrier from UI..."
)


shipping_carrier_locator = page.get_by_label(
    "Shipping Carrier",
    exact=True
).first


expect(
    shipping_carrier_locator
).to_be_visible(
    timeout=10000
)


# ------------------------------------------------------------
# Shipping Carrier is a select/autocomplete field.
#
# input_value() gets the currently selected UI value.
# ------------------------------------------------------------

ui_shipping_carrier_raw = (
    shipping_carrier_locator.input_value()
)


ui_shipping_carrier_raw = (
    ui_shipping_carrier_raw.strip()
)


print(
    "Shipping Carrier from UI:",
    ui_shipping_carrier_raw
)


assert ui_shipping_carrier_raw, (
    "\\nShipping Carrier value is empty in UI."
)


# ============================================================
# 1D. NORMALIZE SHIPPING CARRIER FOR PDF
# ============================================================

expected_pdf_carrier = normalize_carrier_name(
    ui_shipping_carrier_raw
)


print(
    "\\nShipping Carrier expected in PDF:",
    expected_pdf_carrier
)


assert expected_pdf_carrier, (
    "\\nUnable to determine Shipping Carrier name "
    "expected in PDF.\\n"
    f"UI Shipping Carrier: {ui_shipping_carrier_raw}"
)


# ============================================================
# 1E. DISPLAY ALL VALUES CAPTURED FROM UI
# ============================================================

print(
    "\\n============================================================"
)

print(
    "VALUES CAPTURED FROM MANAGE SHIPMENT UI"
)

print(
    "============================================================"
)

print(
    "Carrier BOL       :",
    ui_carrier_bol
)

print(
    "Reference #       :",
    ui_reference
)

print(
    "Shipping Carrier  :",
    ui_shipping_carrier_raw
)

print(
    "PDF Carrier Name  :",
    expected_pdf_carrier
)

print(
    "============================================================"
)


# ============================================================
# 2. LOCATE PRINT BUTTON
# ============================================================

print_button = page.locator(
    "//button[@id=\'print-button\' and normalize-space()=\'Print\']"
).first


expect(
    print_button
).to_be_visible(
    timeout=10000
)


expect(
    print_button
).to_be_enabled(
    timeout=10000
)


print(
    "\\nPrint button is visible and enabled."
)


# ============================================================
# 3. COUNT TABS BEFORE PRINT
# ============================================================

tabs_before = len(
    context.pages
)


print(
    "Tabs before clicking Print:",
    tabs_before
)


# ============================================================
# 4. OPEN PRINT MENU
# ============================================================

print(
    "\\n============================================================"
)

print(
    "OPENING PRINT MENU"
)

print(
    "============================================================"
)


print_bol_menu = page.get_by_role(
    "menuitem",
    name="Print BOL",
    exact=True
).last


# ------------------------------------------------------------
# Check whether menu is already open.
# ------------------------------------------------------------

try:

    if print_bol_menu.is_visible():

        print(
            "Print menu is already open."
        )

    else:

        print(
            "Print menu is closed."
        )

        print(
            "Clicking Print button once..."
        )

        print_button.click(
            force=True
        )

except Exception:

    print(
        "Print BOL menu item is not currently available."
    )

    print(
        "Clicking Print button once..."
    )

    print_button.click(
        force=True
    )


# ------------------------------------------------------------
# Wait for Print BOL menu item.
# ------------------------------------------------------------

try:

    expect(
        print_bol_menu
    ).to_be_visible(
        timeout=10000
    )

except Exception as e:

    print(
        "\\nPrint BOL menu item was not found."
    )

    print(
        "Current page URL:",
        page.url
    )

    print(
        "Current Print BOL count:",
        page.get_by_role(
            "menuitem",
            name="Print BOL",
            exact=True
        ).count()
    )

    raise AssertionError(
        "\\nPrint BOL menu could not be opened.\\n\\n"
        "The Print button was clicked, but the "
        "\'Print BOL\' menuitem did not become visible.\\n\\n"
        f"Original error:\\n{e}"
    )


assert print_bol_menu.is_visible(), (
    "\\nPrint BOL menu item is not visible."
)


print(
    "Print BOL menu opened successfully."
)


# ============================================================
# 5. PDF RESPONSE PREDICATE
# ============================================================

def is_bol_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_shipment_pdf = (
            "/api/scadmin/control/shipment.pdf"
            in response_url
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        return (
            is_shipment_pdf
            and is_pdf_content
        )

    except Exception:

        return False


# ============================================================
# 6. CLICK PRINT BOL
# ============================================================

print(
    "\\n============================================================"
)

print(
    "CLICKING PRINT BOL"
)

print(
    "============================================================"
)


pdf_response = None
pdf_page = None


try:

    # --------------------------------------------------------
    # Register listeners BEFORE clicking Print BOL.
    # --------------------------------------------------------

    with page.expect_response(
        is_bol_pdf_response,
        timeout=30000
    ) as pdf_response_info:

        with context.expect_page(
            timeout=30000
        ) as new_page_info:

            print_bol_menu.click(
                force=True
            )


    # --------------------------------------------------------
    # Get actual PDF browser response.
    # --------------------------------------------------------

    pdf_response = (
        pdf_response_info.value
    )


    # --------------------------------------------------------
    # Get newly opened PDF tab.
    # --------------------------------------------------------

    pdf_page = (
        new_page_info.value
    )


    print(
        "Print BOL clicked successfully."
    )

    print(
        "New PDF tab detected."
    )


except Exception as e:

    raise AssertionError(
        "\\nPrint BOL was clicked, but the "
        "PDF response/new tab was not detected.\\n\\n"
        f"Error: {e}"
    )


# ============================================================
# 7. WAIT FOR PDF TAB
# ============================================================

try:

    pdf_page.wait_for_load_state(
        "domcontentloaded",
        timeout=30000
    )

except Exception:

    # Chrome PDF viewer may not expose normal DOM state.
    pass


print(
    "PDF tab URL:",
    pdf_page.url
)


# ============================================================
# 8. VERIFY PDF RESPONSE
# ============================================================

pdf_url = pdf_response.url

pdf_status = pdf_response.status

pdf_content_type = (
    pdf_response.headers.get(
        "content-type",
        ""
    ).lower()
)


print(
    "\\n================ PDF RESPONSE ================"
)

print(
    "PDF URL:",
    pdf_url
)

print(
    "HTTP Status:",
    pdf_status
)

print(
    "Content-Type:",
    pdf_content_type
)

print(
    "=============================================="
)


assert pdf_status == 200, (

    "\\nPDF HTTP response failed.\\n"

    f"Expected: 200\\n"

    f"Actual: {pdf_status}\\n"

    f"URL: {pdf_url}"
)


print(
    "PDF HTTP response verification PASSED."
)


assert (
    "application/pdf"
    in pdf_content_type
), (

    "\\nExpected application/pdf.\\n"

    f"Actual Content-Type: {pdf_content_type}\\n"

    f"URL: {pdf_url}"
)


print(
    "PDF Content-Type verification PASSED."
)


# ============================================================
# 9. VERIFY NEW PDF TAB
# ============================================================

tabs_after = len(
    context.pages
)


print(
    "\\nTabs before clicking Print BOL:",
    tabs_before
)

print(
    "Tabs after clicking Print BOL:",
    tabs_after
)


assert tabs_after > tabs_before, (

    "\\nBOL PDF did not open in a new tab.\\n"

    f"Tabs before: {tabs_before}\\n"

    f"Tabs after: {tabs_after}"
)


print(
    "PDF opened in new tab successfully."
)


# ============================================================
# 10. GET PDF BYTES FROM BROWSER RESPONSE
# ============================================================
#
# Use the authenticated browser response directly.
#
# Do NOT use:
#
#     context.request.get(pdf_url)
#
# ============================================================

print(
    "\\nDownloading Print BOL PDF..."
)

print(
    "Reading PDF body from actual browser response..."
)


pdf_bytes = (
    pdf_response.body()
)


assert pdf_bytes, (
    "PDF response body is empty."
)


print(
    "PDF body downloaded successfully."
)

print(
    "PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 11. VERIFY PDF HEADER
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (

    "\\nDownloaded browser response is NOT a valid PDF.\\n"

    f"PDF URL: {pdf_url}\\n"

    f"HTTP Status: {pdf_status}\\n"

    f"Content-Type: {pdf_content_type}\\n"

    f"PDF body size: {len(pdf_bytes)} bytes\\n"

    f"First 100 bytes: {repr(pdf_bytes[:100])}"
)


print(
    "Downloaded PDF signature verification PASSED."
)


# ============================================================
# 12. SAVE PDF
# ============================================================

download_dir = "/tmp/downloads"


os.makedirs(
    download_dir,
    exist_ok=True
)


downloaded_pdf_path = os.path.join(
    download_dir,
    "Print_BOL.pdf"
)


if os.path.exists(
    downloaded_pdf_path
):

    os.remove(
        downloaded_pdf_path
    )


with open(
    downloaded_pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )


assert os.path.exists(
    downloaded_pdf_path
), (
    "Downloaded PDF file does not exist."
)


downloaded_file_size = (
    os.path.getsize(
        downloaded_pdf_path
    )
)


assert downloaded_file_size > 0, (
    "Downloaded PDF file is empty."
)


print(
    "\\nPDF saved successfully:",
    downloaded_pdf_path
)

print(
    "Downloaded PDF size:",
    downloaded_file_size,
    "bytes"
)

print(
    "PDF download verification PASSED."
)


# ============================================================
# 13. READ PDF WITH PYPDF
# ============================================================

reader = PdfReader(
    BytesIO(pdf_bytes)
)


assert len(
    reader.pages
) > 0, (
    "PDF contains no pages."
)


print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 14. EXTRACT PDF TEXT
# ============================================================

pdf_text = ""


for pdf_document_page in reader.pages:

    page_text = (
        pdf_document_page.extract_text()
        or ""
    )

    pdf_text += (
        page_text
        + "\\n"
    )


assert pdf_text.strip(), (
    "Unable to extract text from BOL PDF."
)


print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n=============================================="
)


# ============================================================
# 15. NORMALIZE PDF TEXT
# ============================================================

pdf_text_normalized = normalize_text(
    pdf_text
)


print(
    "\\nNormalized PDF text:"
)

print(
    pdf_text_normalized
)


# ============================================================
# 16. VALIDATE PDF VALUES AGAINST UI VALUES
# ============================================================
#
# We ONLY validate:
#
#     UI Shipping Carrier -> PDF NOM DU TRANSPORTEUR
#     UI Carrier BOL      -> PDF BOL
#     UI Reference #      -> PDF REF #
#
# We intentionally do NOT validate:
#
#     Item numbers
#     Quantity
#     Length
#     Unit
#     Weight
#     Description
#     Any other PDF fields
# ============================================================

print(
    "\\n============================================================"
)

print(
    "VALIDATING BOL / REF # / SHIPPING CARRIER"
)

print(
    "============================================================"
)


# ============================================================
# 16A. EXPECTED VALUES
# ============================================================

expected_pdf_bol = normalize_text(
    ui_carrier_bol
)

expected_pdf_reference = normalize_text(
    ui_reference
)

expected_pdf_carrier_normalized = normalize_text(
    expected_pdf_carrier
)


print(
    "\\nExpected PDF values:"
)

print(
    "NOM DU TRANSPORTEUR:",
    expected_pdf_carrier
)

print(
    "BOL:",
    ui_carrier_bol
)

print(
    "REF #:",
    ui_reference
)


# ============================================================
# 16B. VALIDATE NOM DU TRANSPORTEUR
# ============================================================
#
# Expected PDF structure:
#
#     NOM DU TRANSPORTEUR
#     PRC TRUCKING LTD
#
# We validate the carrier specifically after the label.
# ============================================================

print(
    "\\nValidating NOM DU TRANSPORTEUR..."
)


carrier_pdf_pattern = re.compile(

    r"nom\\s+du\\s+transporteur"

    r"\\s+"

    + re.escape(
        expected_pdf_carrier_normalized
    ),

    re.IGNORECASE
)


carrier_pdf_match = (
    carrier_pdf_pattern.search(
        pdf_text_normalized
    )
)


assert carrier_pdf_match, (

    "\\nNOM DU TRANSPORTEUR validation failed.\\n\\n"

    f"Expected Carrier: "
    f"{expected_pdf_carrier_normalized}\\n\\n"

    f"PDF URL:\\n"
    f"{pdf_url}\\n\\n"

    f"Normalized PDF Text:\\n"
    f"{pdf_text_normalized}"
)


print(
    "NOM DU TRANSPORTEUR verification PASSED."
)

print(
    "PDF Carrier:",
    expected_pdf_carrier
)


# ============================================================
# 16C. VALIDATE BOL
# ============================================================
#
# Expected PDF structure:
#
#     BOL
#     BOL54321
#
# ============================================================

print(
    "\\nValidating BOL..."
)


bol_pdf_pattern = re.compile(

    r"\\bbol\\b"

    r"\\s+"

    + re.escape(
        expected_pdf_bol
    )

    + r"(?:\\s|$)",

    re.IGNORECASE
)


bol_pdf_match = (
    bol_pdf_pattern.search(
        pdf_text_normalized
    )
)


assert bol_pdf_match, (

    "\\nBOL validation failed.\\n\\n"

    f"Expected BOL: "
    f"{ui_carrier_bol}\\n\\n"

    f"PDF URL:\\n"
    f"{pdf_url}\\n\\n"

    f"Normalized PDF Text:\\n"
    f"{pdf_text_normalized}"
)


print(
    "BOL verification PASSED."
)

print(
    "PDF BOL:",
    ui_carrier_bol
)


# ============================================================
# 16D. VALIDATE REF #
# ============================================================
#
# Expected PDF structure:
#
#     REF #
#     REF54321
#
# ============================================================

print(
    "\\nValidating REF #..."
)


reference_pdf_pattern = re.compile(

    r"\\bref\\s*#?"

    r"\\s+"

    + re.escape(
        expected_pdf_reference
    )

    + r"(?:\\s|$)",

    re.IGNORECASE
)


reference_pdf_match = (
    reference_pdf_pattern.search(
        pdf_text_normalized
    )
)


assert reference_pdf_match, (

    "\\nREF # validation failed.\\n\\n"

    f"Expected Reference #: "
    f"{ui_reference}\\n\\n"

    f"PDF URL:\\n"
    f"{pdf_url}\\n\\n"

    f"Normalized PDF Text:\\n"
    f"{pdf_text_normalized}"
)


print(
    "REF # verification PASSED."
)

print(
    "PDF REF #:",
    ui_reference
)


# ============================================================
# 17. VERIFY SAVED PDF
# ============================================================

with open(
    downloaded_pdf_path,
    "rb"
) as downloaded_pdf_file:

    downloaded_pdf_bytes = (
        downloaded_pdf_file.read()
    )


assert downloaded_pdf_bytes.startswith(
    b"%PDF"
), (
    "Saved PDF is not valid."
)


assert (
    downloaded_pdf_bytes
    == pdf_bytes
), (
    "Saved PDF bytes do not match "
    "the browser PDF response."
)


print(
    "Saved PDF bytes verification PASSED."
)


# ============================================================
# 18. RE-OPEN SAVED PDF
# ============================================================

downloaded_reader = PdfReader(
    BytesIO(
        downloaded_pdf_bytes
    )
)


assert len(
    downloaded_reader.pages
) > 0, (
    "Saved PDF contains no pages."
)


downloaded_pdf_text = ""


for downloaded_page in downloaded_reader.pages:

    downloaded_pdf_text += (
        downloaded_page.extract_text()
        or ""
    )

    downloaded_pdf_text += "\\n"


downloaded_pdf_text_normalized = (
    normalize_text(
        downloaded_pdf_text
    )
)


assert downloaded_pdf_text_normalized, (
    "Downloaded PDF text is empty."
)


print(
    "\\nSaved PDF reopened successfully."
)


# ============================================================
# 19. VERIFY SAVED PDF - NOM DU TRANSPORTEUR
# ============================================================

print(
