(18021,349,'custom','Verify Hold Allocate on Inventory Hold screen','Hold Allocate','from playwright.sync_api import expect

# Retrieve stored values
original_hold_allocated = float(
    str(get_var("original_hold_allocated")).replace(",", "").replace("$", "").strip()
)
qty_shipped = float(
    str(get_var("qty_shipped")).replace(",", "").replace("$", "").strip()
)

# Calculate expected Hold Allocated
expected_hold_allocated = original_hold_allocated - qty_shipped

# Locate the Hold Allocate cell (data-field="avilQtyToConsume")
hold_allocate_cell = page.locator(
    "//div[@role=\'gridcell\' and @data-field=\'avilQtyToConsume\']"
).first

# Verify the cell is visible
expect(hold_allocate_cell).to_be_visible()

# Capture the value
hold_allocate_value = hold_allocate_cell.text_content().strip()

# Capture current Hold Allocated value from UI
actual_hold_allocated = float(
    hold_allocate_value.input_value().replace(",", "").replace("$", "").strip()
)

# Verify calculated value matches UI
assert actual_hold_allocated == expected_hold_allocated, (
    f"Expected Hold Allocated: {expected_hold_allocated:.2f}, "
    f"but found: {actual_hold_allocated:.2f}"
)

print(
    f"Verified Hold Allocated is correct on inventory hold screen: "
    f"{actual_hold_allocated:.2f} = "
    f"{original_hold_allocated:.2f} - {qty_shipped:.2f}"
)','2026-08-07 14:27:00','2026-09-08 10:32:02','user','User','PENDING',100,1),
(18022,349,'custom','Scroll Hold Allocate in viewport','Hold Allocate','scroller = page.locator(".MuiDataGrid-virtualScroller")
target = page.locator(\'.MuiDataGrid-virtualScrollerContent [data-field="avilQtyToConsume"]\')

for _ in range(40):
    if target.count() > 0:
        in_view = scroller.evaluate(
            """(el, cell) => {
                if (!cell) return false;
                const s = el.getBoundingClientRect();
                const c = cell.getBoundingClientRect();
                return c.left >= s.left && c.right <= s.right;
            }""",
            target.first.element_handle(),
        )
        if in_view:
            break

    at_end = scroller.evaluate(
        """el => {
            const max = el.scrollWidth - el.clientWidth;
            el.scrollLeft = Math.min(el.scrollLeft + 300, max);
            return el.scrollLeft >= max - 1;
        }"""
    )
    page.wait_for_timeout(100)

    if at_end and target.count() == 0:
        raise AssertionError("avilQtyToConsume column not found after scrolling to end")','2026-08-07 14:40:20','2026-09-08 10:32:02','user','system','PENDING',99,1),
