(18569,356,'custom','Enter User Login, First, Last Name, Password & Confirm password',' User Login, First, Last Name, Password & Confirm Password','import uuid
from playwright.sync_api import expect

# Generate a unique alphanumeric ID
unique_id = uuid.uuid4().hex[:8]

# Generate unique values
# First name and last name: alphabets only
first_name = f"First{unique_id}"
last_name = f"Last{unique_id}"

# User login: alphanumeric only
user_login = f"User{unique_id}"

# Password: alphanumeric only
password = f"Pass{unique_id}123"

# Enter User Login
user_login_field = page.locator("input[name=\'userLogin\']")
expect(user_login_field).to_be_visible()
user_login_field.fill(user_login)

# Enter First Name
first_name_field = page.locator("input[name=\'firstName\']")
expect(first_name_field).to_be_visible()
first_name_field.fill(first_name)

# Enter Last Name
last_name_field = page.locator("input[name=\'lastNameEdit\']")
expect(last_name_field).to_be_visible()
last_name_field.fill(last_name)

# Enter Password
password_field = page.locator("input[name=\'passwordEdit\']")
expect(password_field).to_be_visible()
password_field.fill(password)

# Enter Confirm Password
confirm_password_field = page.locator("input[name=\'passwordVerify\']")
expect(confirm_password_field).to_be_visible()
confirm_password_field.fill(password)

# Validate entered values
expect(user_login_field).to_have_value(user_login)
expect(first_name_field).to_have_value(first_name)
expect(last_name_field).to_have_value(last_name)
expect(password_field).to_have_value(password)
expect(confirm_password_field).to_have_value(password)

# Store values for later use
set_var("user_login", user_login)
set_var("first_name", first_name)
set_var("last_name", last_name)
set_var("password", password)','2026-08-10 13:35:11','2026-08-11 16:22:23','user','User','PENDING',9,1),
