(18809,298,'custom','Click on Export to csv file and validate Saved file name and location','Export to CSV','import os
import csv

# Locate and click the Export as CSV button
export_button = page.locator("xpath=//span[text()=\'Export as CSV\']")

expect(export_button).to_be_visible()

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# Download information
filename = download.suggested_filename

print("Filename:", filename)

# Download location
download_dir = "/tmp/downloads"
os.makedirs(download_dir, exist_ok=True)

# Save downloaded file
file_path = os.path.join(download_dir, filename)

download.save_as(file_path)

print("Saved file:", file_path)

# Validate downloaded file
assert os.path.exists(file_path), (
    f"File was not saved: {file_path}"
)

assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)

# --------------------------------------------------
# Verify Item Level Changes.csv
# --------------------------------------------------

item_level_file = os.path.join(
    download_dir,
    "Item Level Changes.csv"
)

# Verify Item Level Changes.csv exists
assert os.path.exists(item_level_file), (
    f"Item Level Changes.csv was not found: {item_level_file}"
)

# Expected column names
expected_columns = [
    "Date & Time of Change",
    "Product",
    "Field Name",
    "Old Value",
    "New Value",
    "Item #",
    "User ID",
    "Number of Changes"
]

# Read CSV
with open(
    item_level_file,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)
    rows = list(reader)

# Verify CSV contains expected rows
assert len(rows) >= 4, (
    "Item Level Changes.csv does not contain the expected data."
)

# Header is on Row 3
actual_columns = [
    column.strip()
    for column in rows[2]
]

# Verify column names
assert actual_columns == expected_columns, (
    f"Column names mismatch.\\n"
    f"Expected: {expected_columns}\\n"
    f"Actual: {actual_columns}"
)

print("Column names verified successfully.")

# Data row is on Row 4
data_row = rows[3]

# Verify values are present
assert len(data_row) >= len(expected_columns), (
    "Values are missing under the expected columns."
)

for column, value in zip(expected_columns, data_row):
    assert value.strip() != "", (
        f"Value is missing under column: {column}"
    )

print("Values under all columns verified successfully.")

# Print verified values
for column, value in zip(expected_columns, data_row):
    print(f"{column}: {value}")

# --------------------------------------------------
# Delete Item Level Changes.csv after verification
# --------------------------------------------------

os.remove(item_level_file)

print("Deleted file:", item_level_file)','2026-08-11 14:02:16','2026-08-22 12:21:07','user','User','PENDING',37,1),
