(19021,360,'custom','Verify System should display the coil consumed with qty change as -ve value','Assertion','# ============================================================
# Verify Qty Change (+/- Pcs) Values
# ============================================================

pcs_values = page.locator(
    "div[role=\'gridcell\'][data-field=\'qtyChangePCE\']"
)

pcs_count = pcs_values.count()

assert pcs_count > 0, (
    "No values found in Qty Change (+/- Pcs) column."
)

pcs_valid_count = 0

for i in range(pcs_count):

    value = pcs_values.nth(i).inner_text().strip()

    # --------------------------------------------------------
    # Skip blank cells
    # --------------------------------------------------------

    if not value:
        continue

    # --------------------------------------------------------
    # Remove commas for numeric validation
    # Example: 15,602.00 -> 15602.00
    # --------------------------------------------------------

    clean_value = value.replace(",", "")

    # --------------------------------------------------------
    # Verify numeric value
    # --------------------------------------------------------

    try:

        numeric_value = float(clean_value)

    except ValueError:

        raise AssertionError(
            f"Qty Change (+/- Pcs) at row {i + 1} "
            f"is not a valid numeric value: {value}"
        )

    pcs_valid_count += 1

    # --------------------------------------------------------
    # Print value for debugging
    # --------------------------------------------------------

    print(
        f"Qty Change (+/- Pcs) "
        f"Row {i + 1}: {value}"
    )


# ============================================================
# Verify Qty Change (+/- Pcs) Contains Values
# ============================================================

assert pcs_valid_count > 0, (
    "Qty Change (+/- Pcs) column "
    "does not contain any valid values."
)

print(
    "All available values in Qty Change (+/- Pcs) "
    "are valid numeric values."
)

print(
    "Total valid Qty Change (+/- Pcs) values:",
    pcs_valid_count
)


# ============================================================
# Verify Qty Change (+/-) Values
# ============================================================

qty_values = page.locator(
    "div[role=\'gridcell\'][data-field=\'qtyChange\']"
)

qty_count = qty_values.count()

assert qty_count > 0, (
    "No values found in Qty Change (+/-) column."
)

qty_valid_count = 0

for i in range(qty_count):

    value = qty_values.nth(i).inner_text().strip()

    # --------------------------------------------------------
    # Skip blank cells
    # --------------------------------------------------------

    if not value:
        continue

    # --------------------------------------------------------
    # Remove commas for numeric validation
    # Example: 15,602.00 -> 15602.00
    # --------------------------------------------------------

    clean_value = value.replace(",", "")

    # --------------------------------------------------------
    # Verify numeric value
    # --------------------------------------------------------

    try:

        numeric_value = float(clean_value)

    except ValueError:

        raise AssertionError(
            f"Qty Change (+/-) at row {i + 1} "
            f"is not a valid numeric value: {value}"
        )

    qty_valid_count += 1

    # --------------------------------------------------------
    # Print value for debugging
    # --------------------------------------------------------

    print(
        f"Qty Change (+/-) "
        f"Row {i + 1}: {value}"
    )


# ============================================================
# Verify Qty Change (+/-) Contains Values
# ============================================================

assert qty_valid_count > 0, (
    "Qty Change (+/-) column "
    "does not contain any valid values."
)

print(
    "All available values in Qty Change (+/-) "
    "are valid numeric values."
)

print(
    "Total valid Qty Change (+/-) values:",
    qty_valid_count
)


# ============================================================
# Final Verification
# ============================================================

print(
    "SUCCESS: All available values in both "
    "Qty Change columns are valid numeric values."
)','2026-08-12 07:32:22','2026-09-03 17:43:32','user','User','PENDING',33,1),
(19022,360,'custom','Verify Daily Stock Movement Report.CSV should be exported and should display numbers for coil consumption','Assertion','import os
import csv


# ============================================================
# Export Daily Stock Movement Report as CSV
# ============================================================

export_button = page.locator(
    "xpath=//span[text()=\'Export as CSV\']"
)

expect(export_button).to_be_visible()

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value


# ============================================================
# Download Information
# ============================================================

filename = download.suggested_filename

print("Filename:", filename)


# ============================================================
# Download Location
# ============================================================

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)


# ============================================================
# Save Downloaded File
# ============================================================

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print(
    "Saved file:",
    file_path
)


# ============================================================
# Verify File Exists
# ============================================================

assert os.path.exists(file_path), (
    f"File was not saved: {file_path}"
)


# ============================================================
# Verify File Is Not Empty
# ============================================================

assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)


# ============================================================
# Verify Daily Stock Movement Report CSV
# ============================================================

daily_stock_file = file_path

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded: {filename}"
)

print(
    "Daily Stock Movement Report CSV found successfully."
)


# ============================================================
# Read CSV
# ============================================================

with open(
    daily_stock_file,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)

    rows = list(reader)


# ============================================================
# Verify CSV Contains Data
# ============================================================

assert len(rows) >= 2, (
    "Daily Stock Movement Report.csv "
    "does not contain expected data."
)


# ============================================================
# Find Header Row
# ============================================================

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip()
        for column in row
    ]

    if (
        "Qty Change (+/- Pcs)" in cleaned_row
        and "Qty Change (+/-)" in cleaned_row
    ):

        header_row_index = index

        break


assert header_row_index is not None, (
    "Qty Change (+/- Pcs) and "
    "Qty Change (+/-) columns were not found."
)


# ============================================================
# Get Headers
# ============================================================

headers = [
    column.strip()
    for column in rows[header_row_index]
]


# ============================================================
# Get Column Indexes
# ============================================================

pcs_column_index = headers.index(
    "Qty Change (+/- Pcs)"
)

qty_column_index = headers.index(
    "Qty Change (+/-)"
)

print(
    "Qty Change (+/- Pcs) column found."
)

print(
    "Qty Change (+/-) column found."
)


# ============================================================
# Get Data Rows
# ============================================================

data_rows = rows[
    header_row_index + 1:
]

assert len(data_rows) > 0, (
    "No data rows found below the headers."
)


# ============================================================
# Counters
# ============================================================

pcs_valid_count = 0
qty_valid_count = 0

pcs_negative_count = 0
pcs_positive_count = 0
pcs_zero_count = 0

qty_negative_count = 0
qty_positive_count = 0
qty_zero_count = 0


# ============================================================
