(19082,360,'custom','Verify  qty change should display -ve value and CSV should be exported','Assertion','import os
import csv


# ============================================================
# Export Daily Stock Movement Report as CSV
# ============================================================

export_button = page.locator(
    "xpath=//span[text()=\'Export as CSV\']"
)

expect(export_button).to_be_visible()

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value


# ============================================================
# Download Information
# ============================================================

filename = download.suggested_filename

print("Filename:", filename)


# ============================================================
# Download Location
# ============================================================

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)


# ============================================================
# Save Downloaded File
# ============================================================

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print(
    "Saved file:",
    file_path
)


# ============================================================
# Verify File Exists
# ============================================================

assert os.path.exists(file_path), (
    f"File was not saved: {file_path}"
)


# ============================================================
# Verify File Is Not Empty
# ============================================================

assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)


# ============================================================
# Verify Daily Stock Movement Report.csv
# ============================================================

daily_stock_file = file_path

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded: {filename}"
)

print(
    "Daily Stock Movement Report CSV found successfully."
)


# ============================================================
# Read CSV
# ============================================================

with open(
    daily_stock_file,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)

    rows = list(reader)


# ============================================================
# Verify CSV Contains Data
# ============================================================

assert len(rows) >= 2, (
    "Daily Stock Movement Report.csv "
    "does not contain expected data."
)


# ============================================================
# Find Header Row
# ============================================================

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip()
        for column in row
    ]

    if (
        "Qty Change (+/- Pcs)" in cleaned_row
        and "Qty Change (+/-)" in cleaned_row
    ):

        header_row_index = index

        break


assert header_row_index is not None, (
    "Qty Change (+/- Pcs) and "
    "Qty Change (+/-) columns were not found."
)


# ============================================================
# Get Headers
# ============================================================

headers = [
    column.strip()
    for column in rows[header_row_index]
]


# ============================================================
# Get Column Indexes
# ============================================================

pcs_column_index = headers.index(
    "Qty Change (+/- Pcs)"
)

qty_column_index = headers.index(
    "Qty Change (+/-)"
)

print(
    "Qty Change (+/- Pcs) column found."
)

print(
    "Qty Change (+/-) column found."
)


# ============================================================
# Get Data Rows
# ============================================================

data_rows = rows[
    header_row_index + 1:
]

assert len(data_rows) > 0, (
    "No data rows found below the headers."
)


# ============================================================
# Variables for Validation
# ============================================================

pcs_values = []
qty_values = []

negative_pcs_values = []
negative_qty_values = []


# ============================================================
# Validate Qty Change (+/- Pcs)
# ============================================================

for row_number, row in enumerate(
    data_rows,
    start=header_row_index + 2
):

    if len(row) <= pcs_column_index:
        continue

    value = row[
        pcs_column_index
    ].strip()

    # Skip blank cells
    if not value:
        continue

    # --------------------------------------------------------
    # Convert value to numeric
    # --------------------------------------------------------

    try:

        numeric_value = float(
            value.replace(",", "")
        )

    except ValueError:

        raise AssertionError(
            "Invalid Qty Change (+/- Pcs) "
            f"value at CSV row {row_number}: "
            f"{value}"
        )

    pcs_values.append(
        numeric_value
    )

    # --------------------------------------------------------
    # Track negative values
    # --------------------------------------------------------

    if numeric_value < 0:

        negative_pcs_values.append(
            numeric_value
        )


# ============================================================
# Verify Qty Change (+/- Pcs) Contains Data
# ============================================================

assert len(pcs_values) > 0, (
    "No valid values found under "
    "Qty Change (+/- Pcs)."
)

print(
    "Qty Change (+/- Pcs) contains valid numeric data."
)

print(
    "Total Qty Change (+/- Pcs) values:",
    len(pcs_values)
)

print(
    "Negative Qty Change (+/- Pcs) values:",
    len(negative_pcs_values)
)


# ============================================================
# Validate Qty Change (+/-)
# ============================================================

for row_number, row in enumerate(
    data_rows,
    start=header_row_index + 2
):

    if len(row) <= qty_column_index:
        continue

    value = row[
        qty_column_index
    ].strip()

    # Skip blank cells
    if not value:
        continue

    # --------------------------------------------------------
    # Convert value to numeric
    # --------------------------------------------------------

    try:

        numeric_value = float(
            value.replace(",", "")
        )

    except ValueError:

        raise AssertionError(
            "Invalid Qty Change (+/-) "
            f"value at CSV row {row_number}: "
            f"{value}"
        )

    qty_values.append(
        numeric_value
    )

    # --------------------------------------------------------
    # Track negative values
    # --------------------------------------------------------

    if numeric_value < 0:

        negative_qty_values.append(
            numeric_value
        )


# ============================================================
# Verify Qty Change (+/-) Contains Data
# ============================================================

assert len(qty_values) > 0, (
    "No valid values found under "
    "Qty Change (+/-)."
)

print(
    "Qty Change (+/-) contains valid numeric data."
)

print(
    "Total Qty Change (+/-) values:",
    len(qty_values)
)

print(
    "Negative Qty Change (+/-) values:",
    len(negative_qty_values)
)


# ============================================================
# Verify Negative Stock Movement Exists
# ============================================================

assert len(negative_pcs_values) > 0, (
    "No negative values found under "
    "Qty Change (+/- Pcs)."
)

assert len(negative_qty_values) > 0, (
    "No negative values found under "
    "Qty Change (+/-)."
)


# ============================================================
# Final Success Message
# ============================================================

print(
    "SUCCESS: Daily Stock Movement Report CSV "
    "contains valid numeric values in both "
    "Qty Change columns and negative stock "
    "movement values were found."
)


# ============================================================
# Delete CSV After Verification
# ============================================================

assert os.path.exists(
    daily_stock_file
), (
    f"CSV file does not exist: "
    f"{daily_stock_file}"
)

os.remove(
    daily_stock_file
)

assert not os.path.exists(
    daily_stock_file
), (
    f"CSV file was not deleted: "
    f"{daily_stock_file}"
)

print(
    "Deleted file:",
    daily_stock_file
