(19268,366,'custom','Verify  qty change should display -ve value and CSV should be exported','Assertion','import os
import csv

# --------------------------------------------------
# Export Daily Stock Movement Report as CSV
# --------------------------------------------------

export_button = page.locator(
    "xpath=//span[text()=\'Export as CSV\']"
)

expect(export_button).to_be_visible()

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# Download information
filename = download.suggested_filename

print("Filename:", filename)

# Download location
download_dir = "/tmp/downloads"
os.makedirs(download_dir, exist_ok=True)

# Save downloaded file
file_path = os.path.join(download_dir, filename)

download.save_as(file_path)

print("Saved file:", file_path)

# Verify file exists
assert os.path.exists(file_path), (
    f"File was not saved: {file_path}"
)

# Verify file is not empty
assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)

# --------------------------------------------------
# Verify Daily Stock Movement Report.csv
# --------------------------------------------------

daily_stock_file = file_path

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded: {filename}"
)

print("Daily Stock Movement Report CSV found successfully.")

# --------------------------------------------------
# Read CSV
# --------------------------------------------------

with open(
    daily_stock_file,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)
    rows = list(reader)

# Verify CSV contains data
assert len(rows) >= 2, (
    "Daily Stock Movement Report.csv does not contain expected data."
)

# --------------------------------------------------
# Find Header Row
# --------------------------------------------------

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [column.strip() for column in row]

    if (
        "Qty Change (+/- Pcs)" in cleaned_row
        and "Qty Change (+/-)" in cleaned_row
    ):
        header_row_index = index
        break

assert header_row_index is not None, (
    "Qty Change (+/- Pcs) and Qty Change (+/-) columns were not found."
)

headers = [
    column.strip()
    for column in rows[header_row_index]
]

# Get column indexes
pcs_column_index = headers.index(
    "Qty Change (+/- Pcs)"
)

qty_column_index = headers.index(
    "Qty Change (+/-)"
)

print("Qty Change (+/- Pcs) column found.")
print("Qty Change (+/-) column found.")

# --------------------------------------------------
# Get Data Rows
# --------------------------------------------------

data_rows = rows[header_row_index + 1:]

assert len(data_rows) > 0, (
    "No data rows found below the headers."
)

# --------------------------------------------------
# Verify Qty Change (+/- Pcs)
# --------------------------------------------------

for row_number, row in enumerate(
    data_rows,
    start=header_row_index + 2
):

    if len(row) <= pcs_column_index:
        continue

    value = row[pcs_column_index].strip()

    # Skip blank cells
    if not value:
        continue

    # Verify negative value
    assert value.startswith("-"), (
        f"Qty Change (+/- Pcs) value is not negative "
        f"at CSV row {row_number}: {value}"
    )

print(
    "All available values under Qty Change (+/- Pcs) "
    "are negative."
)

# --------------------------------------------------
# Verify Qty Change (+/-)
# --------------------------------------------------

for row_number, row in enumerate(
    data_rows,
    start=header_row_index + 2
):

    if len(row) <= qty_column_index:
        continue

    value = row[qty_column_index].strip()

    # Skip blank cells
    if not value:
        continue

    # Verify negative value
    assert value.startswith("-"), (
        f"Qty Change (+/-) value is not negative "
        f"at CSV row {row_number}: {value}"
    )

print(
    "All available values under Qty Change (+/-) "
    "are negative."
)

# --------------------------------------------------
# Final Success Message
# --------------------------------------------------

print(
    "SUCCESS: All available values in both "
    "Qty Change columns have a negative (-) sign prefix."
)

# --------------------------------------------------
# Delete CSV after verification
# --------------------------------------------------

assert os.path.exists(daily_stock_file), (
    f"CSV file does not exist: {daily_stock_file}"
)

os.remove(daily_stock_file)

assert not os.path.exists(daily_stock_file), (
    f"CSV file was not deleted: {daily_stock_file}"
)

print("Deleted file:", daily_stock_file)','2026-08-12 11:37:25','2026-08-12 11:37:25','API_USER','API_USER','PENDING',51,1),
