# Convert MM/DD/YYYY -> MM-DD-YYYY
current_date = datetime.strptime(
    app_date,
    "%m/%d/%Y"
).strftime("%m-%d-%Y")

expected_filename = (
    f"thirdPartyPipeInventoryReport-As-Of-{current_date}.xls"
)

# --------------------------------------------------
# Verify Dynamic Filename
# --------------------------------------------------

assert filename == expected_filename, (
    f"Expected filename: {expected_filename}, "
    f"but downloaded: {filename}"
)

print("Verified filename:", filename)

