# --------------------------------------------------

os.remove(file_path)

assert not os.path.exists(file_path), (
    f"XLS file was not deleted: {file_path}"
)

print("Deleted XLS file:", file_path)

print(
    "SUCCESS: Third Party Pipe Inventory Report "
    "was downloaded successfully."
