# HELPER - CAPTURE STANDARD INPUT FIELD
# ============================================================

def capture_input_field(
    locator,
    field_name,
    locator_description,
    timeout=10000
):

    print(
        f"\\nLocating {field_name}..."
    )

    expect(
        locator
    ).to_be_visible(
        timeout=timeout
    )

    print(
        f"{field_name} input is visible."
    )

    try:

        value = locator.input_value(
            timeout=timeout
        )

    except Exception as e:

        raise AssertionError(
            f"\\nUnable to capture {field_name} "
            "from Edit Order.\\n\\n"
            f"Locator: {locator_description}\\n\\n"
            f"Error: {e}"
        )

    value = clean_ui_value(
        value
    )

    assert value, (

        f"\\n{field_name} value is empty "
        "in Edit Order UI.\\n\\n"

        f"Locator:\\n"
        f"{locator_description}"
    )

    print(
        f"{field_name} from Edit Order:",
        value
    )

    return value


