(19707,371,'custom','Read and capture the Transit ID near the Intransit Details header','Transit ID','import re
from playwright.sync_api import expect
loc = page.get_by_role("heading", name=re.compile(r"Intransit Details", re.I))
expect(loc).to_be_visible(timeout=15_000)
text = loc.inner_text().strip()
m = re.search(r"\\(#(\\d+)\\)", text)
if not m:
    raise AssertionError(f"Could not parse intransit id from: {text!r}")
intransit_id = m.group(1)
set_var("intransit_id", intransit_id)

print(f\'set_var("intransit_id", {intransit_id})\')
','2026-08-13 15:15:06','2026-09-09 13:25:25','user','User','PENDING',28,1),
