(19783,373,'custom','Verify system should generate the xls file and verify content as per filter result','Assertion','import os
import csv
import re

# ============================================================
# PURCHASE ORDER CSV EXPORT VALIDATION
# ============================================================

# ------------------------------------------------------------
# Export as CSV
# ------------------------------------------------------------

export_button = page.locator(
    "xpath=//span[normalize-space()=\'Export as CSV\']"
)

expect(export_button).to_be_visible(timeout=10000)

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# ------------------------------------------------------------
# Download Information
# ------------------------------------------------------------

filename = download.suggested_filename

print("Downloaded filename:", filename)

# ------------------------------------------------------------
# Verify CSV File
# ------------------------------------------------------------

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded file is: {filename}"
)

# ------------------------------------------------------------
# Download Location
# ------------------------------------------------------------

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print("Saved CSV file:", file_path)

# ------------------------------------------------------------
# Verify File Exists
# ------------------------------------------------------------

assert os.path.exists(file_path), (
    f"Downloaded CSV file was not saved: {file_path}"
)

assert os.path.getsize(file_path) > 0, (
    f"Downloaded CSV file is empty: {file_path}"
)

print("SUCCESS: Purchase Order CSV downloaded successfully.")


# ============================================================
# GET UI PAGINATION TOTAL ROW COUNT
# Example: 1–46 of 46
# ============================================================

pagination = page.locator(
    ".MuiTablePagination-displayedRows"
)

expect(pagination).to_be_visible(timeout=10000)

pagination_text = pagination.inner_text().strip()

print("UI Pagination:", pagination_text)

# ------------------------------------------------------------
# Extract Total Rows
# ------------------------------------------------------------

pagination_match = re.search(
    r"\\d+\\s*[–-]\\s*\\d+\\s+of\\s+(\\d+)",
    pagination_text
)

assert pagination_match is not None, (
    f"Unable to extract total row count from UI pagination: "
    f"{pagination_text}"
)

ui_total_rows = int(
    pagination_match.group(1)
)

print(
    "Total Purchase Orders displayed in UI:",
    ui_total_rows
)


# ============================================================
# READ PURCHASE ORDER CSV
# ============================================================

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)
    rows = list(reader)

assert len(rows) > 0, (
    "Purchase Order CSV does not contain any data."
)

print(
    "Total CSV rows including report information:",
    len(rows)
)


# ============================================================
# FIND PURCHASE ORDER HEADER ROW
# ============================================================

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip().strip(\'="\')
        for column in row
    ]

    if (
        "PO #" in cleaned_row
        and "Supplier Name" in cleaned_row
        and "Project Name" in cleaned_row
        and "Destination Location" in cleaned_row
        and "Sales Order" in cleaned_row
        and "Status" in cleaned_row
        and "Order Date" in cleaned_row
        and "Last Modified Date" in cleaned_row
    ):
        header_row_index = index
        break


assert header_row_index is not None, (
    "Purchase Order CSV header row was not found."
)

headers = [
    column.strip().strip(\'="\')
    for column in rows[header_row_index]
]

print(
    "Purchase Order CSV header found at row:",
    header_row_index + 1
)

print(
    "CSV Headers:",
    headers
)


# ============================================================
# GET CSV DATA ROWS
# ============================================================

data_rows = rows[
    header_row_index + 1:
]

# Remove completely blank rows
data_rows = [
    row
    for row in data_rows
    if any(
        cell.strip()
        for cell in row
    )
]

csv_total_rows = len(data_rows)

print(
    "Total Purchase Order data rows in CSV:",
    csv_total_rows
)


# ============================================================
# VERIFY UI ROW COUNT == CSV ROW COUNT
# ============================================================

assert csv_total_rows == ui_total_rows, (
    f"UI and CSV row counts do not match. "
    f"UI rows: {ui_total_rows}, "
    f"CSV rows: {csv_total_rows}"
)

print(
    f"SUCCESS: UI pagination total rows ({ui_total_rows}) "
    f"match CSV data rows ({csv_total_rows})."
)


# ============================================================
# VERIFY EXPECTED PURCHASE ORDER COLUMNS
# ============================================================

expected_columns = [
    "PO #",
    "Supplier Name",
    "Project Name",
    "Destination Location",
    "Sales Order",
    "Status",
    "Order Date",
    "Last Modified Date"
]

for column in expected_columns:

    assert column in headers, (
        f"Expected Purchase Order column "
        f"\'{column}\' was not found in CSV."
    )

print(
    "SUCCESS: All expected Purchase Order columns "
    "are present in the CSV."
)


# ============================================================
# VERIFY COLUMN COUNT
# ============================================================

assert len(headers) == len(expected_columns), (
    f"Unexpected number of CSV columns. "
    f"Expected: {len(expected_columns)}, "
    f"Actual: {len(headers)}"
)

print(
    f"SUCCESS: CSV contains exactly "
    f"{len(expected_columns)} expected columns."
)


# ============================================================
# FINAL VERIFICATION
# ============================================================

print(
    "SUCCESS: Purchase Order CSV export validation completed."
)

print(
    f"UI Purchase Orders : {ui_total_rows}"
)

print(
    f"CSV Purchase Orders: {csv_total_rows}"
)


# ============================================================
# DELETE CSV AFTER VERIFICATION
# ============================================================

assert os.path.exists(file_path), (
    f"CSV file does not exist before deletion: {file_path}"
)

os.remove(file_path)

assert not os.path.exists(file_path), (
    f"CSV file was not deleted: {file_path}"
)

print(
    "SUCCESS: Purchase Order CSV was deleted after verification."
