(19974,375,'custom','Click on Shop Order Report and Verify PDF is printing on click','Shop Order Report','import os
from playwright.sync_api import expect


# ============================================================
# SHOP ORDER REPORT - OPEN PDF, DOWNLOAD AND DELETE
# ============================================================

downloaded_pdf_path = "/tmp/downloads/Shop_Order_Report.pdf"

os.makedirs("/tmp/downloads", exist_ok=True)


# ------------------------------------------------------------
# 1. LOCATE SHOP ORDER REPORT BUTTON
# ------------------------------------------------------------

shop_order_report_button = page.locator(
    "//button[text()=\'Shop Order Report\']"
).first

expect(shop_order_report_button).to_be_visible(timeout=10000)
expect(shop_order_report_button).to_be_enabled(timeout=10000)


# ------------------------------------------------------------
# 2. COUNT TABS BEFORE CLICK
# ------------------------------------------------------------

tabs_before = len(context.pages)

print("Tabs before clicking Shop Order Report:", tabs_before)


# ------------------------------------------------------------
# 3. PDF RESPONSE PREDICATE
# ------------------------------------------------------------

def is_pdf_response(response):
    try:
        content_type = response.headers.get(
            "content-type",
            ""
        ).lower()

        return "application/pdf" in content_type

    except Exception:
        return False


# ------------------------------------------------------------
# 4. CLICK SHOP ORDER REPORT
#    Capture BOTH:
#      - new tab
#      - PDF response
# ------------------------------------------------------------

try:

    with context.expect_page(timeout=30000) as new_page_info:

        with page.expect_response(
            is_pdf_response,
            timeout=30000
        ) as pdf_response_info:

            shop_order_report_button.click()

    # Get new PDF tab
    pdf_page = new_page_info.value

    # Get actual PDF browser response
    pdf_response = pdf_response_info.value

except Exception as e:

    raise AssertionError(
        "\\nShop Order Report was clicked, but "
        "PDF/new tab was not detected.\\n\\n"
        f"Error: {e}"
    )


# ------------------------------------------------------------
# 5. VERIFY NEW TAB
# ------------------------------------------------------------

tabs_after = len(context.pages)

print("Tabs after clicking Shop Order Report:", tabs_after)

assert tabs_after > tabs_before, (
    "\\nShop Order Report did not open in a new tab.\\n"
    f"Tabs before: {tabs_before}\\n"
    f"Tabs after: {tabs_after}"
)

print("Shop Order Report opened in new tab successfully.")


# ------------------------------------------------------------
# 6. GET PDF RESPONSE DETAILS
# ------------------------------------------------------------

pdf_url = pdf_response.url
pdf_status = pdf_response.status

pdf_content_type = pdf_response.headers.get(
    "content-type",
    ""
).lower()


print("\\n================ PDF RESPONSE ================")
print("PDF URL:", pdf_url)
print("HTTP Status:", pdf_status)
print("Content-Type:", pdf_content_type)
print("==============================================")


# ------------------------------------------------------------
# 7. VERIFY PDF RESPONSE
# ------------------------------------------------------------

assert pdf_status == 200, (
    "\\nPDF request failed.\\n"
    f"Expected status: 200\\n"
    f"Actual status: {pdf_status}\\n"
    f"URL: {pdf_url}"
)

assert "application/pdf" in pdf_content_type, (
    "\\nExpected PDF response.\\n"
    f"Content-Type: {pdf_content_type}\\n"
    f"URL: {pdf_url}"
)

print("PDF response verification PASSED.")


# ------------------------------------------------------------
# 8. WAIT FOR PDF TAB
# ------------------------------------------------------------

try:
    pdf_page.wait_for_load_state(
        "domcontentloaded",
        timeout=30000
    )
except Exception:
    # Chrome PDF viewer may not expose normal DOM state
    pass


print("PDF tab URL:", pdf_page.url)


# ------------------------------------------------------------
# 9. GET PDF BYTES DIRECTLY FROM BROWSER RESPONSE
# ------------------------------------------------------------

print("Downloading Shop Order Report PDF...")

pdf_bytes = pdf_response.body()

assert pdf_bytes, (
    "Shop Order Report PDF response body is empty."
)


# ------------------------------------------------------------
# 10. VERIFY PDF FILE SIGNATURE
# ------------------------------------------------------------

assert pdf_bytes.startswith(b"%PDF"), (
    "\\nDownloaded response is not a valid PDF.\\n"
    f"URL: {pdf_url}\\n"
    f"Content-Type: {pdf_content_type}\\n"
    f"Size: {len(pdf_bytes)} bytes"
)

print("PDF download verification PASSED.")


# ------------------------------------------------------------
# 11. SAVE PDF
# ------------------------------------------------------------

if os.path.exists(downloaded_pdf_path):
    os.remove(downloaded_pdf_path)


with open(downloaded_pdf_path, "wb") as pdf_file:
    pdf_file.write(pdf_bytes)


assert os.path.exists(downloaded_pdf_path), (
    "Shop Order Report PDF was not saved."
)

assert os.path.getsize(downloaded_pdf_path) > 0, (
    "Shop Order Report PDF is empty."
)

print(
    "Shop Order Report PDF downloaded successfully:",
    downloaded_pdf_path
)


# ------------------------------------------------------------
# 12. DELETE PDF
# ------------------------------------------------------------

os.remove(downloaded_pdf_path)

assert not os.path.exists(downloaded_pdf_path), (
    "Shop Order Report PDF was not deleted."
)

print(
    "Shop Order Report PDF deleted successfully."
)


# ------------------------------------------------------------
# FINAL
# ------------------------------------------------------------

print("\\n============================================================")
print("SHOP ORDER REPORT PDF TEST PASSED")
print("============================================================")
print("Shop Order Report button       : PASS")
print("New PDF tab opened             : PASS")
print("PDF response                   : PASS")
print("PDF downloaded                 : PASS")
print("PDF deleted                    : PASS")
print("PDF content validation         : NOT PERFORMED")
print("============================================================")','2026-08-14 15:04:19','2026-09-09 07:35:14','API_USER','User','PENDING',120,1),
