(19976,375,'custom',' Validate coil items and attachment details are being displayed as enter before creation','coil items and attachment details','Based on the DOM, the **Coil Items** row contains `2, 34.4, 48, 0.375, Y`, and the **Attachment Items** row contains `1, 2, 2, 1, 1, Bevel, Y, Y, N, Bevel, Bevel, Bevel`.  


from playwright.sync_api import expect

# =========================
# Validate Coil Items
# =========================

coil_grid = page.locator(
    "//p[normalize-space()=\'Coil Items\']/following::div[@role=\'grid\'][1]"
)

expect(coil_grid).to_be_visible()

coil_row = coil_grid.locator("//div[@role=\'row\' and @data-rowindex=\'0\']")

# No. of Coils
expect(
    coil_row.locator(".//div[@data-field=\'numberOfCoils\']")
).to_have_text("2")

# Total Weight (Tons)
expect(
    coil_row.locator(".//div[@data-field=\'totalWeight\']")
).to_have_text("34.4")

# Width
expect(
    coil_row.locator(".//div[@data-field=\'width\']")
).to_have_text("48")

# Thickness
expect(
    coil_row.locator(".//div[@data-field=\'thickness\']")
).to_have_text("0.375")

# Production Test
expect(
    coil_row.locator(".//div[@data-field=\'productionTest\']")
).to_have_text("Y")


# =========================
# Validate Attachment Items
# =========================

attachment_grid = page.locator(
    "//p[normalize-space()=\'Attachment Items\']/following::div[@role=\'grid\'][1]"
)

expect(attachment_grid).to_be_visible()

attachment_row = attachment_grid.locator(
    "//div[@role=\'row\' and @data-rowindex=\'0\']"
)

# QTY
expect(
    attachment_row.locator(".//div[@data-field=\'quantity\']")
).to_have_text("1")

# Plates
expect(
    attachment_row.locator(".//div[@data-field=\'plates\']")
).to_have_text("2")

# Connectors
expect(
    attachment_row.locator(".//div[@data-field=\'connectors\']")
).to_have_text("2")

# Cones
expect(
    attachment_row.locator(".//div[@data-field=\'cones\']")
).to_have_text("1")

# Shoes
expect(
    attachment_row.locator(".//div[@data-field=\'shoes\']")
).to_have_text("1")

# Groove Type
expect(
    attachment_row.locator(".//div[@data-field=\'grooveType\']")
).to_have_text("Bevel")

# RT
expect(
    attachment_row.locator(".//div[@data-field=\'rt\']")
).to_have_text("Y")

# UT
expect(
    attachment_row.locator(".//div[@data-field=\'ut\']")
).to_have_text("Y")

# MPI
expect(
    attachment_row.locator(".//div[@data-field=\'mpi\']")
).to_have_text("N")

# Pipe End 1 - Inside
expect(
    attachment_row.locator(".//div[@data-field=\'pipeEnd1Inside\']")
).to_have_text("Bevel")

# Pipe End 1 - Outside
expect(
    attachment_row.locator(".//div[@data-field=\'pipeEnd1Outside\']")
).to_have_text("Bevel")

# Pipe End 2 - Inside
expect(
    attachment_row.locator(".//div[@data-field=\'pipeEnd2Inside\']")
).to_have_text("Bevel")

# Pipe End 2 - Outside
expect(
    attachment_row.locator(".//div[@data-field=\'pipeEnd2Outside\']")
).to_have_text("Bevel")

