(20013,374,'custom','Upload CSV File','Upload CSV FIle','import os
print(os.getcwd())
print("##" * 10)

from datetime import datetime
from pathlib import Path
import xlwt

xls_path = Path.cwd() / "ChemicalComposition.xls"

# S + YYMMDDHHmmss + 2-digit sequence
base = "S" + datetime.now().strftime("%y%m%d%H%M%S")
heat_numbers = [f"{base}01", f"{base}02"]

for hn in heat_numbers:
    print("Heat#:", hn)

rows = [
    {"Heat#": heat_numbers[0], "C": 0.12, "Mn": 1.35, "Si": 0.25, "P": 0.018, "S": 0.008},
    {"Heat#": heat_numbers[1], "C": 0.15, "Mn": 1.40, "Si": 0.22, "P": 0.020, "S": 0.010},
]

wb = xlwt.Workbook()
ws = wb.add_sheet("Chemical Composition")

headers = list(rows[0].keys())
for col, h in enumerate(headers):
    ws.write(0, col, h)
for r, row in enumerate(rows, start=1):
    for c, h in enumerate(headers):
        ws.write(r, c, row[h])

wb.save(str(xls_path))
print("Created:", xls_path)

fileupload = page.locator("input[type=\'file\']")
fileupload.set_input_files(str(xls_path))

page.locator(".base-state>div>div:last-child button").click(timeout=10000,force=True)
page.wait_for_timeout(10000)
set_var("Heat_one",heat_numbers[0])
set_var("Heat_two",heat_numbers[1])','2026-08-14 16:20:59','2026-08-17 10:31:56','user','User','PENDING',11,1),
(20014,130,'custom','Click the Print button and then Click Print BOL button after that Verify Bol should generate and same details and quantity should show in BOL pdf with updated yard.','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# 1. Helper Functions
# ============================================================

def normalize_text(value):

    if value is None:
        return ""

    return re.sub(
        r"\\s+",
        " ",
        str(value)
    ).strip().lower()


def normalize_number(value):

    value = str(value).strip()

    value = re.sub(
        r"\\s*(ft|lbs|pcs)\\s*$",
        "",
        value,
        flags=re.IGNORECASE
    )

    try:

        number = float(value)

        if number.is_integer():
            return str(int(number))

        return str(number)

    except Exception:

        return normalize_text(value)


def verify_equal(
    ui_value,
    pdf_value,
    field_name
):

    ui_normalized = normalize_text(
        ui_value
    )

    pdf_normalized = normalize_text(
        pdf_value
    )

    assert ui_normalized == pdf_normalized, (

        f"\\n\\nVALIDATION FAILED: {field_name}\\n"
        f"UI Value  : \'{ui_value}\'\\n"
        f"PDF Value : \'{pdf_value}\'\\n"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"UI=\'{ui_value}\' | "
        f"PDF=\'{pdf_value}\'"
    )


def verify_number_equal(
    ui_value,
    pdf_value,
    field_name
):

    ui_normalized = normalize_number(
        ui_value
    )

    pdf_normalized = normalize_number(
        pdf_value
    )

    assert ui_normalized == pdf_normalized, (

        f"\\n\\nNUMERIC VALIDATION FAILED: {field_name}\\n"
        f"UI Value  : \'{ui_value}\'\\n"
        f"PDF Value : \'{pdf_value}\'\\n"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"UI=\'{ui_value}\' | "
        f"PDF=\'{pdf_value}\'"
    )


def extract_pdf_section(
    text,
    start_text,
    end_text
):

    pattern = (
        re.escape(start_text)
        + r"(.*?)"
        + re.escape(end_text)
    )

    match = re.search(
        pattern,
        text,
        flags=re.IGNORECASE | re.DOTALL
    )

    assert match is not None, (
        f"PDF section not found: {start_text}"
    )

    return match.group(1).strip()


# ============================================================
# 2. PDF Response Storage
# ============================================================

pdf_data = {
    "bytes": None,
    "url": None,
    "content_type": None
}


# ============================================================
# 3. Click Print
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(
    timeout=10000
)

print_button.click(
    force=True
)

print(
    "Print button clicked."
)


# ============================================================
# 4. Verify Print BOL
# ============================================================

print_bol = page.locator(
    "//li[@role=\'menuitem\' and "
    "contains(normalize-space(.),\'Print BOL\')]"
)

expect(
    print_bol
).to_be_visible(
    timeout=10000
)

print(
    "Print BOL option found."
)


# ============================================================
# 5. Count Tabs Before Print BOL
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before Print BOL:",
    tabs_before
)


# ============================================================
# 6. Click Print BOL and Capture PDF
# ============================================================

with context.expect_page(
    timeout=15000
) as new_page_info:

    with context.expect_event(
        "response",
        predicate=lambda response: (
            "application/pdf"
            in response.headers.get(
                "content-type",
                ""
            ).lower()
        ),
        timeout=15000
    ) as pdf_response_info:

        print_bol.click(
            force=True
        )


# ============================================================
# 7. Get New PDF Tab
# ============================================================

pdf_page = (
    new_page_info.value
)

print(
    "Print BOL clicked."
)

print(
    "New PDF tab opened successfully."
)


# ============================================================
# 8. Get PDF Response
# ============================================================

pdf_response = (
    pdf_response_info.value
)

print(
    "\\n================ PDF RESPONSE ================\\n"
)

print(
    "PDF URL:",
    pdf_response.url
)

print(
    "PDF Content-Type:",
    pdf_response.headers.get(
        "content-type",
        ""
    )
)

print(
    "\\n===============================================\\n"
)


# ============================================================
# 9. Capture PDF Body
# ============================================================

pdf_bytes = (
    pdf_response.body()
)

assert pdf_bytes is not None, (
    "PDF response body is None."
)

assert len(pdf_bytes) > 0, (
    "PDF response body is empty."
)


pdf_data["bytes"] = (
    pdf_bytes
)

pdf_data["url"] = (
    pdf_response.url
)

pdf_data["content_type"] = (
    pdf_response.headers.get(
        "content-type",
        ""
    ).lower()
)


print(
    "PDF response body captured successfully."
)

print(
    "Captured PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 10. Verify New Tab
# ============================================================

tabs_after = len(
    context.pages
)

print(
    "Tabs after Print BOL:",
    tabs_after
)

assert tabs_after > tabs_before, (
    f"\\nExpected new PDF tab.\\n"
    f"Before={tabs_before}\\n"
    f"After={tabs_after}"
)


# ============================================================
# 11. PDF Tab URL
# ============================================================

pdf_page.wait_for_timeout(
    2000
)

print(
    "PDF tab URL:",
    repr(pdf_page.url)
)


# ============================================================
# 12. Verify Content-Type
# ============================================================

assert (
    "application/pdf"
    in pdf_data["content_type"]
), (
    "Response is not a PDF.\\n"
    f"Content-Type: "
    f"{pdf_data[\'content_type\']}"
)


# ============================================================
# 13. Verify PDF Header
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Captured response is not a valid PDF."
)

print(
    "Valid PDF detected."
)


# ============================================================
# 14. Save PDF Temporarily
# ============================================================

pdf_path = (
    "/tmp/print_bol.pdf"
)

with open(
    pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )

print(
    "PDF saved at:",
    pdf_path
)


# ============================================================
# 15. Verify PDF File
# ============================================================

assert os.path.exists(
    pdf_path
), (
    f"PDF file was not saved: {pdf_path}"
)

assert os.path.getsize(
    pdf_path
) > 0, (
    "PDF file is empty."
)


# ============================================================
# 16. Read PDF
# ============================================================

reader = PdfReader(
    BytesIO(pdf_bytes)
)

print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 17. Extract PDF Text
# ============================================================

pdf_text = ""


for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    try:

        page_text = (
            pdf_document_page
            .extract_text()
            or ""
        )

        pdf_text += (
            f"\\n--- PDF Page "
            f"{page_number} ---\\n"
            + page_text
        )

    except Exception as e:

        print(
            f"Unable to extract text "
            f"from PDF page "
            f"{page_number}: {e}"
        )


# ============================================================
# 18. Verify PDF Text
# ============================================================

assert pdf_text.strip(), (
    "PDF text extraction returned empty text."
)


print(
    "\\n================ PDF TEXT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n===========================================\\n"
)

print(
    "PDF text extracted successfully."
)


# ============================================================
# 19. Get UI Body Text
# ============================================================

body_text = (
    page.locator(
        "body"
    ).inner_text()
)


# ============================================================
# 20. BILLING DETAILS vs CONSIGNEE
# ============================================================

billing_header = page.get_by_text(
    "Billing Details",
    exact=True
)

expect(
    billing_header
).to_be_visible(
    timeout=10000
)


billing_section = (
    billing_header
    .locator(
        "xpath=following-sibling::*[1]"
    )
)


if billing_section.count() == 0:

    billing_section = (
        billing_header
        .locator(
            "xpath=.."
        )
        .locator(
            "xpath=following-sibling::*[1]"
        )
    )


billing_ui_text = (
    billing_section
    .inner_text()
)


consignee_pdf = extract_pdf_section(
    pdf_text,
    "CONSIGNEE:",
    "FROM:"
)


print(
    "\\n================ BILLING UI ================\\n"
)

print(
    billing_ui_text
)

print(
    "\\n================ PDF CONSIGNEE ================\\n"
)

print(
    consignee_pdf
)


billing_values = [

    "Algoma Steel Inc",

    "Mr. Norman Honsaczek",

    "105 West Street",

    "Sault Ste-Marie"

]


billing_ui_normalized = normalize_text(
    billing_ui_text
)

consignee_pdf_normalized = normalize_text(
    consignee_pdf
)


for value in billing_values:

    normalized_value = normalize_text(
        value
    )

    assert normalized_value in (
        billing_ui_normalized
    ), (
        f"\\nBilling UI value not found:\\n"
        f"{value}"
    )

    assert normalized_value in (
        consignee_pdf_normalized
    ), (
        f"\\nCONSIGNEE PDF value not found:\\n"
        f"{value}"
    )

    print(
        "Billing / CONSIGNEE verified:",
        value
    )


print(
    "Billing Details vs CONSIGNEE validation passed."
)


# ============================================================
# 21. Planned In Shipment vs SHIPPER S NO.
# ============================================================

planned_match = re.search(
    r"Planned\\s+In\\s+Shipment\\s+"
    r"(\\d+)",
    body_text,
    flags=re.IGNORECASE
)


assert planned_match is not None, (
    "Planned In Shipment value "
    "not found in UI."
)


planned_ui = (
    planned_match.group(1)
)


print(
    "UI Planned In Shipment:",
    planned_ui
)


shipper_section_match = re.search(
    r"SHIPPER\\s*\'?S\\s+NO\\."
    r"(.*?)"
    r"CONSIGNEE:",
    pdf_text,
    flags=re.IGNORECASE | re.DOTALL
)


assert shipper_section_match is not None, (
    "SHIPPER S NO. section not found in PDF."
)


shipper_section = (
    shipper_section_match
    .group(1)
    .strip()
)


print(
    "\\nPDF SHIPPER S NO. SECTION:"
)

print(
    shipper_section
)


shipper_numbers = re.findall(
    r"\\b\\d+\\b",
    shipper_section
)


assert shipper_numbers, (
    "No numeric value found in "
    "SHIPPER S NO. section."
)


shipper_pdf = (
    shipper_numbers[-1]
)


print(
    "PDF SHIPPER S NO.:",
    shipper_pdf
)


verify_equal(
    planned_ui,
    shipper_pdf,
    "Planned In Shipment vs SHIPPER S NO."
)


# ============================================================
# 22. Order # vs P&P ORDER #
# ============================================================

order_input = page.locator(
    "input[name=\'orderNumber\']"
)


if order_input.count() > 0:

    order_ui = (
        order_input
        .first
        .input_value()
        .strip()
    )

else:

    order_match_ui = re.search(
        r"Order\\s*#:\\s*"
        r"([A-Za-z0-9_-]+)",
        body_text,
        flags=re.IGNORECASE
    )

    assert order_match_ui is not None, (
        "Order # value not found in UI."
    )

    order_ui = (
        order_match_ui.group(1)
    )


assert order_ui, (
    "Order # value is empty."
)


print(
    "UI Order #:",
    order_ui
)


order_pdf_match = re.search(
    r"P&P\\s+ORDER\\s*#\\s*"
    r"([A-Za-z0-9_-]+)",
    pdf_text,
    flags=re.IGNORECASE
)


assert order_pdf_match is not None, (
    "P&P ORDER # not found in PDF."
)


order_pdf = (
    order_pdf_match.group(1)
)


print(
    "PDF P&P ORDER #:",
    order_pdf
)


verify_equal(
    order_ui,
    order_pdf,
    "Order # vs P&P ORDER #"
)


# ============================================================
# 23. PO # vs CUSTOMER PO #
# ============================================================

# IMPORTANT:
# There are two input[name=\'poNumber\'] elements.
#
# The second element is the actual PO # field.
#
# DOM:
# (//input[@name=\'poNumber\'])[2]
#
# Example value:
# Test123
# ============================================================

po_input = page.locator(
    "(//input[@name=\'poNumber\'])[2]"
)

expect(
    po_input
).to_be_visible(
    timeout=10000
)

po_ui = (
    po_input
    .input_value()
    .strip()
)

assert po_ui, (
    "PO # value is empty in UI."
)

print(
    "UI PO #:",
    po_ui
)


# ============================================================
# PDF CUSTOMER PO #
# ============================================================

customer_po_match = re.search(
    r"CUSTOMER\\s+PO\\s*#\\s*"
    r"([^\\n]+)",
    pdf_text,
