(20158,121,'custom','Click the Print button and Verify The credit note should open in the pdf format in a new browser window','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os


# Print button
print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(print_button).to_be_visible(timeout=10000)

print("Print button found.")


# PDF response capture
pdf_data = {
    "bytes": None,
    "url": None
}


def handle_response(response):

    try:

        content_type = response.headers.get(
            "content-type",
            ""
        ).lower()

        if "application/pdf" in content_type:

            body = response.body()

            if body.startswith(b"%PDF"):

                pdf_data["bytes"] = body
                pdf_data["url"] = response.url

                print(
                    "PDF response captured:",
                    response.url
                )

    except Exception:
        pass


# Register listener
context.on(
    "response",
    handle_response
)


# Click Print
print_button.click()

print("Print button clicked.")


# Wait for response
page.wait_for_timeout(5000)


# Verify PDF captured
assert pdf_data["bytes"] is not None, (
    "PDF response was not captured."
)


# Read PDF directly from memory
reader = PdfReader(
    BytesIO(pdf_data["bytes"])
)


# Extract text
pdf_text = ""

for pdf_page in reader.pages:

    pdf_text += (
        pdf_page.extract_text()
        or ""
    )


# Verify content
assert pdf_text.strip(), (
    "PDF content is empty."
)


# Display PDF CONTENT ONLY
print(pdf_text)


# Temporary PDF save
pdf_path = "/tmp/print_pdf.pdf"

with open(
    pdf_path,
    "wb"
) as file:

    file.write(
        pdf_data["bytes"]
    )


# Delete temporary PDF
if os.path.exists(pdf_path):

    os.remove(pdf_path)


assert not os.path.exists(pdf_path), (
    "Temporary PDF was not deleted."
)','2026-08-15 11:09:00','2026-08-15 11:56:22','user','User','PENDING',10,1),
