(20190,377,'custom','Select the checkbox for the product where Actual Yard Stock is greater than 0 and Stock on Sales Order is equal to 0','Click checkbox in first row where Actual Yard Stock > 0 and Stock on S/O = 0','import re
from playwright.sync_api import expect

# Set to False to select products WITHOUT the stock condition
# (StockOnSoPCS == 0 and actualYardStockPCS > 1)
APPLY_STOCK_FILTER = False

# Scope inside dialog
dialog = page.locator("div[role=\'dialog\']")

# Wait for grid initial load
dialog.locator("div[role=\'row\'][data-id]").first.wait_for()

# -------------------------------------------------------------------
# STEP 1: Read total row count from pagination
# Example text: "1-780 of 780"
# -------------------------------------------------------------------

pagination_text = dialog.locator(
    "p.MuiTablePagination-displayedRows"
).inner_text().strip()

print("Pagination Text:", pagination_text)

match = re.search(r"of\\s+(\\d+)", pagination_text)

if not match:
    raise Exception("Unable to determine total row count")

total_rows = int(match.group(1))

print("Total Rows:", total_rows)

# -------------------------------------------------------------------
# STEP 2: Iterate rows, select TWO products such that:
#   Condition 1 (both rows): StockOnSoPCS == 0 and actualYardStockPCS > 1
#   Condition 2: length of product 2 != length of product 1
#     (length = number between "Pipe -" and "Ft" in description)
# -------------------------------------------------------------------

selected = []   # each entry: (data_id, row_index, length, description)

for row_index in range(total_rows):

    print(f"\\nProcessing Row Index: {row_index}")

    # Row locator using logical index
    row_locator = dialog.locator(
        f"div[role=\'row\'][data-rowindex=\'{row_index}\']"
    )

    # ----------------------------------------------------------------
    # If row not present in DOM -> scroll grid
    # ----------------------------------------------------------------

    retry = 0

    while row_locator.count() == 0 and retry < 10:

        print(f"Row {row_index} not in DOM. Scrolling...")

        visible_rows = dialog.locator("div[role=\'row\'][data-id]")

        last_visible = visible_rows.last

        last_visible.scroll_into_view_if_needed()

        page.wait_for_timeout(300)

        retry += 1

    if row_locator.count() == 0:
        print(f"Row {row_index} could not be loaded")
        continue

    row = row_locator.first

    row.scroll_into_view_if_needed()

    # ----------------------------------------------------------------
    # Read values safely
    # ----------------------------------------------------------------

    try:
        stock_on_so = row.locator(
            "[data-field=\'StockOnSoPCS\']"
        ).inner_text().strip()

        actual_yard = row.locator(
            "[data-field=\'actualYardStockPCS\']"
        ).inner_text().strip()

        # title attribute holds the full description text
        description = row.locator(
            "[data-field=\'description\']"
        ).get_attribute("title")

        description = description.strip() if description else ""

        print("StockOnSoPCS:", stock_on_so)
        print("ActualYardStockPCS:", actual_yard)
        print("Description:", description)

        stock_on_so_val = float(stock_on_so)
        actual_yard_val = float(actual_yard)

    except Exception as e:
        print("Failed reading row:", e)
        continue

    # ----------------------------------------------------------------
    # CONDITION 1: stock filter (must pass for BOTH selections)
    # Skipped entirely when APPLY_STOCK_FILTER is False
    # ----------------------------------------------------------------

    if APPLY_STOCK_FILTER and not (stock_on_so_val == 0 and actual_yard_val > 1):
        continue

    # ----------------------------------------------------------------
    # Parse length from description ("... Pipe - 35.00 Ft - ...")
    # ----------------------------------------------------------------

    length_match = re.search(r"-\\s*([\\d.]+)\\s*Ft", description, re.IGNORECASE)

    if not length_match:
        print(f"Row {row_index}: could not parse length")
        continue

    length = float(length_match.group(1))

    # ----------------------------------------------------------------
    # CONDITION 2: second product length must differ from first
    # ----------------------------------------------------------------

    if len(selected) == 1 and abs(length - selected[0][2]) <= 0.001:
        print(f"Row {row_index} skipped: same length ({length}) as first product")
        continue

    # ----------------------------------------------------------------
    # Click checkbox and VERIFY this exact row got selected
    # ----------------------------------------------------------------

    product_no = len(selected) + 1
    print(f"Matching row for product {product_no} at index {row_index}, length {length}")

    data_id = row.get_attribute("data-id")

    checkbox_cell = row.locator("[data-field=\'__check__\']")
    checkbox_input = checkbox_cell.locator("input[type=\'checkbox\']")

    checkbox_cell.scroll_into_view_if_needed()
    page.wait_for_timeout(200)

    # Normal click (no force) - Playwright waits for the element to be
    # stable, so the click cannot land on a neighboring row
    checkbox_cell.locator("span.MuiCheckbox-root").click()
    page.wait_for_timeout(300)

    if not checkbox_input.is_checked():
        print("Click did not register, retrying on the input directly...")
        checkbox_input.check(force=True)
        page.wait_for_timeout(300)

    # Hard verification: THIS row must now be selected
    expect(checkbox_input).to_be_checked()
    expect(row).to_have_attribute("aria-selected", "true")

    print(f"Product {product_no} selected and verified (row {row_index}, data-id {data_id})")

    selected.append((data_id, row_index, length, description))

    if len(selected) == 2:
        break

# -------------------------------------------------------------------
# Final validation
# -------------------------------------------------------------------

if len(selected) < 2:
    raise Exception(
        f"Could not select two products with different lengths (found {len(selected)})"
    )

# -------------------------------------------------------------------
# FINAL VERIFICATION: re-check both rows are still selected and
# still meet the stock filter, and lengths differ
# -------------------------------------------------------------------

print("\\n--- FINAL VERIFICATION ---")

for data_id, row_index, length, description in selected:

    vrow = dialog.locator(f"div[role=\'row\'][data-id=\'{data_id}\']")

    if vrow.count() == 0:
        # Row scrolled out of DOM - selection persists by id in MUI grid
        print(f"Row data-id {data_id} virtualized out of DOM (selection kept by grid)")
        continue

    expect(vrow.first).to_have_attribute("aria-selected", "true")

    v_stock = vrow.first.locator("[data-field=\'StockOnSoPCS\']").inner_text().strip()
    v_yard = vrow.first.locator("[data-field=\'actualYardStockPCS\']").inner_text().strip()

    if APPLY_STOCK_FILTER and not (float(v_stock) == 0 and float(v_yard) > 1):
        raise Exception(
            f"Selected row {row_index} does NOT meet stock filter "
            f"(StockOnSoPCS={v_stock}, actualYardStockPCS={v_yard})"
        )

    print(f"Row {row_index} verified: selected, StockOnSoPCS={v_stock}, "
          f"actualYardStockPCS={v_yard}, length={length}")

if abs(selected[0][2] - selected[1][2]) <= 0.001:
    raise Exception("Both selected products have the SAME length - condition violated")

print("\\nSelected products:")
for data_id, row_index, length, description in selected:
    print(f"  Row {row_index} | Length {length} | {description}")
