(20381,376,'custom','Verify Qty Picked on Mill Order is same as Qty Ordered','Qty Picked and Qty Ordered','from playwright.sync_api import expect

# Get all available rows
rows = page.locator("//div[@role=\'row\' and @data-rowindex]")

row_count = rows.count()
assert row_count > 0, "No rows found in the grid"

# Validate Qty Ordered = Qty Picked for every row
for i in range(row_count):
    row = rows.nth(i)

    qty_ordered = row.locator(
        ".//div[@role=\'gridcell\' and @data-field=\'qtyOrderedInPO\']"
    )

    qty_picked = row.locator(
        ".//div[@role=\'gridcell\' and @data-field=\'poQtyIntransit\']"
    )

    expect(qty_ordered).to_be_visible()
    expect(qty_picked).to_be_visible()

    ordered_value = qty_ordered.inner_text().strip()
    picked_value = qty_picked.inner_text().strip()

    assert ordered_value == picked_value, (
        f"Row {i + 1}: Qty Ordered ({ordered_value}) "
        f"does not match Qty Picked ({picked_value})"
    )

print(f"Qty Ordered and Qty Picked match for all {row_count} available rows.")','2026-08-15 12:48:33','2026-09-09 07:43:20','user','system','PENDING',52,1),
(20385,113,'custom','Click the Print Invoice button and Verify the invoice pdf should open in a new tab and the user should be able to download pdf from there','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# 1. Locate Print Invoice Button
# ============================================================

print_invoice_button = page.locator(
    "//button[normalize-space()=\'Print Invoice\']"
)

expect(
    print_invoice_button
).to_be_visible(
    timeout=10000
)

print(
    "Print Invoice button found."
)


# ============================================================
# 2. PDF Request Storage
# ============================================================

pdf_request_data = {
    "request": None
}


# ============================================================
# 3. PDF Request Listener
# ============================================================

def capture_pdf_request(request):

    try:

        request_url = request.url

        if (
            "/scadmin/genPdfs/" in request_url
            and request_url.lower().endswith(".pdf")
        ):

            pdf_request_data["request"] = request

            print(
                "PDF request detected:",
                request_url
            )

    except Exception as e:

        print(
            "Unable to capture PDF request:",
            e
        )


# Register listener before clicking Print Invoice

context.on(
    "request",
    capture_pdf_request
)


# ============================================================
# 4. Count Tabs Before Print Invoice
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before Print Invoice:",
    tabs_before
)


# ============================================================
# 5. Click Print Invoice
# ============================================================

with context.expect_page(
    timeout=15000
) as new_page_info:

    print_invoice_button.click(
        force=True
    )


# ============================================================
# 6. Get PDF Page
# ============================================================

pdf_page = (
    new_page_info.value
)

print(
    "Print Invoice clicked."
)

print(
    "PDF opened in new tab."
)


# ============================================================
# 7. Wait for PDF Request
# ============================================================

pdf_page.wait_for_timeout(
    3000
)


# ============================================================
# 8. Verify PDF Request
# ============================================================

assert pdf_request_data["request"] is not None, (
    "PDF request was not captured."
)


# ============================================================
# 9. Get Actual PDF URL
# ============================================================

pdf_request = (
    pdf_request_data["request"]
)

pdf_url = (
    pdf_request.url
)


print(
    "\\n================ PDF REQUEST ================\\n"
)

print(
    "Actual PDF URL:",
    pdf_url
)

print(
    "Request Method:",
    pdf_request.method
)

print(
    "Resource Type:",
    pdf_request.resource_type
)

print(
    "\\n==============================================\\n"
)


# ============================================================
# 10. Verify PDF URL
# ============================================================

assert pdf_url, (
    "PDF URL was not captured."
)

assert (
    "/scadmin/genPdfs/" in pdf_url
), (
    f"Unexpected PDF URL: {pdf_url}"
)

assert (
    pdf_url.lower().endswith(".pdf")
), (
    f"Captured URL is not a PDF: {pdf_url}"
)


# ============================================================
# 11. Verify New PDF Tab
# ============================================================

tabs_after = len(
    context.pages
)

print(
    "Tabs after Print Invoice:",
    tabs_after
)

assert tabs_after > tabs_before, (
    f"\\nExpected new PDF tab.\\n"
    f"Before={tabs_before}\\n"
    f"After={tabs_after}"
)


# ============================================================
# 12. PDF Viewer
# ============================================================

pdf_page.wait_for_timeout(
    3000
)

print(
    "PDF tab URL:",
    repr(pdf_page.url)
)

# Chrome PDF Viewer may return an empty URL.
# Actual PDF URL is captured from the network request.


# ============================================================
# 13. Extract Expected Filename
# ============================================================

expected_filename = (
    pdf_url.rsplit(
        "/",
        1
    )[1]
)

print(
    "Expected PDF filename:",
    expected_filename
)


# ============================================================
# 14. Verify Filename Format
# ============================================================

assert re.match(
    r"^Document\\d+_\\d+\\.pdf$",
    expected_filename,
    flags=re.IGNORECASE
), (
    f"Unexpected PDF filename: "
    f"{expected_filename}"
)

print(
    "PDF filename format verified."
)


# ============================================================
# 15. Fetch PDF Using Actual PDF URL
# ============================================================

print(
    "Fetching PDF using captured PDF URL..."
)

pdf_response = (
    context.request.get(
        pdf_url,
        timeout=30000
