pdf_response_data = {
    "bytes": None,
    "url": None,
}


def capture_pdf_response(response):

    try:

        response_url = response.url
        response_url_lower = (
            response_url.lower()
        )

        content_type = (
            response.headers
            .get(
                "content-type",
                ""
            )
            .lower()
        )


        # --------------------------------------------------------
        # ONLY process the real imsOrder.pdf API.
        #
        # blob:https://... responses are ignored.
        # --------------------------------------------------------

        if "imsorder.pdf" not in (
            response_url_lower
        ):
            return


        if "application/pdf" not in (
            content_type
        ):
            return


        # --------------------------------------------------------
        # Only capture once.
        # --------------------------------------------------------

        if pdf_response_data[
            "bytes"
        ] is not None:

            return


        # --------------------------------------------------------
        # Read response immediately.
        #
        # Any protocol/navigation issue is silently ignored.
        # No warning is printed.
        # --------------------------------------------------------

        try:

            body = response.body()

        except Exception:

            return


        if not body:
            return


        if not body.startswith(
            b"%PDF"
        ):

            return


        # --------------------------------------------------------
        # Store PDF bytes.
        # --------------------------------------------------------

        pdf_response_data[
            "bytes"
        ] = body

        pdf_response_data[
            "url"
        ] = response_url


        print(
            "\\nPDF HTTP RESPONSE DETECTED"
        )

        print(
            f"PDF Response URL: "
            f"{response_url}"
        )

        print(
            f"PDF Content-Type: "
            f"{content_type}"
        )

        print(
            "PDF response body captured successfully."
        )


    except Exception:
        # Completely suppress listener errors.
        return


