(20490,380,'custom','Click the Order Pdf S/O button in the search result and Verify that the Order Status PDF opens successfully and contains the report date and time, order number, order date, Sold To and Ship To information, agent name, payment term, shipping term, carrier name, shipping instructions, item description, order quantity, shipped quantity, price, balance outstanding, order notes, subtotal, global discount, shipping/handling charges, GST, PST, deposit, and total amount.','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
from datetime import datetime
import os
import re


# ============================================================
# 1. Helper Functions
# ============================================================

def normalize_text(value):
    if value is None:
        return ""

    return re.sub(
        r"\\s+",
        " ",
        str(value)
    ).strip().lower()


def verify_contains(
    pdf_text,
    value,
    field_name
):
    normalized_pdf = normalize_text(pdf_text)
    normalized_value = normalize_text(value)

    assert normalized_value in normalized_pdf, (
        f"\\n\\nVALIDATION FAILED: {field_name}\\n"
        f"Expected Value : \'{value}\'\\n"
        f"PDF Value/Text : \'{pdf_text}\'"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"Value=\'{value}\'"
    )


def verify_equal(
    ui_value,
    pdf_value,
    field_name
):
    ui_normalized = normalize_text(ui_value)
    pdf_normalized = normalize_text(pdf_value)

    assert ui_normalized == pdf_normalized, (
        f"\\n\\nVALIDATION FAILED: {field_name}\\n"
        f"UI Value  : \'{ui_value}\'\\n"
        f"PDF Value : \'{pdf_value}\'"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"UI=\'{ui_value}\' | "
        f"PDF=\'{pdf_value}\'"
    )


# ============================================================
# 2. Locate Sales Order PDF Button
# ============================================================

