(20512,248,'custom','Click the Print button and Verify that the PDF opens in a new tab and that all the data is correctly populated in the PDF','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# 1. Get UI Pagination
# ============================================================

pagination_locator = page.locator(
    "//p[contains(@class,\'MuiTablePagination-displayedRows\')]"
)

