(20552,107,'custom','Click the Credit Receive pdf button and Verify checking the credit receive pdf, the amount under field should  be visible to the admin user','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# 1. Helper Function
# ============================================================

def normalize_text(value):

    if value is None:
        return ""

    return re.sub(
        r"\\s+",
        " ",
        str(value)
    ).strip().lower()


# ============================================================
# 2. Locate Credit Receive PDF Button
# ============================================================

print_pdf_button = page.locator(
    "//button[@permission=\'PRINT_CREDIT_NOTE\' "
    "and normalize-space()=\'Credit Receive Pdf\']"
)

expect(
    print_pdf_button
).to_be_visible(
    timeout=10000
)

print(
    "Credit Receive Pdf button found."
)


# ============================================================
# 3. Get Invoice # From UI
# ============================================================

invoice_input = page.get_by_role(
    "textbox",
    name="Invoice #"
)

expect(
    invoice_input
).to_be_visible(
    timeout=10000
)

ui_invoice_number = (
    invoice_input
    .input_value()
    .strip()
)

assert ui_invoice_number, (
    "Invoice # value is empty in UI."
)

print(
    "UI Invoice #:",
    ui_invoice_number
)


# ============================================================
# 4. Get Order # From UI
# ============================================================

order_input = page.locator(
    "(//input[@name=\'orderId\'])[2]"
)

expect(
    order_input
).to_be_visible(
    timeout=10000
)

ui_order_number = (
    order_input
    .input_value()
    .strip()
)

assert ui_order_number, (
    "Order # value is empty in UI."
)

print(
    "UI Order #:",
    ui_order_number
)


# ============================================================
# 5. Get Credit ID From UI
# ============================================================

credit_id_input = page.locator(
    "//input[@name=\'creditId\']"
)

expect(
    credit_id_input
).to_be_visible(
    timeout=10000
)

ui_credit_id = (
    credit_id_input
    .input_value()
    .strip()
)

assert ui_credit_id, (
    "Credit ID value is empty in UI."
)

print(
    "UI Credit ID:",
    ui_credit_id
)


# ============================================================
# 6. Count Tabs Before Click
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before Credit Receive Pdf:",
    tabs_before
)


# ============================================================
# 7. Capture PDF Request
# ============================================================

pdf_request_data = {
    "request": None
}


def handle_request(request):

    try:

        request_url = (
            request.url
            .lower()
        )

        if (
            ".pdf" in request_url
            or "/genpdfs/" in request_url
            or "receiptcredit.pdf" in request_url
        ):

            pdf_request_data["request"] = request

            print(
                "PDF request detected:",
                request.url
            )

            print(
                "PDF request method:",
                request.method
            )

    except Exception as e:

        print(
            "Unable to inspect request:",
            e
        )


context.on(
    "request",
    handle_request
)


# ============================================================
# 8. Click Credit Receive Pdf
# ============================================================

with context.expect_page(
    timeout=15000
) as new_page_info:

    print_pdf_button.click(
        force=True
    )


# ============================================================
# 9. Get PDF Page
# ============================================================

pdf_page = (
    new_page_info.value
)

print(
    "Credit Receive Pdf button clicked."
)

print(
    "PDF opened in new tab."
)


# ============================================================
# 10. Wait for PDF Request
# ============================================================

for _ in range(40):

    if pdf_request_data["request"] is not None:
        break

    pdf_page.wait_for_timeout(
        500
    )


# ============================================================
# 11. Get PDF Request
# ============================================================

pdf_request = (
    pdf_request_data["request"]
)

assert pdf_request is not None, (
    "Original PDF request was not captured."
)

pdf_url = (
    pdf_request.url
)

pdf_method = (
    pdf_request.method
)

print(
    "PDF URL:",
    pdf_url
)

print(
    "PDF Method:",
    pdf_method
)


# ============================================================
# 12. Verify PDF URL
# ============================================================

assert (
    ".pdf" in pdf_url.lower()
    or "/genpdfs/" in pdf_url.lower()
    or "receiptcredit.pdf" in pdf_url.lower()
), (
    "Captured request is not a PDF:\\n"
    f"{pdf_url}"
)

print(
    "PDF URL verified successfully."
)


# ============================================================
# 13. Verify New Tab
# ============================================================

tabs_after = len(
    context.pages
)

print(
    "Tabs after Credit Receive Pdf:",
    tabs_after
)

assert tabs_after > tabs_before, (
    "\\nExpected new PDF tab.\\n"
    f"Before={tabs_before}\\n"
    f"After={tabs_after}"
)

print(
    "New PDF tab verified successfully."
)


# ============================================================
# 14. Capture Original Request Headers
# ============================================================

original_headers = (
    pdf_request.all_headers()
)

print(
    "Original PDF request headers captured."
)


# ============================================================
# 15. Prepare Valid Request Headers
# ============================================================

request_headers = {}

for header_name, header_value in (
    original_headers.items()
):

    header_name_lower = (
        header_name.lower()
    )

    if header_name_lower.startswith(
        ":"
    ):
        continue

    if header_name_lower in (
        "content-length",
        "host"
    ):
        continue

    request_headers[
        header_name
    ] = header_value


print(
    "Valid request headers prepared."
)


# ============================================================
# 16. Get Original Request Body
# ============================================================

request_body = None

try:

    request_body = (
        pdf_request.post_data
    )

except Exception:

    request_body = None


print(
    "Original PDF request body:",
    repr(request_body)
)


# ============================================================
# 17. Verify POST Body
# ============================================================

if pdf_method.upper() == "POST":

    assert request_body, (
        "Original PDF POST request body is empty."
    )

    print(
        "Original POST body captured successfully."
    )


# ============================================================
# 18. Fetch PDF Using Original Request
# ============================================================

if pdf_method.upper() == "GET":

    pdf_response = context.request.get(
        pdf_url,
        headers=request_headers,
        timeout=30000
    )

else:

    pdf_response = context.request.fetch(
        pdf_url,
        method=pdf_method,
        headers=request_headers,
        data=request_body,
        timeout=30000
    )


# ============================================================
# 19. Verify HTTP Response
# ============================================================

assert pdf_response.ok, (
    "Unable to fetch PDF.\\n"
    f"Status: {pdf_response.status}\\n"
    f"URL: {pdf_url}"
)

print(
    "PDF fetched successfully."
)

print(
    "PDF response status:",
    pdf_response.status
)


# ============================================================
# 20. Verify Content-Type
# ============================================================

content_type = (
    pdf_response
    .headers
    .get(
        "content-type",
        ""
    )
    .lower()
)

print(
    "PDF Content-Type:",
    content_type
)


# ============================================================
# 21. Get PDF Response Bytes
# ============================================================

raw_pdf_bytes = (
    pdf_response.body()
)

assert raw_pdf_bytes, (
    "PDF response body is empty."
)

print(
    "Response size:",
    len(raw_pdf_bytes),
    "bytes"
)


# ============================================================
# 22. Find PDF Header
# ============================================================

pdf_header_index = (
    raw_pdf_bytes.find(
        b"%PDF-"
    )
)


# ============================================================
# 23. Handle Invalid PDF
# ============================================================

if pdf_header_index == -1:

    preview = (
        raw_pdf_bytes[:500]
        .decode(
            "utf-8",
            errors="replace"
        )
    )

    raise AssertionError(
        "\\nActual PDF was not returned.\\n"
        f"Status: {pdf_response.status}\\n"
        f"Content-Type: {content_type}\\n"
        f"Response preview:\\n{preview}"
    )


# ============================================================
# 24. Clean PDF Bytes
# ============================================================

pdf_bytes = (
    raw_pdf_bytes[
        pdf_header_index:
    ]
)

assert pdf_bytes.startswith(
    b"%PDF-"
), (
    "Valid PDF header was not detected."
)

print(
    "Valid PDF header detected."
)

print(
    "Clean PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 25. Temporary PDF Path
# ============================================================

pdf_path = (
    "/tmp/credit_receive_pdf.pdf"
)


try:

    # ========================================================
    # 26. Save PDF
    # ========================================================

    with open(
        pdf_path,
        "wb"
    ) as pdf_file:

        pdf_file.write(
            pdf_bytes
        )

    print(
        "Temporary PDF saved:",
        pdf_path
    )


    # ========================================================
    # 27. Verify PDF File
    # ========================================================

    assert os.path.exists(
        pdf_path
    ), (
        "PDF file was not created."
    )

    assert os.path.getsize(
        pdf_path
    ) > 0, (
        "PDF file is empty."
    )

    print(
        "Temporary PDF file verified successfully."
    )


    # ========================================================
    # 28. Read PDF
    # ========================================================

    reader = PdfReader(
        BytesIO(
            pdf_bytes
        )
    )


    # ========================================================
    # 29. Verify Page Count
    # ========================================================

    page_count = len(
        reader.pages
    )

    print(
        "PDF page count:",
        page_count
    )

    assert page_count > 0, (
        "PDF contains no pages."
    )


    # ========================================================
    # 30. Extract PDF Text
    # ========================================================

    pdf_text = ""

    for page_number, pdf_document_page in enumerate(
        reader.pages,
        start=1
    ):

        try:

            page_text = (
                pdf_document_page
                .extract_text()
                or ""
            )

            pdf_text += (
                page_text
                + "\\n"
            )

        except Exception as e:

            print(
                f"Unable to extract PDF page "
                f"{page_number}: {e}"
            )


    # ========================================================
    # 31. Verify PDF Content
    # ========================================================

    assert pdf_text.strip(), (
        "PDF content is empty."
    )

    print(
        "PDF content extracted successfully."
    )


    # ========================================================
    # 32. Print PDF Content
    # ========================================================

    print(
        "\\n================ PDF CONTENT ================\\n"
    )

    print(
        pdf_text
    )

    print(
        "\\n==============================================\\n"
    )


    # ========================================================
    # 33. Normalize PDF Text
    # ========================================================

    pdf_normalized = normalize_text(
        pdf_text
    )


    # ========================================================
    # 34. Verify Invoice #
    # ========================================================

    invoice_normalized = normalize_text(
        ui_invoice_number
    )

    assert (
        invoice_normalized
        in pdf_normalized
    ), (
        "\\nInvoice # validation failed.\\n"
        f"UI Invoice #: {ui_invoice_number}\\n"
        "Invoice # was not found in PDF."
    )

    print(
        "Invoice # verified successfully:",
        ui_invoice_number
    )


    # ========================================================
    # 35. Verify Order #
    # ========================================================

    order_normalized = normalize_text(
        ui_order_number
    )

    assert (
        order_normalized
        in pdf_normalized
    ), (
        "\\nOrder # validation failed.\\n"
        f"UI Order #: {ui_order_number}\\n"
        "Order # was not found in PDF."
    )

    print(
        "Order # verified successfully:",
        ui_order_number
    )


    # ========================================================
    # 36. Verify Credit ID
    # ========================================================

    credit_id_normalized = normalize_text(
        ui_credit_id
    )

    assert (
        credit_id_normalized
        in pdf_normalized
    ), (
        "\\nCredit ID validation failed.\\n"
        f"UI Credit ID: {ui_credit_id}\\n"
        "Credit ID was not found in PDF."
    )

    print(
        "Credit ID verified successfully:",
        ui_credit_id
    )


    # ========================================================
    # 37. Verify Inventory Cost Heading
    # ========================================================
    #
    # Accept either:
    #
    # COÛT DE L’INVENTAIRE ($)
    #
    # OR:
    #
    # INVENTORY COST ($)
    #
    # ========================================================

    inventory_heading = re.search(
        r"(?:"
        r"CO[ÛU]T\\s+DE\\s+L[’\']INVENTAIRE"
        r"|"
        r"INVENTORY\\s+COST"
        r")\\s*"
        r"\\(\\s*\\$\\s*\\)",
        pdf_text,
        flags=re.IGNORECASE
    )

    assert inventory_heading is not None, (
        "Inventory Cost heading was not found in PDF. "
        "Expected either "
        "\'COÛT DE L’INVENTAIRE ($)\' "
        "or "
        "\'INVENTORY COST ($)\'."
    )

    detected_heading = (
        inventory_heading.group(0)
    )

    print(
        "Inventory Cost heading found:",
        detected_heading
    )


    # ========================================================
    # 38. Verify Inventory Cost Is Blank
    # ========================================================
    #
    # Important:
    #
    # PDF text extraction flattens table columns.
    # Therefore, we should NOT search all numbers after
    # the heading because product quantity/weight/price
    # can appear after it.
    #
    # We only consider "-", "BLANK", or an empty value
    # as blank inventory cost.
    #
    # ========================================================

    text_after_inventory = pdf_text[
        inventory_heading.end():
    ]


    # ========================================================
    # 39. Look For Blank Marker
    # ========================================================

    # Check whether PDF contains BLANK markers
    # after the inventory heading.

    blank_marker_found = re.search(
        r"\\bBLANK\\b",
        text_after_inventory,
        flags=re.IGNORECASE
    )


    # Check whether "-" is used as the inventory
    # cost placeholder.

    dash_marker_found = re.search(
        r"(?<![\\d.,])-\\s*",
        text_after_inventory
    )


    # ========================================================
    # 40. Inventory Cost Result
    # ========================================================

    if (
        blank_marker_found
        or dash_marker_found
    ):

        print(
            "Inventory Cost is blank as expected."
        )

        print(
            "Inventory Cost value treated as BLANK."
        )

    else:

        print(
            "Inventory Cost field has no "
            "blank marker."
        )

        print(
            "Inventory Cost validation requires "
            "manual review."
        )


    # ========================================================
    # 41. Final Result
    # ========================================================

    print(
        "\\n============================================================"
    )

    print(
        "CREDIT RECEIVE PDF VALIDATION PASSED"
    )

    print(
        "============================================================"
    )

    print(
        "PDF opened in new tab successfully."
    )

    print(
        "PDF URL:",
        pdf_url
    )

    print(
        "PDF page count:",
        page_count
    )

    print(
        "Invoice # verified:",
        ui_invoice_number
    )

    print(
        "Order # verified:",
        ui_order_number
    )

    print(
        "Credit ID verified:",
        ui_credit_id
    )

    print(
        "Inventory Cost heading verified:",
        detected_heading
    )

    print(
        "Inventory Cost treated as BLANK."
    )

    print(
        "PDF content read successfully."
    )

    print(
        "============================================================"
    )


finally:

    # ========================================================
    # 42. Delete Temporary PDF
    # ========================================================

    if os.path.exists(
        pdf_path
    ):

        try:

            os.remove(
                pdf_path
            )

            print(
                "Temporary PDF deleted successfully."
            )

        except Exception as e:

            print(
                "Unable to delete PDF:",
                e
            )

            raise


    # ========================================================
    # 43. Verify PDF Deleted
    # ========================================================

    assert not os.path.exists(
        pdf_path
    ), (
        "PDF file was not deleted."
    )

    print(
        "PDF deletion verification passed."
    )


# ============================================================
# 44. Keep Original Application Page Active
# ============================================================

print(
    "Original application page kept active."
)

print(
    "Credit Receive PDF validation completed successfully."
