(20612,375,'custom','validate Qty picked should match shop order qty added on shop order.','Qty Picked','from playwright.sync_api import expect

# Get previously stored S/O Qty (PCS)
so_qty = get_var("so_qty")

# Capture Qty Picked from the 3rd row
qty_picked = page.locator(
    "xpath=//div[@data-id=\'3\' and @data-rowindex=\'2\']//div[@data-field=\'poQtyIntransit\']"
).get_attribute("title")

print("S/O Qty (PCS):", so_qty)
print("Qty Picked:", qty_picked)

# Compare Qty Picked with S/O Qty
assert float(qty_picked) == float(so_qty), (
    f"Qty Picked ({qty_picked}) does not match "
    f"S/O Qty (PCS) ({so_qty})"
)','2026-08-16 17:38:24','2026-09-09 07:35:14','user','User','PENDING',163,1),
