text = shipment_text_locator.inner_text().strip()

shipment_id = re.search(r"Planned In Shipment\\s+(\\d+)", text).group(1)

set_var("shipment_id", shipment_id)

print(shipment_id)','2026-08-17 07:48:31','2026-09-08 10:35:12','API_USER','User','PENDING',103,1),
