    row = page.locator(
        f"//div[@role=\'row\'][.//div[@data-field=\'formattedSeqId\' and normalize-space()=\'{item_number}\']]"
    )

    expect(row).to_be_visible()

    qty_received_pcs = row.locator(
        ".//div[@data-field=\'qtyReceivedinPcs\']"
    )

    expect(qty_received_pcs).to_have_text(expected_qty)','2026-08-17 07:48:31','2026-09-08 10:35:58','API_USER','User','PENDING',171,1),
