(20914,385,'custom','Verify CSV download, remove data above the header and rows after first 5 records, verify headers and adjustment values, create and verify XLS, navigate to Admin/Manage Configuration, upload XLS, verify success message, and delete CSV/XLS files.','Assertion','import os
import csv
import xlwt

# ==================================================
# 1. Export Inventory Summary Report as CSV
# ==================================================

export_button = page.locator(
    "xpath=//span[normalize-space()=\'Export as CSV\']"
)

expect(
    export_button
).to_be_visible(timeout=10000)

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# ==================================================
# 2. Download Information
# ==================================================

filename = download.suggested_filename

print(
    "Filename:",
    filename
)

# ==================================================
# 3. Download Location
# ==================================================

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(
    file_path
)

print(
    "Saved file:",
    file_path
)

# ==================================================
# 4. Verify CSV
# ==================================================

assert os.path.exists(
    file_path
), (
    f"Downloaded file was not saved: {file_path}"
)

assert os.path.getsize(
    file_path
) > 0, (
    f"Downloaded file is empty: {file_path}"
)

assert filename.lower().endswith(
    ".csv"
), (
    f"Expected CSV file, but downloaded: {filename}"
)

print(
    "SUCCESS: Inventory Summary Report CSV "
    "downloaded successfully."
)

# ==================================================
# 5. Read Original CSV
# ==================================================

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)

    rows = list(reader)

assert len(rows) > 0, (
    "Inventory Summary Report CSV "
    "does not contain any data."
)

print(
    "Original CSV rows:",
    len(rows)
)

# ==================================================
# 6. Find Header Row Automatically
# ==================================================

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip().strip(\'="\')
        for column in row
    ]

    if (
        "Product Type" in cleaned_row
        and "Product ID" in cleaned_row
        and "Description" in cleaned_row
        and "Location" in cleaned_row
        and "Current Stock" in cleaned_row
    ):
        header_row_index = index
        break

assert header_row_index is not None, (
    "Inventory Summary Report column "
    "header row was not found."
)

print(
    "Column header found at row:",
    header_row_index + 1
)

# ==================================================
# 7. Get Original Column Names
# ==================================================

headers = [
    column.strip().strip(\'="\')
    for column in rows[header_row_index]
]

print(
    "Total columns:",
    len(headers)
)

# ==================================================
# 8. Rename ONLY Required Adjustment Columns
#
# Final column names:
#
# Adjust Price
# Adjust Grade
# adjust Stock type
# Adjust Bulk TFR FRT Cost
# Adjust PO Transit FRT Cost
# ==================================================

column_rename_map = {
    "Adjusted Price":
        "Adjust Price",

    "Adjusted Grade":
        "Adjust Grade",

    "Adjust Stock Type":
        "adjust Stock type",

    "Adjust Bulk TFR FRT Cost":
        "Adjust Bulk TFR FRT Cost",

    "Adjust PO Transit FRT Cost":
        "Adjust PO Transit FRT Cost"
}

headers = [
    column_rename_map.get(
        column,
        column
    )
    for column in headers
]

print(
    "SUCCESS: Required adjustment "
    "column names updated."
)

# ==================================================
# 9. Get Data Rows Below Header
# ==================================================

data_rows = rows[
    header_row_index + 1:
]

data_rows = [
    row
    for row in data_rows
    if any(
        cell.strip()
        for cell in row
    )
]

print(
    "Original data rows:",
    len(data_rows)
)

# ==================================================
# 10. Keep ONLY First 5 Data Rows
# ==================================================

first_five_rows = data_rows[:5]

assert len(first_five_rows) == 5, (
    f"Expected exactly 5 data rows, "
    f"but found {len(first_five_rows)}."
)

print(
    "Rows retained:",
    len(first_five_rows)
)

# ==================================================
# 11. Create Filtered CSV
# Header + ONLY 5 Data Rows
# ==================================================

final_rows = [
    headers
] + first_five_rows

temp_file_path = (
    file_path + ".tmp"
)

with open(
    temp_file_path,
    mode="w",
    encoding="utf-8-sig",
    newline=""
) as file:

    writer = csv.writer(file)

    writer.writerows(
        final_rows
    )

os.replace(
    temp_file_path,
    file_path
)

print(
    "SUCCESS: Filtered CSV saved:",
    file_path
)

# ==================================================
# 12. Read Final CSV
# ==================================================

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    final_reader = csv.reader(file)

    final_rows = list(
        final_reader
    )

# ==================================================
# 13. Verify Final CSV Structure
# ==================================================

assert len(final_rows) == 6, (
    f"Expected exactly 6 rows "
    f"(1 header + 5 data rows), "
    f"but found {len(final_rows)} rows."
)

print(
    "SUCCESS: Final CSV contains "
    "1 header row + 5 data rows."
)

# ==================================================
# 14. Verify Headers
# ==================================================

final_headers = [
    column.strip().strip(\'="\')
    for column in final_rows[0]
]

assert final_headers == headers, (
    "Column headers were changed unexpectedly."
)

print(
    "SUCCESS: All column names are present."
)

# ==================================================
# 15. Get Final Data Rows
# ==================================================

final_data_rows = final_rows[1:]

assert len(final_data_rows) == 5, (
    f"Expected exactly 5 data rows, "
    f"but found {len(final_data_rows)}."
)

print(
    "SUCCESS: Exactly 5 data rows are present."
)

# ==================================================
# 16. Verify Every Row Has Same Column Count
# ==================================================

for row_number, row in enumerate(
    final_data_rows,
    start=1
):

    assert len(row) == len(final_headers), (
        f"Column count mismatch at data row "
        f"{row_number}. "
        f"Expected {len(final_headers)} columns, "
        f"but found {len(row)}."
    )

print(
    "SUCCESS: All 5 data rows contain "
    "the correct number of columns."
)

# ==================================================
# 17. Required Adjustment Columns
# ==================================================

required_columns = [
    "Adjust Price",
    "Adjust Grade",
    "adjust Stock type",
    "Adjust Bulk TFR FRT Cost",
    "Adjust PO Transit FRT Cost"
]

for column_name in required_columns:

    assert column_name in final_headers, (
        f"Required column \'{column_name}\' "
        "was not found."
    )

print(
    "SUCCESS: All required adjustment "
    "columns are present."
)

# ==================================================
# 18. Get Exact Column Indexes
# ==================================================

adjust_price_index = final_headers.index(
    "Adjust Price"
)

adjust_grade_index = final_headers.index(
    "Adjust Grade"
)

adjust_stock_type_index = final_headers.index(
    "adjust Stock type"
)

adjust_bulk_tfr_index = final_headers.index(
    "Adjust Bulk TFR FRT Cost"
)

adjust_po_transit_index = final_headers.index(
    "Adjust PO Transit FRT Cost"
)

# ==================================================
# 19. Enter Adjustment Values
#
# EXACT REQUESTED SEQUENCE
# ==================================================

# Row 1
final_data_rows[0][
    adjust_price_index
] = "100"

# Row 2
final_data_rows[1][
    adjust_grade_index
] = "10"

# Row 3
final_data_rows[2][
    adjust_stock_type_index
] = "Prime"

# Row 4
final_data_rows[3][
    adjust_bulk_tfr_index
] = "30"

# Row 5
final_data_rows[4][
    adjust_po_transit_index
] = "20"

print(
    "Row 1 -> Adjust Price = 100"
)

print(
    "Row 2 -> Adjust Grade = 10"
)

print(
    "Row 3 -> adjust Stock type = Prime"
)

print(
    "Row 4 -> Adjust Bulk TFR FRT Cost = 30"
)

print(
    "Row 5 -> Adjust PO Transit FRT Cost = 20"
)

# ==================================================
# 20. Rebuild Final CSV
# ==================================================

final_rows = [
    final_headers
] + final_data_rows

# ==================================================
# 21. Save Updated CSV
# ==================================================

temp_file_path = (
    file_path + ".tmp"
)

with open(
    temp_file_path,
    mode="w",
    encoding="utf-8-sig",
    newline=""
) as file:

    writer = csv.writer(file)

    writer.writerows(
        final_rows
    )

os.replace(
    temp_file_path,
    file_path
)

print(
    "SUCCESS: Adjustment values saved "
    "into CSV."
)

# ==================================================
# 22. Verify Exact Adjustment Values
# ==================================================

assert final_data_rows[0][
    adjust_price_index
] == "100"

assert final_data_rows[1][
    adjust_grade_index
] == "10"

assert final_data_rows[2][
    adjust_stock_type_index
] == "Prime"

assert final_data_rows[3][
    adjust_bulk_tfr_index
] == "30"

assert final_data_rows[4][
    adjust_po_transit_index
] == "20"

print(
    "SUCCESS: All adjustment values "
    "were verified."
)

# ==================================================
# 23. Save as Excel 97-2003 XLS
# ==================================================

xls_file_path = os.path.join(
    download_dir,
    "Inventory Summary Report.xls"
)

workbook = xlwt.Workbook()

worksheet = workbook.add_sheet(
    "Inventory Summary Report"
)

# ==================================================
# 24. Write Headers
# ==================================================

for column_index, header in enumerate(
    final_headers
):

    worksheet.write(
        0,
        column_index,
        header
    )

# ==================================================
# 25. Write ONLY 5 Data Rows
# ==================================================

for row_index, row in enumerate(
    final_data_rows,
    start=1
):

    for column_index, value in enumerate(
        row
    ):

        worksheet.write(
            row_index,
            column_index,
            value
        )

# ==================================================
# 26. Save XLS
# ==================================================

workbook.save(
    xls_file_path
)

print(
    "SUCCESS: Inventory Summary Report saved "
    "as Excel 97-2003 XLS."
)

print(
    "XLS file:",
    xls_file_path
)

# ==================================================
# 27. Verify XLS
# ==================================================

assert os.path.exists(
    xls_file_path
), (
    f"XLS file was not saved: {xls_file_path}"
)

assert os.path.getsize(
    xls_file_path
) > 0, (
    f"XLS file is empty: {xls_file_path}"
)

print(
    "SUCCESS: XLS file exists and is not empty."
)

# ==================================================
# 28. Click Admin
# ==================================================

admin_menu = page.get_by_text(
    "Admin",
    exact=True
).last

expect(
    admin_menu
).to_be_visible(
    timeout=10000
)

admin_menu.click(
    force=True
)

print(
    "SUCCESS: Admin clicked."
)

# ==================================================
# 29. Click Manage Configuration
# ==================================================

manage_configuration = page.get_by_text(
    "Manage Configuration",
    exact=True
).last

expect(
    manage_configuration
).to_be_visible(
    timeout=10000
)

manage_configuration.scroll_into_view_if_needed()

manage_configuration.click(
    force=True
)

print(
    "SUCCESS: Manage Configuration clicked."
)

# ==================================================
# 30. Wait for Manage Configuration
# ==================================================

page.wait_for_timeout(
    1500
)

# ==================================================
# 31. Verify XLS Before Upload
# ==================================================

assert os.path.exists(
    xls_file_path
), (
    f"XLS file does not exist: {xls_file_path}"
)

assert os.path.getsize(
    xls_file_path
) > 0, (
    f"XLS file is empty: {xls_file_path}"
)

print(
    "XLS file ready for upload:",
    xls_file_path
)

# ==================================================
# 32. Locate Bulk Adjustment Choose File
# ==================================================

choose_file = page.locator(
    "xpath=//tr[.//p[normalize-space()=\'Upload File For Bulk Adjustment\']]"
    "//h6[normalize-space()=\'Choose File\']"
)

expect(
    choose_file
).to_be_visible(
    timeout=10000
)

print(
    "SUCCESS: Bulk Adjustment Choose File "
    "is visible."
)

# ==================================================
# 33. Locate File Input
# ==================================================

file_input = choose_file.locator(
    "xpath=ancestor::div[@role=\'presentation\'][1]"
    "//input[@type=\'file\']"
)

assert file_input.count() == 1, (
    "Expected exactly one file input "
    "for Bulk Adjustment Choose File."
)

print(
    "SUCCESS: Bulk Adjustment file input found."
)

# ==================================================
# 34. Select XLS File
# ==================================================

file_input.set_input_files(
    xls_file_path
)

print(
    "SUCCESS: Inventory Summary Report.xls "
    "selected for Bulk Adjustment upload."
)

# ==================================================
# 35. Locate Upload Button
# ==================================================

upload_button = page.locator(
    "xpath=//tr[.//p[normalize-space()=\'Upload File For Bulk Adjustment\']]"
    "//button[normalize-space()=\'Upload\']"
)

expect(
    upload_button
).to_be_visible(
    timeout=10000
)

expect(
    upload_button
).to_be_enabled(
    timeout=10000
)

print(
    "SUCCESS: Bulk Adjustment Upload button found."
)

# ==================================================
# 36. Click Upload
# ==================================================

upload_button.click()

print(
    "SUCCESS: Upload button clicked."
)

# ==================================================
# 37. Wait Until Success Toast Appears
# ==================================================

success_toast = page.get_by_text(
    "Transaction completed successfully.",
    exact=True
)

expect(
    success_toast
).to_be_visible(
    timeout=30000
)

print(
    "SUCCESS: Transaction completed successfully."
)

# ==================================================
# 38. Delete CSV File
# ==================================================

assert os.path.exists(
    file_path
), (
    f"CSV file does not exist before deletion: "
    f"{file_path}"
)

os.remove(
    file_path
)

assert not os.path.exists(
    file_path
), (
    f"CSV file was not deleted: {file_path}"
)

print(
    "SUCCESS: Inventory Summary Report.csv "
    "was deleted."
)

# ==================================================
# 39. Delete XLS File
# ==================================================

assert os.path.exists(
    xls_file_path
), (
    f"XLS file does not exist before deletion: "
    f"{xls_file_path}"
)

os.remove(
    xls_file_path
)

assert not os.path.exists(
    xls_file_path
), (
    f"XLS file was not deleted: {xls_file_path}"
)

print(
    "SUCCESS: Inventory Summary Report.xls "
    "was deleted."
)

# ==================================================
# Final Result
# ==================================================

print(
    "\\nSUCCESS: Inventory Summary Report workflow "
    "completed successfully."
)

print(
    "CSV downloaded -> header detected -> first 5 "
    "rows retained -> required columns renamed -> "
    "values entered in exact sequence -> XLS 97-2003 "
    "created -> XLS verified -> Admin -> Manage "
    "Configuration -> Choose File -> XLS selected -> "
    "Upload clicked -> waited until Transaction "
    "completed successfully -> CSV deleted -> "
    "XLS deleted."
