    "wb"
) as downloaded_file:

    downloaded_file.write(
        pdf_bytes
    )


print(
    "PDF saved successfully:"
)

print(
    file_path
)


# ============================================================
# 26. Verify Downloaded File Exists
# ============================================================

assert os.path.exists(
    file_path
), (
    f"Downloaded PDF does not exist:\\n"
    f"{file_path}"
)

print(
    "Downloaded PDF file exists."
)


# ============================================================
# 27. Verify Downloaded File Size
# ============================================================

downloaded_file_size = (
    os.path.getsize(
        file_path
    )
)

assert downloaded_file_size > 0, (
    "Downloaded PDF file is empty."
)

print(
    "Downloaded PDF size:",
    downloaded_file_size,
    "bytes"
)


# ============================================================
# 28. Read Downloaded PDF
# ============================================================

with open(
    file_path,
    "rb"
) as downloaded_file:

    downloaded_bytes = (
        downloaded_file.read()
    )


# ============================================================
# 29. Verify Downloaded PDF Header
# ============================================================

assert downloaded_bytes.startswith(
    b"%PDF"
), (
    "Downloaded file is not a valid PDF."
)

print(
    "Downloaded file is a valid PDF."
)


# ============================================================
# 30. Verify Downloaded Bytes Match PDF Opened in Tab
# ============================================================

assert (
    downloaded_bytes
    == pdf_bytes
), (
    "\\nDownloaded PDF bytes do not match "
    "the PDF response opened in the new tab."
)

print(
    "Downloaded PDF bytes match the PDF opened in the new tab."
)


# ============================================================
# 31. Read Downloaded PDF Using pypdf
# ============================================================

downloaded_reader = PdfReader(
    BytesIO(
        downloaded_bytes
    )
)

assert len(downloaded_reader.pages) > 0, (
    "Downloaded PDF contains no pages."
)


# ============================================================
# 32. Extract Downloaded PDF Text
# ============================================================

downloaded_pdf_text_parts = []

for pdf_document_page in downloaded_reader.pages:

    try:

        page_text = (
            pdf_document_page.extract_text()
            or ""
        )

        downloaded_pdf_text_parts.append(
            page_text
        )

    except Exception as e:

        print(
            "Unable to extract downloaded PDF page:",
            e
        )


downloaded_pdf_text = "\\n".join(
    downloaded_pdf_text_parts
)

assert downloaded_pdf_text.strip(), (
    "Downloaded PDF text is empty."
)


# ============================================================
# 33. Verify Downloaded PDF Transit Number
# ============================================================

normalized_downloaded_pdf_text = normalize_pdf_text(
    downloaded_pdf_text
)

assert normalized_ui_transit_number in (
    normalized_downloaded_pdf_text
), (
    "\\nDownloaded PDF Transit Number verification failed.\\n"
    f"Expected Transit Number: "
    f"{expected_transit_number}\\n"
    f"Downloaded PDF:\\n"
    f"{downloaded_pdf_text}"
)

print(
