assert normalized_ui_description in (
    normalized_downloaded_pdf_text
), (
    "\\nDownloaded PDF product description verification failed.\\n"
    f"Expected UI description:\\n"
    f"{expected_product_description}\\n\\n"
    f"Downloaded PDF:\\n"
    f"{downloaded_pdf_text}"
)

print(
    "Downloaded PDF product description verification PASSED."
)


# ============================================================
# 35. Verify PDF and Downloaded PDF Content Match
# ============================================================

assert (
    normalized_pdf_text
    == normalized_downloaded_pdf_text
), (
    "\\nPDF opened in new tab and downloaded PDF "
