(21431,149,'custom','Click Print Intransit and verify the pdf should open in a new tab and the user should be able to download pdf from there. Also verify downloaded pdf have same product description as in the UI for first row and same Transit Number as in the UI with Transit ID','Intransit PDF','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None
response_listener_registered = False


# ============================================================
# 1. Get Dynamic Transit ID from Intransit Details
# ============================================================

transit_header = page.locator(
    "h6",
    has_text="Intransit Details"
).first

expect(
    transit_header
).to_be_visible(timeout=10000)

transit_header_text = transit_header.inner_text()

print(
    "\\nIntransit header from UI:",
    transit_header_text
)


# Example:
#
# Intransit Details (#231237)
#
# Transit ID is captured dynamically.
# It is NOT hardcoded.

transit_match = re.search(
    r"Intransit\\s+Details\\s*\\(\\s*#?\\s*(\\d+)\\s*\\)",
    transit_header_text,
    re.IGNORECASE
)

assert transit_match, (
    "Transit ID was not found in Intransit Details header.\\n"
    f"Header: {transit_header_text}"
)

ui_transit_number = transit_match.group(1)

print(
    "Transit Number from UI:",
    ui_transit_number
)


# ============================================================
# 2. Get Product Description from First Row
# ============================================================

product_description_locator = page.locator(
    "//div[@data-id=\'1\' and @data-rowindex=\'0\']"
    "//div[@data-field=\'internalName\']"
)

expect(
    product_description_locator
).to_be_visible(timeout=10000)

ui_product_description = (
    product_description_locator.inner_text()
)

ui_product_description_normalized = " ".join(
    ui_product_description.split()
)

print(
    "\\nProduct Description from UI:",
    ui_product_description
)

print(
    "Normalized Product Description:",
    ui_product_description_normalized
)

assert ui_product_description_normalized, (
    "Product Description from first row is empty."
)


# ============================================================
# 3. Locate Print Button
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(timeout=10000)

expect(
    print_button
).to_be_enabled(timeout=10000)

print(
    "\\nPrint button is visible and enabled."
)


# ============================================================
# 4. Count Tabs Before Clicking Print
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before clicking Print:",
    tabs_before
)


# ============================================================
# 5. PDF Response Information
#
# IMPORTANT:
#
# We capture ONLY the HTTP PDF URL.
#
# We DO NOT call response.body() on the browser
# navigation response.
#
# This avoids:
#
# Network.getResponseBody:
# No resource with given identifier found
# ============================================================

pdf_info = {
    "url": None,
    "status": None,
    "content_type": None
}


def capture_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )


        # ----------------------------------------------------
        # Only HTTP/HTTPS responses
        # ----------------------------------------------------

        is_http_url = (
            response_url.startswith("http://")
            or response_url.startswith("https://")
        )

        if not is_http_url:
            return


        # ----------------------------------------------------
        # Detect PDF response
        # ----------------------------------------------------

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        is_generated_pdf = (
            "/genPdfs/" in response_url
            and ".pdf" in response_url.lower()
        )

        if not (
            is_pdf_content
            or is_generated_pdf
        ):
            return


        # ----------------------------------------------------
        # Ignore duplicate PDF responses
        # ----------------------------------------------------

        if pdf_info["url"] is not None:
            return


        pdf_info["url"] = response_url
        pdf_info["status"] = response.status
        pdf_info["content_type"] = content_type


        print(
            "\\n================================================"
        )

        print(
            "Print Intransit PDF response detected."
        )

        print(
            "PDF URL:",
            response_url
        )

        print(
            "HTTP Status:",
            response.status
        )

        print(
            "Content-Type:",
            content_type
        )

        print(
            "PDF URL captured successfully."
        )

        print(
            "================================================\\n"
        )


    except Exception as e:

        print(
            "Error while capturing PDF response:",
            e
        )


# ============================================================
# 6. Register Context-Level Response Listener
# ============================================================

context.on(
    "response",
    capture_pdf_response
)

response_listener_registered = True


try:

    # ========================================================
    # 7. Click Print
    # ========================================================

    print(
        "\\nClicking Print..."
    )

    print_button.click(
        force=True
    )

    print(
        "Print button clicked successfully."
    )


    # ========================================================
    # 8. Locate Print Intransit Menu
    # ========================================================

    print_intransit = page.locator(
        "//li[@role=\'menuitem\' and contains(.,\'Print Intransit\')]"
    )

    expect(
        print_intransit
    ).to_be_visible(timeout=10000)

    print(
        "Print Intransit menu is visible."
    )


    # ========================================================
    # 9. Click Print Intransit and Capture New Tab
    # ========================================================

    print(
        "\\nClicking Print Intransit..."
    )


    try:

        with context.expect_page(
            timeout=30000
        ) as new_page_info:

            print_intransit.click(
                force=True
            )


        pdf_page = new_page_info.value


        print(
            "Print Intransit clicked successfully."
        )

        print(
            "New PDF tab detected."
        )


    except Exception as e:

        raise AssertionError(
            "\\nPrint Intransit was clicked, "
            "but a new PDF tab was not detected.\\n"
            f"Error: {e}"
        )


    # ========================================================
    # 10. Wait for PDF Tab
    # ========================================================

    try:

        pdf_page.wait_for_load_state(
            "domcontentloaded",
            timeout=30000
        )

    except Exception:

        # Chrome built-in PDF viewer may not expose a
        # normal DOM load state. This is acceptable.
        pass


    print(
        "PDF tab URL:",
        pdf_page.url
    )


    # ========================================================
    # 11. Wait for PDF HTTP Response
    #
    # The response can happen before or after the new tab.
    # ========================================================

    timeout_ms = 30000
    poll_interval_ms = 250

    elapsed = 0


    while (
        pdf_info["url"] is None
        and elapsed < timeout_ms
    ):

        page.wait_for_timeout(
            poll_interval_ms
        )

        elapsed += poll_interval_ms


    # ========================================================
    # 12. Verify PDF Response Was Captured
    # ========================================================

    assert pdf_info["url"] is not None, (
        "\\nPrint Intransit PDF URL was not captured.\\n"
        "The new tab opened, but no HTTP PDF response "
        "was detected."
    )


    pdf_url = pdf_info["url"]

    pdf_status = pdf_info["status"]

    pdf_content_type = pdf_info["content_type"]


    print(
        "\\n================ PDF RESPONSE ================\\n"
    )

    print(
        "PDF URL:",
        pdf_url
    )

    print(
        "HTTP Status:",
        pdf_status
    )

    print(
        "Content-Type:",
        pdf_content_type
    )

    print(
        "\\n==============================================\\n"
    )


    # ========================================================
