(21635,58,'custom','Click the Print button and then click Print Picklist button, and Verify Print picklist should be enabled and should be print in the new tab','Assertion','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO


# Step 1: Click Print button inside dialog
dialog_print_button = page.locator(
    "//*[@role=\'dialog\']//button[@id=\'print-button\']"
)

expect(
    dialog_print_button
).to_be_visible(timeout=10000)

dialog_print_button.click()

print("Dialog Print button clicked.")


# Step 2: Locate Print Picklist
print_button = page.locator(
    "//li[@role=\'menuitem\' and normalize-space()=\'Print Picklist\']"
)

expect(
    print_button
).to_be_visible(timeout=10000)

print("Print Picklist button found.")


# Step 3: Capture PDF response
pdf_data = {
    "bytes": None,
    "url": None
}


def handle_response(response):

    try:

        content_type = response.headers.get(
            "content-type",
            ""
        ).lower()

        if "application/pdf" in content_type:

            body = response.body()

            if body.startswith(b"%PDF"):

                pdf_data["bytes"] = body
                pdf_data["url"] = response.url

                print(
                    "PDF response captured:",
                    response.url
                )

    except Exception:
        pass


context.on(
    "response",
    handle_response
)


# Step 4: Click Print Picklist
print_button.click()

print("Print Picklist button clicked.")


# Step 5: Wait for PDF response
page.wait_for_timeout(5000)


# Step 6: Verify PDF captured
assert pdf_data["bytes"] is not None, (
    "PDF response was not captured."
)


# Step 7: Read PDF directly from memory
reader = PdfReader(
    BytesIO(pdf_data["bytes"])
)


# Step 8: Extract PDF text only
pdf_text = ""

for pdf_page_data in reader.pages:

    pdf_text += (
        pdf_page_data.extract_text()
        or ""
    )


# Step 9: Verify PDF content
assert pdf_text.strip(), (
    "PDF content is empty."
)


# Step 10: Print PDF text only
print(pdf_text)


# Step 11: Remove response listener
context.remove_listener(
