(21846,340,'custom','Click Print button and then Print BOL and Verify item quantity should show in BOL pdf','BOL PDF','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


def normalize_number(value):
    """
    Converts values such as:

        2
        2.0
        2.00
        2,00

    into:

        2
    """

    if value is None:
        return None

    value = str(value).strip()

    # Handle decimal comma
    value = value.replace(",", ".")

    try:

        number = float(value)

        if number.is_integer():
            return str(int(number))

        return f"{number:g}"

    except Exception:

        return value


