(21887,354,'custom','Scroll company name in viewport ','company name','scroller = page.locator(".MuiDataGrid-virtualScroller")
target = page.locator(\'.MuiDataGrid-virtualScrollerContent [data-field="companyName"]\')

for _ in range(40):
    if target.count() > 0:
        in_view = scroller.evaluate(
            """(el, cell) => {
                if (!cell) return false;
                const s = el.getBoundingClientRect();
                const c = cell.getBoundingClientRect();
                return c.left >= s.left && c.right <= s.right;
            }""",
            target.first.element_handle(),
        )
        if in_view:
            break

    at_end = scroller.evaluate(
        """el => {
            const max = el.scrollWidth - el.clientWidth;
            el.scrollLeft = Math.min(el.scrollLeft + 300, max);
            return el.scrollLeft >= max - 1;
        }"""
    )
    page.wait_for_timeout(100)

    if at_end and target.count() == 0:
        raise AssertionError("companyName column not found after scrolling to end")','2026-08-26 08:43:10','2026-08-26 12:38:45','user','User','PENDING',59,1),
